window.MEC_META={"version": "1.0.0", "reviewed": "2026-11-05", "source": "https://www.wko.at/ooe/bildung-lehre/fragenkatalog-kandidat-mec-h1.pdf", "chapters": {"D": 46, "E": 48}};
window.MEC_CARDS=[{"id":"D1","title":"Greifprinzip und Greiferauswahl","category":"Pneumatik","question":"Ordne Greifer nach ihrem Wirkprinzip, erläutere zwei Backenbauformen und begründe drei Kriterien für die Auswahl an einem Werkstück.","answer":[{"label":"Wirkprinzipien","text":"Eine sinnvolle Einteilung unterscheidet mechanische Greifer und haftende Greifer. Mechanische Greifer halten mit Fingern durch Reibung (Kraftschluss) oder durch passende Konturen (Formschluss). Zu haftenden Systemen gehören Vakuumgreifer und Magnetgreifer; Magnete setzen einen geeigneten ferromagnetischen Werkstoff voraus."},{"label":"Zwei Bauformen","text":"Beim Parallelgreifer bewegen sich die Backen geradlinig aufeinander zu. Das eignet sich für definierte Außen- und Innengriffe. Beim Winkelgreifer schwenken die Finger; der größere Öffnungsraum kann das Freigeben eines Werkstücks erleichtern. Pneumatisch oder elektrisch beschreibt dagegen die Antriebsart."},{"label":"Drei Auswahlkriterien","text":"Erstens zählen Masse, Schwerpunkt, Geometrie und Oberfläche des Werkstücks. Zweitens müssen Haltekraft und Fingerbelastung auch bei Beschleunigung, Bremsen und ungünstiger Reibung ausreichen. Drittens müssen Hub, Zugänglichkeit, Wiederholgenauigkeit und Umgebungsbedingungen zur Aufgabe passen; empfindliche Teile dürfen dabei nicht verformt werden."}],"mnemonic":"Erst Werkstück und Bewegung beurteilen, dann Greifprinzip, Kraft und Baugröße wählen.","pitfall":"Die statische Gewichtskraft allein genügt nicht zur Greiferauslegung; Beschleunigung und Reibung verändern die erforderliche Haltekraft.","keywords":["Greifer","Parallelgreifer","Winkelgreifer","Kraftschluss","Formschluss","Vakuum"],"sources":[{"label":"Festo: Auswahl eines Roboter-Greifers","url":"https://www.festo.com/ch/de/e/blog/in-practice/wie-sie-den-richtigen-roboter-greifer-auswaehlen-id_4159813"},{"label":"Festo: Pneumatische Greifer","url":"https://media.festo.com/media/276594_documentation.pdf?fwacid=b3f7f5f5de13b33f"}],"minutes":4,"pdfPage":2},{"id":"D2","title":"Gefährdungen durch Druckluft","category":"Sicherheit","question":"Erkläre mindestens zwei Gefährdungen und zwei Schutzmaßnahmen einer Pneumatikanlage und fasse die fünf Verhaltensregeln für befugtes Instandhaltungspersonal zusammen.","answer":[{"label":"Gefährdungen","text":"Unerwartete Zylinderbewegungen können quetschen oder scheren, etwa durch Restdruck, Ventilfehler oder wiederkehrende Energie. Gelöste Schläuche und fortgeschleuderte Teile können Personen treffen. Hinzu kommen Abluftlärm und die Gefahr absinkender Lasten bei Druckverlust."},{"label":"Schutzmaßnahmen","text":"Geeignete trennende oder überwachte Schutzeinrichtungen begrenzen den Zugang zu Bewegungen. Zur Anlage gehören außerdem eine passend ausgelegte Energieabschaltung mit Wiederanlaufschutz, kontrollierbarer Entlüftung und eine sichere Lastabstützung. Geeignete Schlauchbefestigungen, Sicherheitskupplungen und Schalldämpfer mindern weitere Gefährdungen."},{"label":"Fünf Verhaltensregeln","text":"Die Prüfungserklärung für Arbeiten nach Betriebsanleitung lautet: 1. Hochgehaltene Lasten und abrutschende Maschinenteile sicher absenken oder abstützen. 2. Die Steuerung ausschalten. 3. Sämtliche Energiequellen trennen und gegen Wiedereinschalten sichern. 4. Alle betroffenen Anlagenteile einschließlich eingeschlossener Druckräume drucklos machen lassen und den sicheren Zustand überprüfen; weitere gespeicherte Energie berücksichtigen. 5. Gefährdungen durch benachbarte oder verkettete Maschinen durch Abschalten oder Abschranken verhindern."}],"mnemonic":"Last sichern, Steuerung aus, Energie sichern, Restenergie prüfen, Nachbaranlagen beachten.","pitfall":"Ein ausgeschalteter Magnet oder eine Anzeige von 0 bar an einer Stelle beweist keine Druckfreiheit in allen eingeschlossenen Anlagenteilen.","keywords":["Restdruck","Quetschgefahr","Energieabschaltung","Wiederanlauf","Lastabstützung"],"sources":[{"label":"DGUV/IFA: Sicherer Umgang mit pneumatischen Anlagen, insbesondere fünf Verhaltensregeln","url":"https://www.dguv.de/medien/ifa/de/pra/hydraulik_pneumatik/pneumatische_anlagen.pdf"}],"minutes":4,"pdfPage":2},{"id":"D3","title":"Geführte und kolbenstangenlose Antriebe","category":"Pneumatik","question":"Welche Vorteile bringt eine zusätzliche Zylinderführung, was kennzeichnet einen kolbenstangenlosen Antrieb und wie unterscheiden sich dessen zwei gängige Kopplungsprinzipien?","answer":[{"label":"Nutzen einer Führung","text":"Eine passende Führung nimmt Querkräfte und Kippmomente auf und verhindert das Verdrehen des Schlittens. Das entlastet Kolbenstange und Dichtungen und verbessert die reproduzierbare Ausrichtung des Werkzeugs. Ein gewöhnlicher Kolbenstangenzylinder ist hauptsächlich für axiale Kräfte vorgesehen."},{"label":"Ohne ausfahrende Kolbenstange","text":"Bei einem kolbenstangenlosen Zylinder fährt ein außenliegender Schlitten entlang des Zylindergehäuses. Der innere Kolben treibt ihn an. Der Bauraum wächst dadurch weniger stark mit dem Hub als bei einem Zylinder mit ausfahrender Stange."},{"label":"Zwei Kopplungen","text":"Bei mechanischer Kopplung verbindet ein Mitnehmer den Kolben durch einen längs verlaufenden Gehäuseschlitz mit dem Schlitten; Dichtbänder verschließen den Schlitz. Bei magnetischer Kopplung übertragen Magnete die Bewegung durch ein geschlossenes Zylinderrohr. Diese Kopplung besitzt eine begrenzte übertragbare Kraft und kann bei Überlast entkoppeln."}],"mnemonic":"Die Führung trägt Querlasten; die Kopplung überträgt die Kolbenbewegung.","pitfall":"Kolbenstangenlos bedeutet weder unbegrenzt belastbar noch selbsttätig gegen Absinken gesichert.","keywords":["Linearführung","Querkräfte","Moment","Kolbenstangenlos","Magnetkopplung","Dichtband"],"sources":[{"label":"SMC: Kolbenstangenlose Zylinder und Kopplungsprinzipien","url":"https://www.smc.eu/de-de/produkte/kolbenstangenlose-antriebe~17914~nav"},{"label":"Festo: Magnetisch gekoppelte Zylinder","url":"https://www.festo.com/us/en/c/products/actuators-and-drives/pneumatic-cylinders/rodless-cylinders/magnetically-coupled-cylinders-id_pim385"},{"label":"Festo: Geführte Pneumatikzylinder","url":"https://www.festo.com/de/de/c/produkte/antriebe-aktuatoren/pneumatische-zylinder/fuehrungszylinder-id_pim219"}],"minutes":4,"pdfPage":3,"imagePage":25,"imagePages":[25]},{"id":"D4","title":"Legierungen und Messing","category":"Mechanik","question":"Erkläre, wie und warum eine Legierung entsteht, nenne zwei technische Anwendungen und beschreibe typische Merkmale einer Kupfer-Zink-Legierung.","answer":[{"label":"Legieren","text":"Beim Legieren werden mindestens zwei Elemente gezielt zu einem metallischen Werkstoff kombiniert; mindestens eines ist ein Metall. Häufig werden die Bestandteile in der Schmelze zusammengeführt und gleichmäßig verteilt. Beim Erstarren entsteht je nach Zusammensetzung ein Gefüge aus Mischkristallen oder mehreren Phasen. Ziel sind beispielsweise höhere Festigkeit, bessere Bearbeitbarkeit oder günstigere Korrosionseigenschaften."},{"label":"Zwei Anwendungen","text":"Kupfer mit Zink ergibt Messing, etwa für Armaturen und mechanische Drehteile. Kupfer mit Zinn ergibt Zinnbronze, beispielsweise für Lager- und Gleitteile. Die genaue Sorte richtet sich nach der Beanspruchung."},{"label":"Kupfer und Zink","text":"Messing ist typischerweise gelblich, gut verarbeitbar und bei passenden Sorten gut umformbar oder zerspanbar. Es ist meist fester als reines Kupfer und leitet Wärme und elektrischen Strom, jedoch schlechter als reines Kupfer. Seine Korrosionsbeständigkeit hängt von Legierung und Medium ab; bestimmte Bedingungen können Entzinkung oder Spannungsrisskorrosion auslösen."}],"mnemonic":"Eine Legierung wird auf Eigenschaften abgestimmt; Kupfer plus Zink heißt Messing.","pitfall":"Legieren ist kein bloßes Mischen fertiger Metallspäne, und Messing ist nicht gegen jedes Medium beständig.","keywords":["Legierung","Messing","Kupfer","Zink","Mischkristall","Bronze"],"sources":[{"label":"Kupferverband: Kupfer-Zink-Legierungen","url":"https://kupfer.de/kupferwerkstoffe/kupfer-legierungen/kupfer-zink-legierungen-messing/"},{"label":"Kupferverband: Kupfer-Legierungen","url":"https://kupfer.de/kupferwerkstoffe/kupfer-legierungen/"}],"minutes":4,"pdfPage":3},{"id":"D5","title":"Korrosion und Werkstoffwahl","category":"Mechanik","question":"Was geschieht bei Korrosion und welche Überlegungen zur Werkstoffauswahl können einen Korrosionsangriff verhindern oder ausreichend begrenzen?","answer":[{"label":"Reaktion mit der Umgebung","text":"Korrosion ist eine physikalisch-chemische Wechselwirkung zwischen einem Werkstoff und seiner Umgebung, die Eigenschaften verändert und die Funktion beeinträchtigen kann. Bei Metallen sind oft elektrochemische Vorgänge beteiligt. Rost ist ein Korrosionsprodukt von Eisen; nicht jede Korrosion ist Rost und nicht jeder Angriff ist sofort sichtbar."},{"label":"Passende Werkstoffe","text":"Der Werkstoff muss zum tatsächlichen Medium, seiner Konzentration, Temperatur und Feuchtigkeit passen. Geeignete nichtrostende Stähle, korrosionsbeständige Legierungen oder geeignete Kunststoffe können einen Angriff im vorgesehenen Einsatz vermeiden. Elektrisch leitend verbundene unterschiedliche Metalle sind bei vorhandenem Elektrolyten auf Kontaktkorrosion zu prüfen; geeignete Paarung oder elektrische Trennung helfen."},{"label":"Grenze der Aussage","text":"Eine pauschale Zusage „korrosionsfrei“ ist durch die Bezeichnung Edelstahl oder Kunststoff nicht möglich. Beständigkeitsdaten, konstruktiver Schutz und gegebenenfalls eine Beschichtung müssen gemeinsam zur Umgebung passen."}],"mnemonic":"Korrosionsbeständigkeit ergibt sich aus Werkstoff und Umgebung gemeinsam.","pitfall":"Edelstahl ist kein universeller Schutz gegen Chloride, Säuren und Spaltkorrosion.","keywords":["Korrosion","Rost","Elektrolyt","Kontaktkorrosion","Werkstoffwahl","Beständigkeit"],"sources":[{"label":"Fraunhofer IFAM: Korrosion FAQ","url":"https://www.ifam.fraunhofer.de/de/technologien/korrosion/korrosion-faq.html"},{"label":"BAM: Beständigkeitsbewertung","url":"https://tes.bam.de/gefahrgut/werkstoffbestaendigkeit/bestaendigkeitsbewertung"}],"minutes":4,"pdfPage":4},{"id":"D6","title":"Drei Kunststoffgruppen","category":"Mechanik","question":"Vergleiche Thermoplaste, Duroplaste und Elastomere hinsichtlich Molekülaufbau, Wärmeverhalten und typischer Verwendung.","answer":[{"label":"Thermoplaste","text":"Ihre langen Molekülketten sind nicht dauerhaft chemisch miteinander vernetzt. Sie werden beim Erwärmen weich beziehungsweise schmelzbar und erstarren beim Abkühlen erneut. Innerhalb zulässiger Temperaturgrenzen lassen sie sich deshalb mehrfach formen und häufig schweißen. Beispiele sind PE, PP und PVC, etwa für Rohre, Gehäuse oder Isolierungen."},{"label":"Duroplaste","text":"Sie bilden beim Aushärten ein eng vernetztes Netzwerk. Danach sind sie hart, formstabil und häufig spröde. Erneutes Erwärmen macht sie nicht wieder schmelzbar; bei zu hoher Temperatur zersetzen sie sich. Ein Beispiel ist ausgehärtetes Epoxidharz, etwa als Matrix in Verbundwerkstoffen und Leiterplatten."},{"label":"Elastomere","text":"Ihr weitmaschig vernetztes Netzwerk erlaubt große, überwiegend rückstellbare Verformungen. Klassische Elastomere sind ebenfalls nicht wieder aufschmelzbar. Beispiele sind NBR und EPDM für Dichtungen oder elastische Bauteile. Wärme-, Kälte- und Medienbeständigkeit hängen stark von der jeweiligen Mischung ab."}],"mnemonic":"Unvernetzt lässt sich warm formen, eng vernetzt bleibt hart, weit vernetzt federt zurück.","pitfall":"Nicht jeder Kunststoff wird bei Wärme flüssig; klassische Elastomere und ausgehärtete Duroplaste lassen sich nicht wie Thermoplaste einschmelzen.","keywords":["Thermoplast","Duroplast","Elastomer","Vernetzung","Epoxidharz","PE"],"sources":[{"label":"VdS: Kunststoffe, Aufbau und Wärmeverhalten","url":"https://vds.de/fileadmin/Website_Content_Images/VdS_Publikationen/vds_2516_web.pdf"},{"label":"Ensinger: Thermoplastische Kunststoffe","url":"https://www.ensingerplastics.com/de-de/thermoplastische-kunststoffe"}],"minutes":4,"pdfPage":4},{"id":"D7","title":"Stärken, Grenzen und Abluftlärm","category":"Pneumatik","question":"Stelle je drei Vorteile und Nachteile pneumatischer Antriebe gegenüber und erkläre die Geräuschminderung an der Abluft.","answer":[{"label":"Drei Vorteile","text":"Pneumatische Antriebe sind häufig einfach, robust und leicht. Sie ermöglichen schnelle Bewegungen und ein günstiges Verhältnis von Kraft zu Baugröße. Druckluft lässt sich über Leitungen verteilen und in dafür ausgelegten Behältern speichern."},{"label":"Drei Nachteile","text":"Die Drucklufterzeugung und Leckagen verursachen Energieverluste und Betriebskosten. Die Kompressibilität erschwert eine lastunabhängig konstante Geschwindigkeit und das genaue Halten einer beliebigen Zwischenposition. Entspannende Abluft verursacht Lärm; die Luft muss außerdem passend gefiltert und getrocknet werden."},{"label":"Schalldämpfung","text":"Ein passend dimensionierter Schalldämpfer am Entlüftungsanschluss verteilt und beruhigt den Luftstrom. Alternativ kann Abluft gesammelt zu einem zentralen Schalldämpfer geführt werden. Ausreichender Durchfluss und saubere Dämpferelemente sind wichtig: zu großer Gegendruck verändert die Zylinderbewegung und kann die Funktion beeinträchtigen."}],"mnemonic":"Druckluft bewegt schnell, kostet Energie und muss kontrolliert ausströmen.","pitfall":"Ein immer stärker gedrosselter Abluftausgang ist keine beliebig gute Lärmschutzlösung.","keywords":["Kompressibilität","Druckluft","Schalldämpfer","Leckage","Abluft","Energie"],"sources":[{"label":"Festo: Wissenswertes über Pneumatik","url":"https://techblog.festo.at/wissenswertes-ueber-pneumatik-festo"},{"label":"Festo: Schalldämpfer und Durchfluss","url":"https://www.festo.com/ch/de/c/produkte/sonstige-pneumatische-komponenten/schalldaempfer-pneumatik-id_pim163"}],"minutes":4,"pdfPage":5},{"id":"D8","title":"Vakuum erzeugen","category":"Pneumatik","question":"Nenne verschiedene technische Vakuumerzeuger und erkläre den Luftweg sowie die Unterdruckentstehung in einem Druckluftejektor.","answer":[{"label":"Erzeugerarten","text":"Gängige Möglichkeiten sind mechanisch angetriebene Vakuumpumpen, beispielsweise Drehschieberpumpen, Vakuumgebläse für größere Volumenströme und druckluftbetriebene Ejektoren. Die Auswahl hängt von benötigtem Unterdruck, Saugvermögen, Leckage und Betriebsdauer ab."},{"label":"Ejektorprinzip","text":"Druckluft strömt durch eine verengte Treibdüse und wird stark beschleunigt. Der schnelle Luftstrahl reißt Gas aus dem angeschlossenen Saugraum mit; dort sinkt der Druck unter den Umgebungsdruck. Im nachfolgenden Misch- und Auslassbereich werden Treibluft und angesaugte Luft gemeinsam abgeführt, meist über einen Schalldämpfer. Es gibt keine mechanisch bewegte Pumpe im Ejektor."},{"label":"Wirkung am Sauger","text":"Die Haltekraft entsteht durch die Druckdifferenz zwischen Umgebung und Saugerinnerem über der wirksamen Fläche. Ein Vakuum ist kein eigener „Sogstoff“; Undichtheiten und poröse Oberflächen erfordern entsprechend mehr Saugvermögen."}],"mnemonic":"Der Ejektor verbraucht Druckluft, um Luft aus dem Saugraum mitzunehmen.","pitfall":"Ein hoher maximaler Unterdruck und ein großes Saugvermögen sind unterschiedliche Auswahlgrößen.","keywords":["Vakuum","Ejektor","Venturi","Saugvermögen","Vakuumpumpe","Druckdifferenz"],"sources":[{"label":"Schmalz: Vakuum-Ejektoren und Funktionsprinzip","url":"https://www.schmalz.com/de/support/know-how/vakuum-wissen/vakuumsystem-und-seine-bauteile/vakuum-erzeuger/vakuum-ejektoren"},{"label":"Schmalz: Vakuum-Pumpen","url":"https://www.schmalz.com/de/support/know-how/vakuum-wissen/vakuumsystem-und-seine-bauteile/vakuum-erzeuger/vakuum-pumpen"},{"label":"Schmalz: Vakuum-Gebläse","url":"https://www.schmalz.com/de/support/know-how/vakuum-wissen/vakuumsystem-und-seine-bauteile/vakuum-erzeuger/vakuum-geblaese"}],"minutes":4,"pdfPage":5,"imagePage":26,"imagePages":[26]},{"id":"D9","title":"Dichtungen und Dichtungswerkstoffe","category":"Mechanik","question":"Erkläre die Aufgaben einer Dichtung, vergleiche zwei Werkstoffe und nenne je zwei Beispiele für ruhende und bewegte Dichtstellen.","answer":[{"label":"Aufgabe","text":"Dichtungen begrenzen den Austritt eines Mediums und verhindern je nach Ausführung das Eindringen von Schmutz, Feuchtigkeit oder Fremdmedien. An bewegten Stellen müssen zusätzlich Reibung, Verschleiß und eine ausreichende Schmierung berücksichtigt werden."},{"label":"Zwei Werkstoffe","text":"NBR ist ein elastischer Kautschuk mit guter Beständigkeit gegenüber vielen Mineralölen und Fetten; seine Ozon- und Witterungsbeständigkeit ist begrenzt. EPDM ist gut gegen Ozon, Alterung und viele Heißwasseranwendungen beständig, eignet sich aber im Allgemeinen nicht für Mineralöle. Die konkrete Mischung und Herstellerfreigabe bleiben entscheidend."},{"label":"Ruhende und bewegte Flächen","text":"Statische Beispiele sind eine Flachdichtung zwischen Flanschen und ein O-Ring in einer ruhenden Gehäusefuge. Dynamische Beispiele sind ein Radialwellendichtring an einer rotierenden Welle und ein Nutring an einer hin- und hergehenden Kolbenstange. Ein O-Ring kann in passend ausgelegten Anwendungen auch dynamisch verwendet werden."}],"mnemonic":"Das Medium, die Temperatur und die Relativbewegung bestimmen die Dichtung.","pitfall":"Zwei ähnlich aussehende schwarze Dichtungen müssen weder aus demselben Werkstoff bestehen noch dieselbe Medienbeständigkeit haben.","keywords":["Dichtung","NBR","EPDM","Statisch","Dynamisch","Nutring"],"sources":[{"label":"Trelleborg: Statische Dichtungen, Werkstoffe und Einsatzbereiche","url":"https://www.trelleborg.com/seals/-/media/tss-media-repository/tss_website/pdf-and-other-literature/catalogs/static_seals_de.pdf?rev=43b3c558ce9c4e54b882d8318af374a5"},{"label":"Trelleborg: Elektronischer Dichtungskatalog","url":"https://www.trelleborg.com/de-de/seals/resources/e-catalog"}],"minutes":4,"pdfPage":6},{"id":"D10","title":"Schraubenformen und Festigkeitsklasse","category":"Mechanik","question":"Beschreibe typische Schrauben- und Mutterformen, unterscheide Durchsteck- und Stiftschraubverbindungen und entschlüssele die Klasse 8.8.","answer":[{"label":"Formen erkennen","text":"Vier Schraubenbeispiele sind Sechskantschraube, Zylinderschraube mit Innensechskant, Senkschraube und kopfloser Gewindestift. Vier Mutterbeispiele sind Sechskantmutter, Hutmutter mit geschlossenem Ende, Flügelmutter zur Handbetätigung und Kronenmutter mit Schlitzen für eine Splintsicherung. Kopf, Antrieb und Gewinde sind jeweils getrennte Merkmale."},{"label":"Verbindungsprinzip","text":"Bei der Durchsteckverbindung führt die Schraube durch Durchgangslöcher; Kopf und Mutter verspannen die Teile. Bei der Stiftschraube sitzt ein Ende in einem Gewindeloch des Grundteils, während das andere Ende mit einer Mutter das Anbauteil hält. Die Stiftschraube besitzt keinen normalen Schraubenkopf."},{"label":"Bedeutung von 8.8","text":"Die erste 8 ergibt den Nennwert der Zugfestigkeit: 8 × 100 = 800 N/mm². Die zweite 8 bedeutet das Verhältnis 0,8 für die nominelle Dehngrenze: 800 × 0,8 = 640 N/mm². Bei 8.8 wird hierfür die 0,2-%-Dehngrenze Rp0,2 verwendet. Normative Mindestwerte können vom Durchmesser abhängen; die Kennzeichnung ist keine direkt zulässige Betriebslast."}],"mnemonic":"Bei 8.8 stehen 800 für die Nennzugfestigkeit und 640 für die nominelle 0,2-%-Dehngrenze.","pitfall":"8.8 ist weder ein Anziehdrehmoment noch ein Gewindedurchmesser und gilt nicht als Belastungsfreigabe der ganzen Verbindung.","keywords":["Schraube","Mutter","Stiftschraube","Durchsteckverbindung","8.8","Dehngrenze"],"sources":[{"label":"Bossard: Schraubenformen","url":"https://www.bossard.com/de-de/eshop/produkte/verbindungstechnik/norm-und-standard-verbindungselemente/schrauben/c/01.100.100/"},{"label":"Bossard: Mechanische Eigenschaften nach ISO 898-1","url":"https://media.bossard.com/global-en/-/media/bossard-group/website/documents/technical-resources/en/f-004-en.pdf"}],"minutes":4,"pdfPage":6,"imagePage":27,"imagePages":[27]},{"id":"D11","title":"Drehmoment zwischen Welle und Nabe","category":"Mechanik","question":"Vergleiche drei Übertragungsprinzipien einer Welle-Nabe-Verbindung, erläutere feste und verschiebbare Passfederverbindungen mit Anwendungen und erkläre eine Keilwelle.","answer":[{"label":"Drei Prinzipien","text":"Formschluss überträgt Drehmoment über ineinandergreifende Konturen, etwa eine Passfeder. Kraft- beziehungsweise Reibschluss nutzt Anpressung und Reibung, etwa bei einem Spannsatz oder Pressverband. Stoffschluss verbindet die Werkstoffe beispielsweise durch Kleben oder Schweißen."},{"label":"Zwei Passfederverbindungen","text":"Bei einer festen Passfederverbindung überträgt die Passfeder das Drehmoment über ihre Seitenflächen; die Nabe wird zusätzlich axial festgelegt, zum Beispiel bei einer Riemenscheibe auf einer Motorwelle. Bei einer Gleitfederverbindung bleibt eine passende Nabe axial verschiebbar, während Drehmoment übertragen wird, etwa bei einem verschiebbaren Maschinenteil. Die Passfeder allein ist keine axiale Sicherung."},{"label":"Keilwelle","text":"Mehrere längs verlaufende Mitnehmerprofile sind in die Welle eingearbeitet; die Nabe besitzt das passende Gegenprofil. Die Last verteilt sich auf mehrere Flanken. Das eignet sich für größere oder wechselnde Drehmomente und, bei passender Auslegung, axiale Verschiebung, etwa in einer längenausgleichenden Antriebswelle."}],"mnemonic":"Passfedern und Keilwellen übertragen am Profil; ein Pressverband überträgt durch Reibung.","pitfall":"Eine Passfeder ist kein Spannkeil: Sie soll die Nabe nicht durch Keilwirkung verspannen.","keywords":["Welle","Nabe","Passfeder","Gleitfeder","Keilwelle","Reibschluss"],"sources":[{"label":"TU Chemnitz, IKAT: Welle-Nabe-Verbindungen","url":"https://bildungsportal.sachsen.de/opal/auth/RepositoryEntry/41541369871/CourseNode/1617158128348601010/121_VL_KL-ME_III_16_WNV_FS.pdf"},{"label":"RINGSPANN: Welle-Nabe-Verbindungen","url":"https://www.ringspann.com/de/service/downloads/einbauanleitungen/welle-nabe-verbindungen/"}],"minutes":4,"pdfPage":7,"imagePage":28,"imagePages":[28,29]},{"id":"D12","title":"Spannzylinder und sichere Positionsabfrage","category":"Pneumatik","question":"Nenne zwei fluidtechnische Spannprinzipien, erläutere die Gefahr eines blockierten Schwenkspanners und vergleiche Möglichkeiten zur Positionsüberwachung.","answer":[{"label":"Zwei Spannprinzipien","text":"Ein linearer Druck- oder Zugspanner bewegt sein Spannelement geradlinig. Ein Schwenkspanner schwenkt zunächst das Spanneisen über das Werkstück und führt danach den eigentlichen Spannhub aus. Beide Prinzipien lassen sich je nach Bauart pneumatisch oder hydraulisch verwirklichen."},{"label":"Blockierung","text":"Ein verklemmter Schwenkspanner kann unter Druck und mechanischer Spannung stehen. Beim Freigeben ist deshalb eine plötzliche Bewegung möglich. Die Prüfungserklärung lautet: Werkstück und bewegliche Teile sichern, Energiezustand einschließlich Restenergie nach Betriebsanleitung durch befugtes Personal sichern und die Ursache untersuchen lassen. Mehr Druck oder gewaltsames Lösen ersetzt keine Diagnose."},{"label":"Positionsabfrage","text":"Möglich sind magnetische Zylindersensoren, induktive Näherungsschalter an einer Schaltstange, mechanische Endschalter oder eine pneumatische Staudruck- beziehungsweise Differenzdruckabfrage. Ein Wegmesssystem liefert einen kontinuierlichen Positionswert. Reiner Versorgungsdruck ist kein verlässlicher Positionsnachweis: Druck kann auch bei blockiertem Spanner anstehen."}],"mnemonic":"Druck vorhanden heißt nicht Werkstück richtig gespannt.","pitfall":"Eine Endlagenmeldung allein beweist nur die erfasste Stellung, nicht automatisch eine ausreichende Spannkraft oder korrekte Werkstücklage.","keywords":["Schwenkspanner","Linearspanner","Restenergie","Positionskontrolle","Staudruck","Näherungsschalter"],"sources":[{"label":"ROEMHELD: Schwenkspanner und Schwenkhub","url":"https://mh.roemheld.de/de/produkte/schwenkspanner~pcZoNbbWoNwE"},{"label":"ROEMHELD: Betriebsanleitung B1854, Positionskontrolle","url":"https://ws.roemheld.de/fr/download/jLOVLXnKgn?filename=BA_B1854_DE_0524.PDF"},{"label":"DGUV: Sicherheit bei der Hydraulik-Instandhaltung","url":"https://publikationen.dguv.de/widgets/pdf/download/article/254"}],"minutes":4,"pdfPage":7},{"id":"D13","title":"Stufenlos steuern mit Proportionaltechnik","category":"Automation","question":"Erkläre den Zusammenhang zwischen elektrischem Sollwert und fluidtechnischer Stellgröße sowie die Eigenschaften eines Proportionalmagneten.","answer":[{"label":"Prinzip","text":"Proportionaltechnik verändert Druck, Volumenstrom oder Ventilöffnung stufenlos innerhalb eines Arbeitsbereichs entsprechend einem elektrischen Sollwert. Eine Elektronik setzt beispielsweise ein 0–10-V- oder 4–20-mA-Signal in einen geregelten Magnetstrom um. Ein Proportionalventil besitzt dadurch Zwischenstellungen statt ausschließlich Ein und Aus."},{"label":"Resultierende Bewegung","text":"Ein veränderter Druck beeinflusst die Antriebskraft; ein veränderter Volumenstrom beeinflusst die Bewegungsgeschwindigkeit. Damit lassen sich weiche Anfahr- und Bremsrampen und unterschiedliche Kraft- oder Geschwindigkeitsvorgaben erzeugen. Eine Rückführung und ein Regler sind nötig, wenn Abweichungen vom Sollwert automatisch ausgeregelt werden sollen."},{"label":"Proportionalmagnet","text":"Seine Magnetkraft ist im vorgesehenen Bereich annähernd proportional zum Strom und über den nutzbaren Hub möglichst gleichmäßig. Gegen eine passende Feder ergibt sich daraus eine einstellbare Ankerstellung. Reale Magnete besitzen Hysterese, Reibung und Grenzen; Dither oder eine Lageregelung können das Verhalten verbessern. Die Ansteuerung erfolgt vorzugsweise stromgeregelt."}],"mnemonic":"Strom stellt den Magneten, das Ventil stellt Druck oder Durchfluss, der Antrieb entwickelt Kraft oder Geschwindigkeit.","pitfall":"Ein proportionales Sollsignal macht aus einer Steuerung noch keine geschlossene Regelung.","keywords":["Proportionalventil","Magnetstrom","Volumenstrom","Druck","Hysterese","Regelung"],"sources":[{"label":"HAWE Hydraulik: Proportionalmagnet","url":"https://www.hawe.com/de-at/fluidlexikon/detail/proportionalmagnet/"},{"label":"Wandfluh: Funktions- und Kennlinienbeschreibung von Proportionalmagneten","url":"https://www.wandfluh.de/fileadmin/user_upload/Wandfluh/Products/Components/DataSheets/Deutsch/1.1_Magnete%20%26%20Handnotbet%C3%A4tigungen/1_1_410_d.pdf"},{"label":"Festo Didactic: Proportional-Wege- und Druckregelventile","url":"https://www.festo.com/media/catalog/156206_documentation.pdf"}],"minutes":4,"pdfPage":8,"imagePage":30,"imagePages":[30]},{"id":"D14","title":"Dauerhafte Verbindungen und Niete","category":"Mechanik","question":"Nenne drei nicht zerstörungsfrei lösbare Verbindungen, erkläre ein Beispiel und begründe die Werkstoffverträglichkeit von Niet und Fügeteilen.","answer":[{"label":"Drei Beispiele","text":"Niet-, Schweiß- und Klebeverbindungen gelten als unlösbar, weil ihre Trennung den Verbinder oder die Verbindungsschicht zerstört. Beim Schweißen entsteht Stoffschluss, beim Kleben wirkt eine haftende Verbindungsschicht, beim Nieten hält die geformte Nietgeometrie die Teile zusammen."},{"label":"Beispiel Blindniet","text":"Ein Blindniet besteht aus Hohlniet und Nietdorn. Beim Setzen zieht das Werkzeug am Dorn und verformt das verdeckte Ende des Hohlniets zum Schließkopf. Danach bricht der Dorn an seiner vorgesehenen Sollbruchstelle. Der Vorteil ist die Verarbeitung von nur einer zugänglichen Seite. Klemmbereich und Nietwerkstoff müssen zur Verbindung passen."},{"label":"Werkstoffpaarung","text":"Gleicher oder elektrochemisch verträglicher Werkstoff vermindert das Risiko von Kontaktkorrosion, wenn Feuchtigkeit als Elektrolyt vorhanden ist. Ähnliche Wärmeausdehnung kann zusätzlich günstig sein. Identischer Werkstoff ist jedoch keine ausnahmslose Pflicht: zugelassene Werkstoffkombinationen oder eine geeignete Trennung können ebenfalls funktionieren."}],"mnemonic":"Unlösbar bedeutet: Beim Trennen wird die Verbindung oder der Verbinder beschädigt.","pitfall":"Eine beliebige Aluminium-Stahl- oder Kupfer-Aluminium-Paarung bleibt bei Feuchtigkeit nicht automatisch korrosionsarm.","keywords":["Nieten","Schweißen","Kleben","Blindniet","Schließkopf","Kontaktkorrosion"],"sources":[{"label":"GESIPA: Aufbau und Funktion von Blindnieten","url":"https://www.gesipa.de/produkte/blindniete/"},{"label":"OBO: Kontaktkorrosion bei verschiedenen Metallen","url":"https://www.obo.ch/out/media/Befestigungsmaterial.pdf"}],"minutes":4,"pdfPage":8},{"id":"D15","title":"Federn als Kraft- und Energiespeicher","category":"Mechanik","question":"Beschreibe drei Federarten, ihre technischen Aufgaben und zwei geeignete Werkstoffgruppen.","answer":[{"label":"Drei Arten","text":"Eine Schraubendruckfeder wirkt gegen das Zusammendrücken. Eine Schraubenzugfeder nimmt Zug über ihre Enden auf. Eine Schenkel- oder Drehfeder liefert bei Verdrehung ihrer Schenkel ein rückstellendes Moment. Weitere Bauformen sind Blatt-, Teller- und Spiralfedern."},{"label":"Aufgaben","text":"Federn speichern elastische Energie und geben sie wieder ab, stellen Bauteile zurück, erzeugen Vorspann- oder Kontaktkräfte und gleichen Wege oder Toleranzen aus. Über eine bekannte Federkennlinie lässt sich auch eine Kraft messen. In einer Federung mindern sie zusammen mit geeigneter Dämpfung die Wirkung von Stößen."},{"label":"Zwei Werkstoffe","text":"Häufig verwendet werden unlegierte oder legierte Federstähle, beispielsweise Federstahldraht nach EN 10270-1, sowie nichtrostender Federstahl, beispielsweise 1.4310. Werkstoff, Wärmebehandlung und Oberflächenzustand beeinflussen Dauerfestigkeit, Korrosionsverhalten und zulässige Temperatur."}],"mnemonic":"Eine Feder speichert Energie und erzeugt Rückstellkraft; ein Dämpfer baut Bewegungsenergie ab.","pitfall":"Eine ideale Feder vernichtet keine Schwingungsenergie und ersetzt keinen Dämpfer.","keywords":["Druckfeder","Zugfeder","Schenkelfeder","Federstahl","Rückstellkraft","Energiespeicher"],"sources":[{"label":"Gutekunst: Federarten und Federwerkstoffe","url":"https://www.federnshop.com/de/service-und-informationen/katalogfedern.html"},{"label":"Hochschule Anhalt: Maschinenelemente, Federn und Aufgaben","url":"https://www.hs-anhalt.de/fileadmin/Dateien/FB6/personen/voigt_st/Lehrunterlagen/01_ME_Vorlesung/08_ME_Federn_Stud.pdf"}],"minutes":4,"pdfPage":9,"imagePage":31,"imagePages":[31]},{"id":"D16","title":"Zahnräder und Achsanordnung","category":"Mechanik","question":"Welche Größen können Zahnradtriebe verändern? Benenne drei Zahnradarten anhand ihrer Form und erläutere zwei typische Achsanordnungen genauer.","answer":[{"label":"Aufgabe","text":"Zahnräder übertragen Drehbewegung und Drehmoment formschlüssig. Mit der Zähnezahlübersetzung verändern sie Drehzahl und Drehmoment; abhängig von der Anordnung ändern sie Drehrichtung und Richtung der Wellenachsen. Ein Ritzel mit Zahnstange wandelt Dreh- in Linearbewegung."},{"label":"Stirnrad","text":"Beim Stirnrad liegen die Zähne auf einer zylindrischen Umfangsfläche. Gerade oder schräg verzahnte Stirnräder übertragen zwischen parallelen Wellen. Ein außenverzahntes Radpaar dreht gegensinnig; Schrägverzahnung läuft in der Regel ruhiger, erzeugt aber zusätzliche Axialkräfte."},{"label":"Kegelrad und Schneckenrad","text":"Kegelräder besitzen eine kegelige Grundform und eignen sich für sich schneidende Wellenachsen, häufig mit 90° Achswinkel. Eine Schnecke greift in ein Schneckenrad ein; die Achsen sind versetzt und kreuzen sich räumlich. Damit sind große Übersetzungen in einer Stufe möglich, allerdings mit höheren Gleitanteilen und Verlusten."}],"mnemonic":"Stirnrad: parallele Achsen; Kegelrad: sich schneidende Achsen; Schnecke: räumlich versetzte Achsen.","pitfall":"Ein Schneckengetriebe ist nicht grundsätzlich selbsthemmend; das hängt unter anderem von Steigungswinkel und Reibung ab.","keywords":["Stirnrad","Kegelrad","Schneckenrad","Übersetzung","Zähnezahl","Drehmoment"],"sources":[{"label":"KHK Gears: The ABC's of Gears, Bauarten und Eigenschaften","url":"https://khkgears.us/media/fqrlut1m/abcs-of-gearing-b.pdf"}],"minutes":4,"pdfPage":9,"imagePage":32,"imagePages":[32]},{"id":"D17","title":"Drei Arten der Bewegungsübertragung","category":"Mechanik","question":"Vergleiche Riemen-, Ketten- und Zahnradtrieb nach Wirkprinzip und Achsabstand und gib für jeden ein Anwendungsbeispiel.","answer":[{"label":"Riemenantrieb","text":"Ein biegsamer Riemen verbindet Riemenscheiben und überbrückt einen größeren Achsabstand. Flach- und Keilriemen übertragen durch Reibung und können schlupfen. Zahnriemen übertragen durch Zahneingriff formschlüssig. Beispiel: ein Keilriemen am Lüfter oder ein Zahnriemen an einer Positionierachse."},{"label":"Kettenantrieb","text":"Eine Gelenkkette greift formschlüssig in Kettenräder ein, etwa an einem Förderer oder Fahrrad. Es gibt keinen Reibschlupf wie beim Keilriemen. Gelenkverschleiß verändert jedoch die Teilung; außerdem können Geräusch und ungleichförmiger Lauf durch den Polygoneffekt entstehen. Schmierung und Wartung sind bauartabhängig."},{"label":"Zahnradantrieb","text":"Die Zähne der Räder greifen unmittelbar ineinander. Das eignet sich für kompakte, belastbare Übersetzungen, zum Beispiel im Getriebe einer Werkzeugmaschine. Der Abstand wird durch die Radgeometrie festgelegt; Schmierung und genaue Lagerung sind wichtig. Kette und Riemen können dagegen größere Abstände ohne Zwischenrad überbrücken."}],"mnemonic":"Riemen läuft über Scheiben, Kette greift in Räder, Zahnräder greifen direkt ineinander.","pitfall":"Die Aussage „Riemen haben immer Schlupf“ stimmt für korrekt ausgelegte Zahnriemen nicht.","keywords":["Riementrieb","Kettentrieb","Zahnradtrieb","Schlupf","Formschluss","Achsabstand"],"sources":[{"label":"Optibelt: Kraft- und formschlüssige Riemenantriebe","url":"https://www.optibelt.com/fileadmin/pdf/kataloge/Optibelt-Kompaktkatalog-Power-Transmission.pdf"},{"label":"iwis: Handbuch Kettentechnik","url":"https://www.iwis.com/antriebssysteme-drive-systems/as-handbook/iwis-handbuch-kettentechnik-konstruktionsunterlagen-berechnungsbeispiele.pdf"},{"label":"SEW-EURODRIVE: Funktion und Bauarten von Getrieben","url":"https://www.sew-eurodrive.de/produkte/getriebe/getriebe.html"}],"minutes":4,"pdfPage":10},{"id":"D18","title":"Lagerbauarten und Schmierung","category":"Mechanik","question":"Wie unterscheiden sich Gleit- und Wälzlager? Beschreibe drei Wälzlagerbauarten und begründe die Wahl zwischen Fett und Öl.","answer":[{"label":"Grundausführungen","text":"Bei Gleitlagern bewegen sich die Lagerflächen gegeneinander gleitend, gegebenenfalls durch einen Schmierfilm getrennt. Wälzlager besitzen rollende Körper zwischen den Laufbahnen. Zusätzlich unterscheidet man nach Belastungsrichtung Radial-, Axial- und kombinierte Lager sowie nach Lagerungsfunktion Fest- und Loslager."},{"label":"Drei Wälzlager","text":"Ein Rillenkugellager besitzt Kugeln in tiefen Laufbahnrillen und nimmt radiale sowie begrenzte axiale Kräfte in beiden Richtungen auf. Ein Zylinderrollenlager besitzt zylindrische Rollen und trägt hohe Radiallasten; die Axialfähigkeit hängt von der Bauform ab. Beim Kegelrollenlager laufen kegelige Rollen auf kegeligen Bahnen; es trägt kombinierte Lasten, axial vor allem in einer Richtung."},{"label":"Fett oder Öl","text":"Fett bleibt gut in der Lagerstelle, unterstützt die Abdichtung und ermöglicht einfache, wartungsarme Konstruktionen. Öl ist insbesondere sinnvoll, wenn Wärme abgeführt werden muss, hohe Beanspruchungen dies erfordern oder benachbarte Teile bereits mit Öl versorgt werden. Ausschlaggebend sind Herstellerangaben, Drehzahl, Temperatur und Last; zu viel Fett erhöht Reibung und Erwärmung."}],"mnemonic":"Nicht die Lagergröße allein, sondern Betriebsbedingungen und Wärmehaushalt bestimmen den Schmierstoff.","pitfall":"Mehr Fett bedeutet nicht automatisch bessere Schmierung; Überfüllung kann das Lager stark erwärmen.","keywords":["Gleitlager","Wälzlager","Rillenkugellager","Kegelrollenlager","Fettschmierung","Ölschmierung"],"sources":[{"label":"NSK: Was ist ein Wälzlager?","url":"https://www.nskeurope.com/eu-de/tools-resources/training/whats-a-bearing/"},{"label":"Schaeffler: Wälzlagerkatalog HR1","url":"https://www.schaeffler.de/remotemedien/media/_shared_media/08_media_library/01_publications/schaeffler_2/catalogue_1/downloads_6/hr1_de_de.pdf"},{"label":"Schaeffler: Schmierung von Wälzlagern","url":"https://www.schaeffler.com/remotemedien/media/_shared_media/08_media_library/01_publications/schaeffler_2/tpi/downloads_8/tpi_176_de_de.pdf"}],"minutes":4,"pdfPage":10,"imagePage":33,"imagePages":[33]},{"id":"D19","title":"Störeinflüsse auf Sensorsignale","category":"Elektrotechnik","question":"Unterscheide typische elektromagnetische Einkopplungen, erkläre galvanische Beeinflussung und nenne wirksame Maßnahmen gegen induktive Einstreuung.","answer":[{"label":"Vier Kopplungsarten","text":"Galvanische Kopplung wirkt über gemeinsame leitende Verbindungen, kapazitive Kopplung über elektrische Felder, induktive Kopplung über veränderliche Magnetfelder und Strahlungskopplung über elektromagnetische Wellen. Sie können analoge Messwerte verfälschen oder digitale Signale stören."},{"label":"Galvanische Ursache","text":"Nutzen Leistungs- und Signalstrom einen gemeinsamen Leiter oder eine gemeinsame Impedanz, erzeugt der Leistungsstrom dort einen Spannungsabfall. Dieser verschiebt das Bezugspotenzial des Sensors. Auch Potenzialunterschiede und Ausgleichsströme zwischen Anlagenteilen können Störungen einkoppeln."},{"label":"Gegen induktive Einstreuung","text":"Signalleitungen werden mit Abstand zu Motor- und Lastleitungen geführt; lange parallele Wege werden vermieden und nötige Kreuzungen möglichst rechtwinklig ausgeführt. Verdrillte Hin- und Rückleiter verkleinern die wirksame Schleifenfläche. Geeignete Schirmung, fachgerechter Potenzialausgleich und Entstörung schaltender Spulen ergänzen die Maßnahmen nach Hersteller- und EMV-Konzept."}],"mnemonic":"Kleine Leiterschleifen und großer Abstand zu Störströmen verringern induktive Einkopplung.","pitfall":"Ein Schirm ersetzt weder Schutzleiter noch Potenzialausgleich; seine Anbindung muss zum Signal- und Anlagenkonzept passen.","keywords":["EMV","Galvanische Kopplung","Induktive Kopplung","Schirmung","Twisted Pair","Potenzialausgleich"],"sources":[{"label":"Siemens: Kopplungsmechanismen der EMV","url":"https://docs.tia.siemens.cloud/r/simatic_et_200eco_pn_manual_collection_dede_20/funktionshandbucher/funktionshandbucher-peripherie/steuerungen-storsicher-aufbauen/grundlagen-zur-elektromagnetischen-vertraglichkeit/kopplungsmechanismen?contentId=3e1horHNaH4dv~VQRtqsdw"},{"label":"Beckhoff: Analogtechnische Hinweise zu Schirm und Erde","url":"https://infosys.beckhoff.com/content/1031/ioanalogmanual/2346576779.html"}],"minutes":4,"pdfPage":11,"imagePage":34,"imagePages":[34]},{"id":"D20","title":"Prozesszustände sichtbar machen","category":"Automation","question":"Erkläre Prozessvisualisierung, nenne ihren betrieblichen Nutzen und gib drei mögliche Anzeigegeräte an.","answer":[{"label":"Bedeutung","text":"Eine Prozessvisualisierung stellt aktuelle Zustände, Messwerte und Abläufe einer Maschine oder Anlage verständlich dar. Eine HMI kann zusätzlich berechtigte Bedienhandlungen ermöglichen, etwa Sollwerteingaben und das Quittieren von Meldungen. Die angezeigten Informationen werden aus der Steuerung oder anderen Datenquellen übernommen."},{"label":"Nutzen","text":"Übersichtsbilder machen den Anlagenzustand schneller erkennbar. Meldungen unterstützen die Störungssuche, Trends zeigen zeitliche Veränderungen und gespeicherte Daten helfen bei Qualitätssicherung und Optimierung. Eine gute Oberfläche zeigt Einheiten, Grenzwerte und die Aktualität der Werte deutlich."},{"label":"Drei Geräte","text":"Möglich sind ein industrielles Bedienpanel, ein Industrie-PC beziehungsweise Panel-PC und ein autorisiertes Tablet oder Smartphone mit geeigneter Web-HMI. Die Visualisierung ist die Software; Bildschirm und Eingabegerät sind ihre Hardware. Sicherheitsfunktionen dürfen nicht allein von einer gewöhnlichen HMI-Anzeige abhängen."}],"mnemonic":"Visualisieren heißt Zustände verstehen; Bedienen verlangt passende Rechte und Rückmeldungen.","pitfall":"Ein grünes Symbol beweist keine sichere Maschinenstellung, wenn Daten veraltet, falsch zugeordnet oder nicht sicherheitsgerichtet erfasst sind.","keywords":["HMI","Visualisierung","Bedienpanel","Trends","Meldungen","Prozesswerte"],"sources":[{"label":"Beckhoff: TwinCAT HMI und Plattformen","url":"https://www.beckhoff.com/de-de/produkte/automation/twincat-hmi/"},{"label":"Beckhoff: Multitouch-Control-Panels","url":"https://www.beckhoff.com/de-de/produkte/ipc/control-panels/cp29xx-cp39xx-multitouch-control-panels/"}],"minutes":4,"pdfPage":11},{"id":"D21","title":"Kupplungen zwischen Antriebswellen","category":"Mechanik","question":"Welche Aufgaben erfüllen Kupplungen? Beschreibe zwei erkennbare Bauarten mit je einer typischen Anwendung.","answer":[{"label":"Aufgaben","text":"Kupplungen verbinden An- und Abtriebswelle zur Drehmomentübertragung. Je nach Bauart gleichen sie begrenzten axialen, radialen oder winkligen Versatz aus, dämpfen Drehschwingungen oder erlauben Schalten beziehungsweise Überlastbegrenzung. Diese Zusatzfunktionen sind nicht bei jeder Kupplung vorhanden."},{"label":"Elastische Klauenkupplung","text":"Zwei Naben mit Klauen greifen über ein elastisches Zwischenstück ineinander. Das Zwischenstück kann Stöße und Drehschwingungen dämpfen und begrenzte Verlagerungen zulassen. Eine typische Anwendung ist die Verbindung eines Elektromotors mit einer Pumpe."},{"label":"Metallbalgkupplung","text":"Zwischen den Naben sitzt ein dünnwandiger, gefalteter Metallbalg. Er ist gegenüber Verlagerungen biegsam, überträgt die Drehung aber mit hoher Torsionssteife und bei entsprechender Ausführung spielfrei. Das eignet sich etwa für eine Servoachse zwischen Motor und Kugelgewindetrieb oder Drehgeber."}],"mnemonic":"Die Kupplung überträgt Drehmoment; ihre Bauart bestimmt Dämpfung, Steifigkeit und Versatzausgleich.","pitfall":"Eine ausgleichende Kupplung ersetzt keine sorgfältige Wellenausrichtung und ist nicht automatisch eine Sicherheitskupplung.","keywords":["Kupplung","Drehmoment","Klauenkupplung","Metallbalg","Wellenversatz","Torsionssteife"],"sources":[{"label":"KTR: Antriebstechnik und Kupplungsbauarten","url":"https://www.ktr.com/dam/jcr%3A674923f2-6eae-4fab-83e9-1b6bb25c0178/KTR-KATALOG-ANTRIEBSTECHNIK.PDF"},{"label":"KTR: Metallbalgkupplung TOOLFLEX","url":"https://www.ktr.com/de/de/produkte/toolflex-metallbalgkupplungen/"}],"minutes":4,"pdfPage":12,"imagePage":35,"imagePages":[35,36]},{"id":"D22","title":"Keilriemen und Zahnriemen","category":"Mechanik","question":"Wozu wird ein Riementrieb eingesetzt und wie erkennst und erklärst du Keilriemen und Zahnriemen?","answer":[{"label":"Zweck","text":"Ein Riementrieb überträgt Leistung zwischen Wellen über einen umlaufenden Riemen. Unterschiedliche wirksame Scheibendurchmesser beziehungsweise Zähnezahlen ergeben eine Übersetzung. Die flexible Verbindung überbrückt größere Achsabstände und kann je nach Bauart Schwingungen mindern."},{"label":"Keilriemen","text":"Sein Querschnitt ist trapezförmig und läuft in einer passenden Rille. Die Kraft wird über Reibung an den Flanken übertragen; dazu ist eine geeignete Vorspannung nötig. Schlupf ist möglich. Eine gezahnte Innenseite bei manchen Keilriemen verbessert die Biegsamkeit, macht sie aber nicht zu Zahnriemen."},{"label":"Zahnriemen","text":"Seine Zähne greifen in passende Zahnlücken der Riemenscheibe ein. Das ergibt eine formschlüssige, im normalen Betrieb schlupffreie Übertragung mit fester Zuordnung der Drehwinkel. Zahnprofil, Teilung, Breite und zulässige Last müssen zueinander passen."}],"mnemonic":"Keilriemen hält an den Flanken durch Reibung; Zahnriemen greift mit seinen Zähnen.","pitfall":"Sichtbare Querkerben an einem Keilriemen sind keine formschlüssig eingreifenden Zahnriemenzähne.","keywords":["Keilriemen","Zahnriemen","Riemenscheibe","Vorspannung","Reibschluss","Zahneingriff"],"sources":[{"label":"Optibelt: Riemenbauarten und Übertragungsprinzipien","url":"https://www.optibelt.com/fileadmin/pdf/kataloge/Optibelt-Kompaktkatalog-Power-Transmission.pdf"},{"label":"Gates: Keilriemen","url":"https://www.gates.com/de/de/power-transmission/v-belts.html"}],"minutes":4,"pdfPage":12,"imagePage":37,"imagePages":[37]},{"id":"D23","title":"CEE-Codierung und Kontaktfolge","category":"Elektrotechnik","question":"Ordne drei CEE-Kennfarben Spannungsbereichen zu, erkläre die mechanische Unverwechselbarkeit, den Schutzkontakt und die Aufgabe eines Pilotkontakts einschließlich Kontaktfolge.","answer":[{"label":"Kennfarben","text":"Drei typische Zuordnungen sind Gelb für 100–130 V, Blau für 200–250 V und Rot für 380–480 V. Maßgeblich sind stets die aufgedruckten Bemessungsdaten einschließlich Frequenz und Polzahl; eine Farbe allein beschreibt nicht jede zulässige Kombination."},{"label":"Mechanische Codierung","text":"Führungsnase und Nut sowie die festgelegte Uhrzeitstellung des Schutzleiterkontakts verhindern unpassende Paarungen. Auch Baugröße und Kontaktanordnung müssen zusammenpassen. Die Farbe unterstützt die Erkennung; die mechanische Codierung verhindert das Zusammenstecken."},{"label":"Schutzkontakt","text":"Der Schutzleiterkontakt besitzt einen größeren Durchmesser als die aktiven Kontakte und ist voreilend ausgeführt. Beim Stecken verbindet PE zuerst, beim Ziehen trennt PE zuletzt. Die Kontaktgeometrie von Stift und Buchse verwirklicht diese Reihenfolge."},{"label":"Pilotkontakt","text":"Der zusätzliche Steuerkontakt kann ein vorgeschaltetes Schütz elektrisch verriegeln: Er schließt nach den Hauptkontakten und öffnet vor ihnen. Beim Stecken lautet die Reihenfolge PE, Hauptkontakte, Pilotkontakt; beim Ziehen umgekehrt. Ein richtig ausgelegter Steuerkreis schaltet dadurch die Last vor dem Trennen der Hauptkontakte ab. Der Pilotkontakt führt keinen Laststrom und ist kein Ersatz für PE."}],"mnemonic":"Beim Stecken schützt PE zuerst; der Pilot gibt die Last zuletzt frei.","pitfall":"Die Gehäusefarbe allein verhindert keine Fehlverbindung, und ein Pilotkontakt wirkt nur mit der zugehörigen Verriegelungsschaltung.","keywords":["CEE","Uhrzeitstellung","Schutzkontakt","Pilotkontakt","Verriegelung","Kennfarben"],"sources":[{"label":"MENNEKES: Kennfarben und Uhrzeitstellungen","url":"https://www.iv-ott.de/fileadmin/user_upload/Downloads/Mennekes-PK.pdf"},{"label":"MENNEKES: Pilotkontakt und nacheilende Kontaktgabe","url":"https://www.mennekes.de/industry/services/fragen-antworten/faq-detailansicht/kann-ich-einen-rueckmeldungsignal-von-der-cee-steckvorrichtung-erhalten/"},{"label":"MENNEKES: Technische Informationen zu CEE-Kontakten","url":"https://www.elec.ru/brands/mennekes/_Mennekes_Deutsch.pdf"},{"label":"LAPP: Cable Guide, voreilender Schutzkontakt","url":"https://t3.lappcdn.com/fileadmin/DAM/Lapp_Austria/Kataloge_Flyer/CableGuide_de_at.pdf"}],"minutes":4,"pdfPage":13},{"id":"D24","title":"Antrieb passend zur Aufgabe wählen","category":"Mechanik","question":"Begründe die Unterschiede von Riemen-, Ketten- und Zahnradtrieb an den Kriterien Kraftübertragung, Abstand, Laufverhalten und Wartung.","answer":[{"label":"Riemen","text":"Keil- und Flachriemen übertragen durch Reibung, Zahnriemen durch Formschluss. Riemen sind leicht, laufen meist leise und benötigen keine Gelenkschmierung. Sie überbrücken größere Achsabstände. Vorspannung, Alterung und bei Reibtrieben Schlupf beeinflussen den Betrieb."},{"label":"Kette","text":"Ketten übertragen durch Formschluss und sind für belastbare Antriebe über größere Abstände geeignet. Gelenke und Zahneingriff verursachen Verschleiß und Geräusche; meist ist eine geeignete Schmierung nötig. Der Polygoneffekt kann die Geschwindigkeit periodisch schwanken lassen."},{"label":"Zahnräder","text":"Direkt eingreifende Räder ergeben einen kompakten, formschlüssigen Trieb mit geometrisch festgelegtem Achsabstand. Präzise Fertigung, Lagerung und ausreichende Schmierung ermöglichen hohe Belastbarkeit. Die gewünschte Übersetzung und Achsanordnung bestimmen die Bauart; vorhandenes Zahnflankenspiel ist kein Reibschlupf."}],"mnemonic":"Zur Auswahl gehören Abstand, Drehwinkelbezug, Last, Geräusch und Wartungsaufwand.","pitfall":"Formschluss bedeutet nicht vollkommen gleichförmigen oder spielfreien Lauf; Ketten können den Polygoneffekt und Zahnräder Flankenspiel besitzen.","keywords":["Riemen","Kette","Zahnräder","Polygoneffekt","Flankenspiel","Antriebsauswahl"],"sources":[{"label":"Gates: Riemenspannung, Verschleiß und Synchronisierung","url":"https://www.gates.com/content/dam/documents-library/operating-manuals/preventive-maintenance-manual-de-de.pdf"},{"label":"iwis: Kettenhandbuch, Schlupf und Polygoneffekt","url":"https://www.iwis.com/antriebssysteme-drive-systems/as-handbook/iwis-handbuch-kettentechnik-konstruktionsunterlagen-berechnungsbeispiele.pdf"},{"label":"SEW-EURODRIVE: Funktion und Bauarten von Getrieben","url":"https://www.sew-eurodrive.de/produkte/getriebe/getriebe.html"}],"minutes":4,"pdfPage":13},{"id":"D25","title":"Zwei Fahrbefehle für einen Zylinder","category":"Pneumatik","question":"Erkläre für die Zuordnung D25 den Signalweg von SF1 beziehungsweise SF2 über die Relais zu den Ventilspulen, die beiden Zylinderbewegungen und das Verhalten nach Loslassen der Taster. Welcher Ventiltyp ist dargestellt?","answer":[{"label":"Geprüfte Schaltung","text":"Auf der zugehörigen Quellseite 38 sind zwei unabhängige 24-V-Zweige zu erkennen: SF1 betätigt QA1, dessen Schließer MB1 versorgt. SF2 betätigt QA2, dessen Schließer MB2 versorgt. Die Relais besitzen hier keine eingezeichnete Selbsthaltung."},{"label":"Pneumatischer Ablauf","text":"MB1 schaltet die Versorgung 1 auf Anschluss 4 zur Kolbenseite; die Stangenseite wird über 2 und 3 entlüftet. Der doppeltwirkende Zylinder fährt aus. MB2 schaltet 1 auf 2 zur Stangenseite und entlüftet die Kolbenseite über 4 und 5; der Zylinder fährt ein."},{"label":"Ventil und Speicherverhalten","text":"Dargestellt ist ein 5/2-Wegeventil mit zwei elektromagnetischen Betätigungen und ohne Rückstellfeder, also eine bistabile Ansteuerung. Nach Loslassen des Tasters fällt das betreffende Relais ab; das Ventil behält seine zuletzt geschaltete Stellung. Die Bewegung kann bei weiter vorhandener Druckluft deshalb bis zur Endlage weiterlaufen."},{"label":"Grenzen der Darstellung","text":"Es sind weder automatische Endlagenrückmeldungen noch eine gegenseitige elektrische Verriegelung erkennbar. Für gleichzeitig betätigte Taster ist damit kein eindeutiger Fahrbefehl aus dem Plan ableitbar. Eine federdefinierte Ventilgrundstellung darf ebenfalls nicht angenommen werden."}],"mnemonic":"Das Relais speichert hier nicht; das bistabile Wegeventil behält den letzten Schaltbefehl.","pitfall":"Loslassen eines Tasters ist bei dieser Schaltung keine sichere Stoppfunktion.","keywords":["5/2-Wegeventil","Bistabil","Relais","MB1","MB2","Doppeltwirkend"],"sources":[{"label":"WKO Oberösterreich: D25, Sichtprüfung der zugeordneten Schaltung auf PDF-Seite 38","url":"https://www.wko.at/ooe/bildung-lehre/fragenkatalog-kandidat-mec-h1.pdf"},{"label":"Festo: Bistabile 5/2-Magnetventile","url":"https://www.festo.com/media/catalog/202473_documentation.pdf"}],"minutes":4,"pdfPage":14,"imagePage":38,"imagePages":[38]},{"id":"D26","title":"Pneumatische Zeitverzögerung","category":"Pneumatik","question":"Nenne günstige und ungünstige Eigenschaften der Pneumatik und erkläre Aufbau, Einschaltverzögerung und Rückstellung eines typischen pneumatischen Zeitglieds.","answer":[{"label":"Eigenschaften","text":"Günstig sind einfache, robuste Komponenten, schnelle Bewegungen und das Speichern sowie Verteilen der Druckluft. Ungünstig sind der Energieaufwand bei Erzeugung und Leckage, Abluftlärm und die nachgiebige, lastabhängige Wirkung der kompressiblen Luft. Die Luftqualität muss zu den Komponenten passen."},{"label":"Bauteile des Zeitglieds","text":"Ein klassisches Zeitverzögerungsventil kombiniert ein einstellbares Drossel-Rückschlagventil, ein kleines Luftvolumen und ein pneumatisch betätigtes, federzurückgestelltes 3/2-Wegeventil. Es existieren Ausführungen mit unterschiedlicher Ruhestellung und unterschiedlicher Verzögerungsrichtung."},{"label":"Funktion am Beispiel Einschaltverzögerung","text":"Ein anliegendes Steuersignal füllt das Luftvolumen durch die Drossel langsam. Erst beim Erreichen des erforderlichen Steuerdrucks schaltet das 3/2-Ventil den Ausgang. Beim Wegfall des Steuersignals entleert sich das Volumen über den Rückschlagweg schneller und die Feder stellt zurück. Drosselquerschnitt und Volumen bestimmen die Verzögerung; Druck und Luftzustand beeinflussen die Wiederholgenauigkeit."}],"mnemonic":"Die Drossel füllt den Speicher langsam; der erreichte Druck löst das Schalten aus.","pitfall":"Ein pneumatisches Zeitglied zählt keine exakten Sekunden unabhängig von Druck, Leckage und Temperatur.","keywords":["Zeitverzögerung","Drossel","Rückschlagventil","Luftspeicher","3/2-Wegeventil","Steuerdruck"],"sources":[{"label":"SFS-Fluidsysteme: Pneumatisches Zeitverzögerungsventil","url":"https://www.sfs-fluidsysteme.com/pneumatisches-zeitverzoegerungsventil/"},{"label":"Festo: Product Guide Fluid-Power, pneumatische Komponenten","url":"https://www.festo.com/media/catalog/156206_documentation.pdf"},{"label":"Festo: Wissenswertes über Pneumatik","url":"https://techblog.festo.at/wissenswertes-ueber-pneumatik-festo"}],"minutes":4,"pdfPage":14,"imagePage":39,"imagePages":[39]},{"id":"D27","title":"Leitungstypen richtig lesen","category":"Elektrotechnik","question":"Für eine feste Inneninstallation soll eine passende Leitung gewählt werden. Nenne geeignete Typen, zerlege A05VV-U 3G1,5 vollständig und grenze zulässige Verlegeorte ab.","answer":[{"label":"Geeignete Beispiele","text":"Mantelleitung YM beziehungsweise AT-N05VV-U; Aderleitung H07V-U in einem geeigneten geschlossenen Rohr- oder Kanalsystem; weitere Installationsleitungen nur entsprechend örtlicher Norm und Herstellerfreigabe."},{"label":"Kennzeichnung","text":"A = anerkannter nationaler Typ, H würde harmonisierter Typ bedeuten. 05 = Bemessungsspannung U₀/U 300/500 V; erstes V = PVC-Aderisolierung, zweites V = PVC-Mantel; U = eindrähtiger Leiter. 3 = drei Adern insgesamt; G = grün-gelbe Schutzleiterader enthalten; 1,5 = Nennquerschnitt jeder Ader in mm²."},{"label":"Einsatzgrenzen","text":"Für feste Verlegung in trockenen, feuchten oder nassen Innenräumen auf, in oder unter Putz gemäß Produktdatenblatt. Kein Erdkabel. Ungeschützte Außenverlegung und Betonverlegung nicht pauschal zulässig; konkrete Freigabe prüfen. Auswahl und Installation gehören zur Elektrofachkraft."}],"mnemonic":"A ist national, H harmonisiert; G zählt den Schutzleiter mit.","pitfall":"Die Bezeichnung beginnt mit A und der Zahl 05, nicht mit H oder den Buchstaben AO. Aus 1,5 mm² folgt allein noch kein zulässiger Sicherungswert.","keywords":["YM","A05VV-U","AT-N05VV-U","300/500 V","PVC","3G1,5"],"sources":[{"label":"LAPP: Typenkurzzeichen T6","url":"https://www.lappkabel.de/fileadmin/catalog/de_T_pdf/T6_Typenkurzzeichen_de.pdf"},{"label":"HEIRU: Datenblatt A05VV-U / AT-N05VV-U","url":"https://www.heiru.com/images/pdf/At/AT-N05VV-U_de.pdf"}],"minutes":4,"pdfPage":15},{"id":"D28","title":"CEE: Verwechslungsschutz und Pilot","category":"Elektrotechnik","question":"Erkläre, wie CEE-Verbindungen falsches Zusammenstecken erschweren. Beschreibe Schutzkontakt und Pilotkontakt einschließlich Kontaktfolge beim Stecken und Ziehen sowie zwei typische Kennfarben.","answer":[{"label":"Mechanische Zuordnung","text":"Nase und Nut legen die Stecklage fest. Die zur Nut definierte Uhrzeitstellung des Schutzkontakts codiert zusammen mit Polzahl und Bauform Spannung beziehungsweise Frequenz. Unterschiedliche Stromgrößen haben unterschiedliche Abmessungen. Farben helfen bei der Erkennung; sie ersetzen die mechanische Codierung nicht."},{"label":"Schutzkontakt","text":"Der PE-Stift und seine Buchse haben einen größeren Durchmesser als die Kontakte von L und N. PE kontaktiert voreilend und trennt nacheilend: Die Schutzverbindung besteht vor den aktiven Kontakten und bleibt bis nach deren Trennung erhalten."},{"label":"Pilotkontakt","text":"Bei einer dafür ausgelegten Verbindung: PE zuerst, Hauptkontakte danach, Pilot zuletzt. Beim Ziehen öffnet zuerst der Pilot, anschließend trennen die Hauptkontakte, zuletzt PE. Der Pilot kann über eine korrekt ausgeführte Verriegelung ein Schütz abschalten; allein macht er keine beliebige Steckverbindung lastfrei."},{"label":"Farben","text":"Blau steht typisch für 200–250 V, etwa 230 V; Rot typisch für 380–440 V, etwa 400 V. Weitere Werte ergeben sich aus Kennzeichnung und Normtabelle."}],"mnemonic":"PE zuerst und zuletzt; Pilot zuletzt hinein, zuerst heraus.","pitfall":"Pilot und PE haben entgegengesetzte zeitliche Aufgaben. Die Uhrzahl bezeichnet eine Position, keine zulässige Betriebsdauer.","keywords":["CEE","PE","Pilotkontakt","Uhrzeitstellung","Kennfarbe","IEC 60309"],"sources":[{"label":"MENNEKES: Schutzleiter, Uhrzeitstellung und Kennfarben","url":"https://www.mennekes.at/industry/wissen/fuer-elektroprofi/schutzleiterkontakt-uhrzeitstellung-und-steckerfarben/"},{"label":"Bals: CEE-Norm und Pilotkontakt","url":"https://m.bals.com/news-und-wissen/lexikon/cee-norm"}],"minutes":4,"pdfPage":15},{"id":"D29","title":"Widerstandskennzeichnung","category":"Elektrotechnik","question":"Lies einen Widerstand mit vier Farbringen und erkläre alternative Beschriftungen. Nutze ein eigenes Zahlenbeispiel und unterscheide Wert, Multiplikator und Toleranz.","answer":[{"label":"Vier Ringe","text":"Ring 1 und 2 liefern die beiden Wertziffern, Ring 3 den Zehnerpotenz-Multiplikator, Ring 4 die Toleranz. Beispiel Rot–Violett–Braun–Gold: 27 × 10 Ω = 270 Ω ±5 %. Der meist abgesetzte Toleranzring hilft bei der Leserichtung."},{"label":"Ziffernfarben","text":"Schwarz 0, Braun 1, Rot 2, Orange 3, Gelb 4, Grün 5, Blau 6, Violett 7, Grau 8, Weiß 9. Als Multiplikator bedeuten Gold ×0,1 und Silber ×0,01; als Toleranz Gold ±5 % und Silber ±10 %."},{"label":"Weitere Kennzeichnungen","text":"Klartext wie 270 Ω oder 2,2 kΩ; Buchstaben als Dezimalzeichen wie 4R7 = 4,7 Ω und 2K2 = 2,2 kΩ; häufig dreistelliger SMD-Code 272 = 27 × 10² Ω = 2,7 kΩ. Kleine SMD-Bauteile können unbeschriftet sein. Für Sondercodes gilt das Datenblatt."}],"mnemonic":"Ziffer, Ziffer, Faktor, Fehlergrenze.","pitfall":"Vier Farbringe bedeuten zwei Wertziffern. Ein fünfbandiger Präzisionswiderstand verwendet normalerweise drei Wertziffern.","keywords":["Farbringe","Widerstand","Toleranz","Multiplikator","SMD-Code"],"sources":[{"label":"Vishay: Widerstandsfarbcode und E-Reihen","url":"https://www.vishay.com/docs/20143/colorcod.pdf"},{"label":"TE Connectivity: Widerstandsfarbcodes","url":"https://www.te.com/en/products/passive-active-electronic-components/resistors/intersection/resistor-color-codes.html"}],"minutes":4,"pdfPage":16},{"id":"D30","title":"Installationskanäle auswählen","category":"Elektrotechnik","question":"Du planst eine übersichtliche Leitungsführung. Vergleiche Kanalbauformen, Vorteile und Werkstoffe und erläutere die Schutzmaßnahme für leitfähige Kanalsysteme.","answer":[{"label":"Bauformen","text":"Leitungsführungskanal für die Wand, Brüstungs- beziehungsweise Geräteeinbaukanal, Sockelleistenkanal, Bodenkanal und Verdrahtungskanal im Schaltschrank sind Beispiele. Bauform und Einbauort müssen zusammenpassen."},{"label":"Vorteile","text":"Geordnete Leitungsführung mit mechanischem Schutz, leichterer Zugang bei Erweiterung und Wartung sowie Trennung unterschiedlicher Stromkreise durch geeignete Kammern oder Trennstege. Füllgrad, Wärmeabfuhr und Biegeradien bleiben zu berücksichtigen."},{"label":"Werkstoffe","text":"Kunststoffe, etwa PVC oder halogenfreie Ausführungen, sowie Stahlblech oder Aluminium. Auswahl nach mechanischer Belastung, Brandanforderungen, Korrosion und Umgebung."},{"label":"Metallkanäle","text":"Die Elektrofachkraft beurteilt und realisiert die erforderliche Schutzleiter- beziehungsweise Potentialausgleichseinbindung nach Systemzulassung und Norm. Elektrische Durchgängigkeit von Verbindern, Deckeln und Trennstegen sicherstellen und prüfen; eine lackierte Schraubverbindung genügt nicht automatisch. Den Kanal nicht ohne Zulassung als Schutzleiter verwenden."}],"mnemonic":"Ordnung, Schutz und Zugang brauchen auch Platz und Erdungskonzept.","pitfall":"Eine Metallabdeckung ist nicht allein durch Aufsetzen sicher elektrisch verbunden. Herstellerangaben zur Kontaktierung beachten.","keywords":["Installationskanal","Brüstungskanal","Verdrahtungskanal","Potentialausgleich","Metallkanal"],"sources":[{"label":"OBO: Planungshilfen Gebäudeinstallation","url":"https://www.obo.de/out/media/Planungshilfen-Gebaeudeinstallation_DE.pdf"}],"minutes":4,"pdfPage":16},{"id":"D31","title":"Vom Schaltplan zur Leiterplatte","category":"Elektrotechnik","question":"Beschreibe zwei typische Leiterplatten-Basismaterialien, den Zweck eines Layouts und zwei Wege zur Herstellung des Leiterbildes. Erläutere einen Fertigungsweg genauer.","answer":[{"label":"Basismaterialien","text":"FR-4 besteht aus Glasgewebe und Epoxidharz und ist weit verbreitet. FR-2 ist phenolharzgebundenes Hartpapier für einfachere Anwendungen. Eine Kupferkaschierung bildet die Grundlage der Leiterbahnen."},{"label":"Layout","text":"Das Layout legt reale Bauteilpositionen, Anschlussflächen, Leiterbahnen, Bohrungen und gegebenenfalls mehrere Kupferlagen fest. Es setzt die elektrische Netzliste räumlich um und berücksichtigt Stromtragfähigkeit, Abstände, EMV und Fertigbarkeit. Entwurf typischerweise mit CAD."},{"label":"Zwei Herstellungswege","text":"Fotolithografische Übertragung mit anschließendem Ätzen; alternativ Isolationsfräsen für geeignete Prototypen. Auch das direkte Aufbringen einer Ätzmaske ist bei einfachen Mustern möglich."},{"label":"Fotoverfahren im Überblick","text":"Das geplante Leiterbild wird durch Film oder Direktbelichtung auf einen lichtempfindlichen Resist übertragen. Entwickeln erzeugt die Schutzmaske; ungeschütztes Kupfer wird entfernt. Danach folgen weitere Bearbeitungs- und Prüfschritte. Chemikalien nur in geeigneter Werkstatt handhaben und fachgerecht entsorgen."}],"mnemonic":"Schaltplan verbindet logisch, Layout ordnet räumlich.","pitfall":"Das Foto einer bestückten Platine ist kein Layout. Basismaterial, Kupferlage und Lötstopplack erfüllen unterschiedliche Aufgaben.","keywords":["FR-4","FR-2","Layout","CAD","Fotolithografie","Isolationsfräsen"],"sources":[{"label":"Altium: Aufbau und Basismaterial einer Leiterplatte","url":"https://resources.altium.com/de/p/what-is-a-pcb"},{"label":"Eurocircuits: Leiterplattenfertigung","url":"https://www.eurocircuits.com/de/technische-richtlinien/leiterplattenfertigung/"}],"minutes":4,"pdfPage":17},{"id":"D32","title":"Wärme aus Elektronik abführen","category":"Elektrotechnik","question":"Ein Leistungsbauteil benötigt Kühlung. Erkläre geeignete Materialien und Bauformen, die Einflussgrößen auf den Wärmewiderstand, übliche Oberflächenfarben und die Aufgabe der Wärmeleitpaste.","answer":[{"label":"Material und Aufbau","text":"Häufig Aluminium wegen Gewicht, Kosten und guter Wärmeleitung; Kupfer bei höherem Bedarf an Wärmeleitung. Eine Auflagefläche nimmt Wärme vom Bauteil auf; Rippen, Stifte oder Lamellen vergrößern die Abgabefläche. Wärme gelangt durch Leitung, Konvektion und Strahlung an die Umgebung."},{"label":"Wärmewiderstand","text":"Rth = Temperaturdifferenz / Verlustleistung, Einheit K/W. Ein kleinerer Wert bedeutet bessere Wärmeabfuhr unter denselben Bedingungen. Entscheidend sind Werkstoff, Größe, Rippengeometrie, Einbaulage, Luftstrom, Einbauraum und Oberfläche. Datenblattwerte gelten nur für die angegebenen Prüfbedingungen."},{"label":"Oberflächen","text":"Typisch sind naturfarbenes beziehungsweise blankes Aluminium und schwarz eloxierte Oberflächen; andere Farben sind möglich. Eloxierung beeinflusst unter anderem Korrosionsschutz und Wärmestrahlung. Die Farbe allein bewertet keinen Kühlkörper."},{"label":"Wärmeleitpaste","text":"Sie füllt mikroskopische Unebenheiten und verdrängt schlecht leitende Luft zwischen Bauteil und Kühlkörper. Eine dünne, gleichmäßige geeignete Schicht reduziert den Übergangswiderstand. Erforderliche elektrische Isolierung muss durch dafür spezifizierte Materialien erfolgen."}],"mnemonic":"Große Fläche, guter Luftweg, kleiner Übergangswiderstand.","pitfall":"Wärmeleitpaste ersetzt keinen Kühlkörper und ist nicht automatisch elektrisch isolierend. Rth des Kühlkörpers ist nur ein Teil der gesamten Wärmekette.","keywords":["Kühlkörper","Aluminium","Kupfer","Wärmewiderstand","K/W","Wärmeleitpaste"],"sources":[{"label":"Seifert electronic: Wärmewiderstände von Kühlprofilen","url":"https://www.seifert-electronic.de/wp-content/uploads/2023/02/Thermische-Widerstaende-Kuehlprofile.pdf"}],"minutes":4,"pdfPage":17},{"id":"D33","title":"Schmelzsicherungen erkennen","category":"Elektrotechnik","question":"Ordne Schmelzsicherungen nach ihrer Bauform ein. Erkläre Kennmelder, Bemessungsstrom und Passeinsatz und nenne einen sicheren Grundsatz beim Austausch.","answer":[{"label":"Bauformen","text":"Schraubsicherungssysteme D/DIAZED und D0/NEOZED; NH-Sicherungen mit Messerkontakten; zylindrische Geräte- oder Feinsicherungen, etwa in Glas- oder Keramikausführung. Die Funktion entsteht durch einen bei Überstrom schmelzenden Leiter. Das im Katalog erwähnte Schaubild liegt zu D33 nicht bei."},{"label":"Kennmelder","text":"Er zeigt das Ansprechen eines dafür ausgestatteten Schmelzeinsatzes an, etwa durch Abfallen oder eine veränderte Anzeige. Der Kennmelder ersetzt weder eine elektrische Prüfung noch das Feststellen der Spannungsfreiheit."},{"label":"Strom erkennen","text":"Maßgeblich sind Aufdruck und Typdaten. Bei D/D0 unterstützt die Kennfarbe, beispielsweise Rot 10 A, Grau 16 A und Blau 20 A. Zusätzlich müssen Baugröße, Spannung, Ausschaltvermögen und Betriebsklasse passen."},{"label":"Passeinsatz und Austausch","text":"Passeinsätze verhindern im jeweiligen D/D0-System mechanisch das Einsetzen eines zu hoch bemessenen Einsatzes. Nicht entfernen oder überbrücken. Defekte Einsätze nur passend ersetzen; Ursache klären und Arbeiten an Verteilungen nach Sicherheitsregeln der Elektrofachkraft überlassen."}],"mnemonic":"Aufdruck bestimmt den Einsatz, Passeinsatz begrenzt ihn.","pitfall":"Eine größere Sicherung behebt keinen Überlastfehler. Farbe und Kennmelder allein beweisen keinen sicheren Zustand.","keywords":["Schmelzsicherung","DIAZED","NEOZED","NH","Kennmelder","Passeinsatz"],"sources":[{"label":"Elektro Technologie Zentrum: Schmelzsicherungen","url":"https://www.etz-stuttgart.de/multimedia/MM_UEBA_V2/ALLGEMEINE%2BDATEIEN_V2/Zentrale%2BDateien/X_Basics%2BET/X_Bauteile/Schmelzsicherungen-p-20029344.pdf"},{"label":"Hager: Sicherungsmaterial","url":"https://hager.com/de/loesungen/energieverteilung/sicherungsmaterial"}],"minutes":4,"pdfPage":18},{"id":"D34","title":"Kontaktwerkstoffe und Gleichstrom","category":"Elektrotechnik","question":"Wähle Kontaktmaterialien für unterschiedliche Aufgaben: Nenne Beispiele, begründe eine korrosionsbeständige Ausführung und erkläre die besonderen Anforderungen beim Schalten von Gleichstrom.","answer":[{"label":"Werkstoffe","text":"Kupfer und Kupferlegierungen dienen häufig als Kontaktträger. Für die Kontaktflächen kommen Silber und Silberlegierungen beziehungsweise Verbundwerkstoffe, etwa AgNi oder AgSnO₂, sowie Gold, Palladium oder Platin für passende Signalaufgaben infrage."},{"label":"Chemische Beständigkeit","text":"Geeignete Edelmetallkontakte, besonders Gold beziehungsweise Goldlegierungen für kleine Signale, widerstehen vielen korrosiven Einflüssen besser. Die Auswahl richtet sich nach konkreter Atmosphäre und Schaltlast. Eine dünne Goldauflage kann bei hoher Schaltenergie rasch abgetragen werden."},{"label":"Gleichstrom","text":"Es fehlt der natürliche Stromnulldurchgang des Wechselstroms. Ein Lichtbogen kann deshalb länger bestehen, Kontakte erodieren oder verschweißen. Ausschließlich für Spannung, Strom und Lastart geeignete DC-Schaltgeräte einsetzen; induktive Lasten benötigen die vom Hersteller vorgesehene Überspannungsbegrenzung. Polung oder Reihenschaltung von Polen nur gemäß Freigabe."}],"mnemonic":"Kleine Signale brauchen saubere Kontakte; DC braucht Lichtbogenbeherrschung.","pitfall":"Eine AC-Stromangabe lässt sich nicht unverändert auf DC übertragen. Gold ist kein universeller Kontaktwerkstoff für hohe Lasten.","keywords":["AgNi","AgSnO₂","Goldkontakt","Korrosion","Gleichstrom","Lichtbogen"],"sources":[{"label":"OMRON: Technische Grundlagen von Relais","url":"https://www.ia.omron.com/support/guide/36/further_information.html"},{"label":"TE Connectivity: Kontaktwerkstoffe und Lebensdauer","url":"https://www.te.com/en/products/relays-and-contactors/electromechanical-relays/intersection/relay-contact-life.html"}],"minutes":4,"pdfPage":18},{"id":"D35","title":"Leiterplatten und Multilayer","category":"Elektrotechnik","question":"Erkläre die Aufgaben einer Leiterplatte, unterscheide mindestens drei Ausführungen und beschreibe den inneren Aufbau sowie Nutzen eines Multilayers.","answer":[{"label":"Grundaufgabe","text":"Eine Leiterplatte trägt Bauteile mechanisch und verbindet sie elektrisch durch strukturierte Kupferflächen und Leiterbahnen auf einem isolierenden Träger. Lötflächen, Bohrungen und Schutzschichten ergänzen den Aufbau."},{"label":"Drei Ausführungen","text":"Einseitig: eine leitende Kupferlage. Doppelseitig: Kupfer auf beiden Seiten, bei Bedarf durch metallisierte Bohrungen verbunden. Mehrlagig beziehungsweise Multilayer: mehrere strukturierte Kupferlagen im verpressten Isolierstoffverbund. Daneben unterscheidet man starre, flexible und starrflexible Leiterplatten."},{"label":"Multilayer","text":"Innen- und Außenlagen werden durch isolierende Schichten getrennt und gezielt über Durchkontaktierungen verbunden. Dadurch sind kompakte Verdrahtung und definierte Signal-, Masse- und Versorgungslagen möglich. Der Lagenaufbau muss bereits im Layout auf Herstellung und elektrische Eigenschaften abgestimmt werden."}],"mnemonic":"Einseitig, doppelseitig, mehrlagig: Kupferlagen zählen.","pitfall":"Zwei bestückte Seiten bedeuten nicht automatisch einen Multilayer. Entscheidend ist die Anzahl leitender Lagen.","keywords":["Leiterplatte","einseitig","doppelseitig","Multilayer","Durchkontaktierung","Starrflex"],"sources":[{"label":"Würth Elektronik: Ein-, doppelseitige und Multilayer-Leiterplatten","url":"https://www.we-online.com/de/produkte/leiterplatten/basic"},{"label":"Eurocircuits: Leiterplattenfertigung","url":"https://www.eurocircuits.com/de/technische-richtlinien/leiterplattenfertigung/"}],"minutes":4,"pdfPage":19},{"id":"D36","title":"Wärmeschrumpfartikel","category":"Elektrotechnik","question":"Du legst Schrumpfmaterial für Kabelverbindungen bereit. Erkläre sachgerechte Lagerung, erforderliche Eigenschaften und mehrere Anwendungen.","answer":[{"label":"Lagerung","text":"Sauber, trocken, ohne mechanische Quetschung und nach Herstellerangaben lagern. Vor direkter Sonne, UV und Wärmequellen schützen, damit das Material nicht vorzeitig schrumpft oder altert. Lagerdauer und Lagertemperatur hängen vom Material ab; keine allgemeingültige Haltbarkeit annehmen."},{"label":"Eigenschaften","text":"Zum Einsatz passende elektrische Isolation, Temperatur- und Alterungsbeständigkeit sowie ausreichende mechanische Festigkeit. Je nach Umgebung sind Flammwidrigkeit, Medienbeständigkeit und UV-Beständigkeit nötig. Durchmesser vor und nach Schrumpfung, Schrumpfverhältnis, Wanddicke und gegebenenfalls Innenkleber müssen zur Verbindung passen."},{"label":"Anwendungen","text":"Isolation von Verbindungen, Scheuerschutz, Bündelung und Kennzeichnung; Kleberausführungen zum geeigneten Abdichten; Endkappen für Kabelenden und Formteile für Abzweige. Verarbeitung mit dem vorgesehenen Werkzeug und kontrollierter Wärmeeinwirkung, bei elektrischen Verbindungen im sicher getrennten Zustand."}],"mnemonic":"Kühl lagern, passend wählen, kontrolliert schrumpfen.","pitfall":"Nicht jeder Schrumpfschlauch dichtet gegen Wasser ab. Ein schwarzer Schlauch ist nicht automatisch für jede Außenanwendung geeignet.","keywords":["Schrumpfschlauch","Schrumpfverhältnis","Innenkleber","Isolation","Endkappe","Lagerung"],"sources":[{"label":"HellermannTyton: Wärmeschrumpfschläuche","url":"https://www.hellermanntyton.at/kompetenzen/schrumpfschlauch"}],"minutes":4,"pdfPage":19},{"id":"D37","title":"Dübel passend zum Untergrund","category":"Mechanik","question":"Vergleiche drei Dübelarten, wähle eine Befestigung für ein Rohr auf verputztem Mauerwerk unter begründeten Annahmen und erläutere Tragfähigkeit sowie Montageprinzip.","answer":[{"label":"Drei Bauarten","text":"Ein Kunststoffspreizdübel wird durch die Schraube gegen die Bohrlochwand gepresst. Ein Universaldübel kann je nach Untergrund spreizen, klappen oder verknoten. Ein Hohlraumdübel stützt sich hinter einer geeigneten Plattenwand ab; er ist kein beliebiger Ersatz für einen Mauerwerksdübel."},{"label":"Auswahl","text":"„Verputzt“ beschreibt nur die Deckschicht. Für tragfähigen Vollziegel oder Beton eignet sich beispielsweise ein dafür freigegebener Kunststoffspreiz- oder Universaldübel mit passender Schraube und ausreichender Verankerung im Grundmaterial. Bei Lochstein oder Porenbeton ist eine dafür geeignete Ausführung nötig. Die Putzschicht darf nicht als tragende Verankerungszone angesetzt werden."},{"label":"Belastbarkeit","text":"Entscheidend sind Art und Zustand des Baustoffs, Verankerungstiefe, Dübel- und Schraubenabmessungen, Zug- oder Querbelastung, Rand- und Achsabstände sowie die Montagequalität. Die Herstellerlasten gelten nur für ihre jeweiligen Randbedingungen."},{"label":"Montageprinzip am Spreizdübel","text":"Vor dem Bohren werden Leitungsverlauf und Untergrund geklärt. Bohrverfahren, Durchmesser und Tiefe folgen der Produktanleitung; anschließend wird das Bohrloch vorschriftsgemäß gereinigt. Der passende Dübel wird gesetzt und die Rohrschelle mit der vorgeschriebenen Schraube befestigt. Dabei entsteht durch das Spreizen die Haltewirkung; ein mitdrehender Dübel oder zerbröselnder Untergrund ist kein ordnungsgemäßer Sitz."}],"mnemonic":"Der tragende Untergrund bestimmt den Dübel; Putz allein trägt die Befestigung nicht.","pitfall":"Ein längerer Dübel erhöht die Tragfähigkeit nicht automatisch, wenn die Spreizzone im falschen Material liegt.","keywords":["Dübel","Mauerwerk","Putz","Verankerungstiefe","Spreizdübel","Hohlraumdübel"],"sources":[{"label":"fischer: Dübelratgeber und Untergrundwahl","url":"https://www.fischer.de/de-de/service/ratgeber/duebelratgeber"},{"label":"fischer: DuoPower, Verankerung und Putzüberbrückung","url":"https://www.fischer.de/de-de/produkte/standardbefestigungen/kunststoffduebel/duopower/duopower-2-komponenten-universalduebel"},{"label":"fischer Austria: Hinweise zur Montage","url":"https://www.fischer.at/de-at/service/wir-helfen-weiter/tipps"},{"label":"fischer: Bedingungen der angegebenen Haltewerte","url":"https://www.fischer-international.com/en/service/our-support/safety-important/german"}],"minutes":4,"pdfPage":20,"imagePage":40,"imagePages":[40]},{"id":"D38","title":"Haftung und Festigkeit beim Kleben","category":"Mechanik","question":"Erkläre die beiden maßgeblichen Bindungskräfte einer Klebung, nenne drei Klebstoffarten und stelle je zwei Vorteile und Nachteile gegenüber.","answer":[{"label":"Adhäsion und Kohäsion","text":"Adhäsion bezeichnet die Haftung zwischen Klebstoff und Fügeteiloberfläche. Dazu müssen Oberfläche und Klebstoff einander ausreichend benetzen und passende Wechselwirkungen aufbauen. Kohäsion bezeichnet den inneren Zusammenhalt der Klebstoffschicht. Die Verbindung ist nur tragfähig, wenn sowohl die Grenzflächen als auch die ausgehärtete beziehungsweise abgebundene Schicht genügend Festigkeit besitzen."},{"label":"Drei Klebstoffarten","text":"Epoxidharzklebstoffe sind häufig für feste Strukturverbindungen geeignet. Cyanacrylatklebstoffe ermöglichen schnelles Fügen kleiner, passend vorbereiteter Flächen. Polyurethanklebstoffe können je nach Rezeptur vergleichsweise elastische Verbindungen bilden. Die Anzahl der Komponenten und die Aushärtungsbedingungen hängen vom konkreten Produkt ab."},{"label":"Zwei Vorteile","text":"Kleben kann unterschiedliche Werkstoffe großflächig verbinden, ohne Bohrungen und deren Kerbwirkung zu benötigen. Außerdem erfolgt das Fügen meist mit geringerem Wärmeeintrag als beim Schweißen; eine geeignete Klebschicht kann zusätzlich abdichten."},{"label":"Zwei Nachteile","text":"Oberflächenvorbereitung und kontrollierte Aushärtung sind oft aufwendig und verzögern die Belastbarkeit. Temperatur, Alterung und chemische Einflüsse begrenzen die Anwendung; Schälbelastung ist bei vielen Klebungen ungünstig."}],"mnemonic":"Adhäsion hält an der Oberfläche, Kohäsion hält die Klebstoffschicht zusammen.","pitfall":"Hohe Klebstofffestigkeit allein hilft nicht, wenn eine verschmutzte oder schlecht benetzte Grenzfläche versagt.","keywords":["Kleben","Adhäsion","Kohäsion","Epoxidharz","Cyanacrylat","Polyurethan"],"sources":[{"label":"UHU: Grundlagen der Klebetechnik","url":"https://www.uhu.com/de-de/klebeberatung/klebetechnik"},{"label":"3M: Verbindungs- und Befestigungslösungen","url":"https://www.3mdeutschland.de/3M/de_DE/kleben-und-verbinden/oberflache/"},{"label":"proHPL: Reaktionsklebstoffe und Verarbeitung","url":"https://www.pro-hpl.org/assets/uploads/prohpl/files/220101_TM_Allgemeine_Verarbeitungsempfehlungen_fuer_HPL.pdf"}],"minutes":4,"pdfPage":20},{"id":"D39","title":"Strombelastbarkeit und Verlegung","category":"Elektrotechnik","question":"Zwei Leitungen gleichen Querschnitts können unterschiedlich belastbar sein. Begründe das und erläutere drei typische Referenzverlegearten für feste Leitungen.","answer":[{"label":"Einflussgrößen","text":"Leiterwerkstoff und Querschnitt, zulässige Isolierstofftemperatur, Umgebungstemperatur, Zahl belasteter Adern, Häufung sowie Art der Wärmeabfuhr bestimmen die Strombelastbarkeit. Wärmedämmung, Sonneneinstrahlung und ein geschlossener Kanal können sie verringern. Für Erdkabel kommen Bodenbedingungen hinzu."},{"label":"Drei Beispiele","text":"A2: mehradrige Leitung im Installationsrohr in einer wärmegedämmten Wand. B2: mehradrige Leitung im Rohr auf einer Wand. C: geeignete mehradrige Leitung direkt auf oder an einer Wand. Unterschiedliche thermische Bedingungen führen zu unterschiedlichen Tabellenwerten; die reale Ausführung muss zur Referenz passen."},{"label":"Dimensionierung","text":"Die Elektrofachkraft wählt die passende Normtabelle und berücksichtigt Korrekturfaktoren. Zusätzlich sind Spannungsfall, Kurzschlussfestigkeit und Schutzabschaltung nachzuweisen. Für einen üblichen Überlastschutz gilt als Auswahlbedingung IB ≤ IN ≤ IZ: Betriebsstrom, Bemessungsstrom der Schutzeinrichtung und zulässige Leitungsbelastbarkeit."}],"mnemonic":"Der Querschnitt leitet Strom, die Umgebung entscheidet über Wärme.","pitfall":"Gleicher Querschnitt bedeutet nicht gleiche Absicherung. Tabellenwerte ohne Verlegeart und Korrekturfaktoren sind keine fertige Auslegung.","keywords":["Strombelastbarkeit","A2","B2","C","Häufung","Spannungsfall"],"sources":[{"label":"LAPP: Strombelastbarkeit und Dimensionierung","url":"https://www.lapp.com/de/at/produkte/eigenschaften-technologien/elektrische-eigenschaften/strombelastbarkeit/e/071001"}],"minutes":4,"pdfPage":21},{"id":"D40","title":"Schraubverbindungen gezielt sichern","category":"Mechanik","question":"Unterscheide Sicherungsprinzip und Sicherungszweck, nenne vier geeignete Beispiele und erkläre die Ausführung sowie Grenzen zweier Sicherungen.","answer":[{"label":"Einteilung","text":"Mechanische Sicherungen lassen sich nach ihrem Wirkprinzip in kraftschlüssige beziehungsweise klemmende und formschlüssige Sicherungen einteilen. Chemische Schraubensicherungen ergänzen dies durch Stoffschluss. Nach dem Zweck sind Vorspannkraftverlust durch Lockern, selbsttätiges Losdrehen und vollständiger Verlust des Verbindungselements zu unterscheiden."},{"label":"Vier Möglichkeiten","text":"Beispiele sind eine Mutter mit Klemmteil, ein abgestimmtes Keilsicherungsscheibenpaar, eine Kronenmutter mit Splint und ein geeigneter Gewindesicherungsklebstoff. Die Auswahl richtet sich nach Belastung, Temperatur, Oberflächen und erforderlicher Wiederverwendbarkeit."},{"label":"Kronenmutter und Splint","text":"Eine dafür vorgesehene Schraube besitzt eine Querbohrung, die Mutter besitzt Kronenschlitze. Ein eingesetzter und gegen Herausfallen gesicherter Splint begrenzt das Weiterdrehen. Das ist vor allem eine formschlüssige Verliersicherung; begrenzte Drehbewegung und Vorspannkraftverlust bleiben möglich."},{"label":"Mutter mit Klemmteil","text":"Ein verformter metallischer Gewindebereich oder ein geeigneter Kunststoffeinsatz erzeugt zusätzliches Reibmoment im Gewinde. Der Einsatz ist bereits bei der Herstellung in die Mutter integriert. Temperaturgrenzen und Wiederverwendung sind produktabhängig. Das Klemmmoment darf nicht mit der für die Verbindung benötigten Vorspannkraft verwechselt werden."}],"mnemonic":"Zuerst das Versagen unterscheiden: Vorspannkraftverlust, Losdrehen oder Verlust.","pitfall":"Ein Splint sichert den Verbleib, aber nicht automatisch die Vorspannkraft; gewöhnliche Federringe sind keine pauschal wirksame Sicherung gegen dynamisches Losdrehen.","keywords":["Schraubensicherung","Vorspannkraft","Losdrehen","Klemmteil","Kronenmutter","Splint"],"sources":[{"label":"Bossard: Lockern, Losdrehen und Verliersicherungen","url":"https://assets.eu.ctfassets.net/0vp0u5uh75zd/4sP1THZ8d8OFO95VbhBonq/81c948affa9638b61ce85f060a0a5a44/075_077_Sichern_Schraubverbindungen_Fastening_DE_01_2025.pdf"},{"label":"Würth Industrie Service: Sicherung gegen Losdrehen","url":"https://www.wuerth-industrie.com/web/de/wuerthindustrie/technikportal/technische_informationen___tools/schraubensicherung_3/sicherung-gegen-losdrehen.php"}],"minutes":4,"pdfPage":21,"imagePage":41,"imagePages":[41]},{"id":"D41","title":"Aktive und passive Sensorprinzipien","category":"Automation","question":"Ordne ein Thermoelement und einen Pt100 nach ihrem Messprinzip ein. Erkläre die zwei Gruppen und zeige, warum die Einteilung nicht dasselbe wie analog oder binär bedeutet.","answer":[{"label":"Aktiv nach Messprinzip","text":"Ein aktives, auch generatorisches Sensorelement erzeugt das elektrische Messsignal aus der Messgröße selbst. Beispiel: Ein Thermoelement erzeugt eine Spannung infolge einer Temperaturdifferenz. Das Sensorelement benötigt hierfür keine elektrische Anregung; eine angeschlossene Auswerteelektronik kann trotzdem Versorgung benötigen."},{"label":"Passiv nach Messprinzip","text":"Ein passives, auch parametrisches Element verändert eine elektrische Größe wie Widerstand, Kapazität oder Induktivität. Ein Pt100 ändert seinen Widerstand mit der Temperatur. Um diese Änderung auszuwerten, wird ein Messstrom beziehungsweise eine Anregung benötigt."},{"label":"Andere Einteilungen","text":"Analog oder binär beschreibt das Ausgangssignal: stetiger Messwert oder zwei Zustände. Beide thermischen Beispiele liefern zunächst analoge Informationen. In Datenblättern kann aktiv auch einen versorgten Sensor mit Elektronik bezeichnen; deshalb die verwendete Definition ausdrücklich nennen."}],"mnemonic":"Aktiv erzeugt, passiv verändert; analog und binär beschreiben das Signal.","pitfall":"Die Behauptung aktiv = binär und passiv = analog ist falsch. Auch Hilfsenergie und Messprinzip dürfen nicht ohne Definition vermischt werden.","keywords":["aktiver Sensor","passiver Sensor","generatorisch","parametrisch","Thermoelement","Pt100"],"sources":[{"label":"Rössel Messtechnik: Aktive und passive Sensoren","url":"https://www.roessel-messtechnik.de/de/infothek/faq.html"}],"minutes":4,"pdfPage":22},{"id":"D42","title":"Analoge Weg- und Winkelerfassung","category":"Automation","question":"Erkläre die Bedeutung eines analogen Sensors. Beschreibe ein Linearpotentiometer als Wegsensor und nenne Anwendungen für lineare und drehende Potentiometer.","answer":[{"label":"Analoges Signal","text":"Der Ausgang kann innerhalb seines Messbereichs stetig abgestufte Werte annehmen, etwa eine wegabhängige Spannung oder ein aufbereitetes Stromsignal. Im Unterschied zu einem binären Schalter wird nicht nur eine Grenzposition erkannt."},{"label":"Linearpotentiometer","text":"Es besitzt eine Widerstandsbahn mit zwei Endanschlüssen und einen beweglichen Schleifer als dritten Anschluss. Eine mechanisch gekoppelte Schubstange bewegt den Schleifer entlang der Bahn. Mit Versorgung zwischen den Enden bildet der Schleifer einen Spannungsteiler; bei linearer Bahn und hochohmiger Auswertung ist die Ausgangsspannung proportional zum Weg."},{"label":"Anwendungen","text":"Linear: Hubrückmeldung an Zylindern, Position eines Schlittens oder einer Pressenachse. Drehend: Winkelrückmeldung eines Stellventils, Joystick oder manueller Sollwertgeber. Geeigneten Messbereich und mechanische Endlagen beachten; ein Standardsensor ersetzt keine Sicherheitsüberwachung."}],"mnemonic":"Drei Anschlüsse teilen Spannung nach Weg oder Winkel.","pitfall":"Ein potentiometrischer Präzisionsweggeber soll normalerweise hochohmig als Spannungsteiler ausgewertet werden. Eine Schleiferlast kann die Kennlinie verfälschen.","keywords":["analog","Linearpotentiometer","Drehpotentiometer","Schleifer","Spannungsteiler","Wegmessung"],"sources":[{"label":"Novotechnik: Messprinzip potentiometrischer Sensoren","url":"https://www.novotechnik.de/fileadmin/user_upload/pdfs/news/presse/Pressemitteilung_nov218_Crashtest-Dummys.pdf"}],"minutes":4,"pdfPage":22},{"id":"D43","title":"Gesundheit und verwertbare Abfälle","category":"Sicherheit","question":"Beurteile eine Werkstattumgebung: Welche Einwirkungen können die Gesundheit schädigen, und welche sauber getrennten Werkstoffreste eignen sich gut zur Wiederverwertung?","answer":[{"label":"Einwirkungen","text":"Lärm kann das Gehör schädigen; Vibrationen belasten Hände, Gelenke oder Rücken. Hitze, Kälte, Zugluft und schlechte Beleuchtung erhöhen Belastung und Unfallrisiko. Stäube, Rauch, Dämpfe und Gase können Atemwege oder Organe schädigen. Je nach Tätigkeit kommen UV-/Laserstrahlung oder andere physikalische Einwirkungen hinzu."},{"label":"Gut verwertbare Fraktionen","text":"Sortenreine, möglichst saubere Reste aus Stahl, Aluminium und Kupfer; getrenntes Glas sowie Papier und Karton. Auch getrennte, eindeutig bekannte Thermoplaste lassen sich häufig verwerten. Sammlung nach betrieblichem Entsorgungskonzept und lokalen Annahmebedingungen."},{"label":"Trennung erhalten","text":"Gefährliche Stoffe, ölverschmutzte Späne, Batterien und Elektroaltgeräte getrennt erfassen. Materialverbunde und starke Verunreinigungen erschweren Recycling. Gefährdungen zuerst an der Quelle mindern, etwa durch Absaugung und Lärmminderung, ergänzt durch Organisation und geeignete PSA."}],"mnemonic":"Belastungen an der Quelle senken, Stoffe an der Quelle trennen.","pitfall":"Recyclingfähig bedeutet nicht, dass beliebig verunreinigte oder gefährliche Reste in die normale Wertstoffsammlung gehören.","keywords":["Lärm","Vibration","Staub","Gefahrstoffe","Recycling","Sortenreinheit"],"sources":[{"label":"Gesundheit.gv.at: Belastungen am Arbeitsplatz","url":"https://www.gesundheit.gv.at/leben/lebenswelt/beruf/arbeitsplatz/ergonomie-am-arbeitsplatz.html"},{"label":"Österreich.gv.at: Abfallvermeidung und Mülltrennung","url":"https://www.oesterreich.gv.at/de/themen/bauen_und_wohnen/abfall/Seite.3790051"}],"minutes":4,"pdfPage":23},{"id":"D44","title":"Kältemittel und Elektroaltgeräte","category":"Sicherheit","question":"Nenne zwei konkrete Kältemittel und fünf gesundheitsschädliche Stoffe aus dem technischen Umfeld. Erläutere die sachgerechte Abgabe ausgedienter Elektrogeräte in Österreich.","answer":[{"label":"Zwei Kältemittel","text":"R600a ist Isobutan, R290 ist Propan. Beide sind brennbare Kohlenwasserstoffe und werden in dafür konstruierten Kälteanlagen verwendet. Welches Mittel ein Gerät enthält, steht am Typenschild. Kältekreisläufe nicht öffnen oder beschädigen; Arbeiten und Rückgewinnung qualifizierten Fachbetrieben überlassen."},{"label":"Elektroaltgeräte","text":"Getrennt vom Restmüll an zugelassenen Sammelstellen beziehungsweise über die vorgesehene Rücknahme abgeben. Für Haushaltsgeräte bieten kommunale Sammelstellen eine kostenlose Abgabe; Handelsrücknahme richtet sich nach den gesetzlichen Bedingungen. Gewerbliche Geräte haben teilweise andere Rücknahmewege. Kühlgeräte vollständig und unbeschädigt einer fachgerechten Behandlung zuführen."},{"label":"Fünf Beispiele","text":"Blei, Quecksilber, Cadmium, Verbindungen mit sechswertigem Chrom und der Weichmacher DEHP sind gesundheitsschädliche Beispiele. Gefährdung und Schutz richten sich nach Stoffform, Menge und Exposition. Kennzeichnung, Sicherheitsdatenblätter und betriebliche Entsorgungsregeln beachten."}],"mnemonic":"Kältemittel am Schild lesen, Altgeräte getrennt abgeben.","pitfall":"R600a ist Isobutan, kein beliebiges Propan-Butan-Gemisch. Nicht jedes FCKW-freie Kältemittel ist unbrennbar oder klimaneutral.","keywords":["R600a","R290","Isobutan","Propan","Elektroaltgeräte","Schadstoffe"],"sources":[{"label":"EMSD: Sicherheit brennbarer Kältemittel","url":"https://www.emsd.gov.hk/filemanager/en/content_2/EMSDnFSDnLD_Joint_Notice.pdf"},{"label":"USP Österreich: Elektroaltgeräte und Rücknahme","url":"https://www.usp.gv.at/themen/betrieb-und-umwelt/abfallrecht/weitere-informationen-abfallrecht/abfall-und-produktregelungen/elektroaltgeraete/elektroaltgeraete-hersteller-eigenimporteure-haendler.html"},{"label":"RIS: Elektroaltgeräteverordnung § 4, Stoffbeschränkungen","url":"https://ris.bka.gv.at/NormDokument.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20004052&Paragraf=4"}],"minutes":4,"pdfPage":23},{"id":"D45","title":"Industrielle Datennetze verkabeln","category":"Automation","question":"Vergleiche gebräuchliche Industrie-Netzwerkstecker und Übertragungsleitungen. Erkläre UTP, FTP und STP und nutze eindeutige moderne Schirmungsbezeichnungen.","answer":[{"label":"Steckverbinder","text":"RJ45, auch in robusten Industriegehäusen; M12 mit D-Codierung für entsprechende Ethernet-Anwendungen und X-Codierung für höhere Datenraten. Je nach Bussystem auch D-Sub oder spezifische Busstecker. Für Lichtwellenleiter sind beispielsweise LC- oder SC-Verbindungen üblich. Steckgesicht, Codierung und System müssen zusammenpassen."},{"label":"Leitungen","text":"Verdrillte Kupferadernpaare für Ethernet und viele Feldbusse, systemspezifische Koaxialleitungen sowie Glas- oder Kunststoff-Lichtwellenleiter. Auswahl nach Übertragungsstrecke, Datenrate, EMV, mechanischer Beanspruchung und Umgebung; die Farbe allein identifiziert kein Kabel."},{"label":"Abkürzungen","text":"UTP = Unshielded Twisted Pair, ungeschirmte verdrillte Paare. FTP = Foiled Twisted Pair, Folienabschirmung. STP = Shielded Twisted Pair, ältere Sammelbezeichnung für geschirmte Paare beziehungsweise Kabel; ihre genaue Bedeutung ist nicht überall einheitlich."},{"label":"Eindeutige Schreibweise","text":"U/UTP: weder Gesamt- noch Paarschirm. F/UTP: gemeinsamer Folienschirm, Paare ohne Einzelschirm. U/FTP: jedes Paar in Folie, ohne Gesamtschirm. S/FTP: Gesamtgeflecht plus Folie je Paar. Vor dem Schrägstrich steht der Gesamtschirm, dahinter der Paarschirm."}],"mnemonic":"Vor dem Schrägstrich das Ganze, dahinter die einzelnen Paare.","pitfall":"UPT und SPT im Ausgangskatalog sind Schreibfehler für UTP und STP. Aus der alten Angabe STP allein folgt keine eindeutige Schirmkonstruktion.","keywords":["RJ45","M12","Twisted Pair","UTP","FTP","STP","S/FTP"],"sources":[{"label":"HARTING: Industrielle Ethernet-Schnittstellen","url":"https://www.harting.com/de-DE/industrielle-ethernet-loesungen"},{"label":"Schneider Electric: Schirmungsbezeichnungen für Twisted Pair","url":"https://www.se.com/fr/fr/faqs/FA18636/"}],"minutes":4,"pdfPage":24},{"id":"D46","title":"Kabeleinführungen dicht und isoliert","category":"Elektrotechnik","question":"Eine Leitung soll in ein Gehäuse eingeführt werden. Welche Bauteile erhalten die Schutzart, welche Auswahl- und Montagepunkte sind wichtig und was ist bei einem schutzisolierten Kunststoffgehäuse besonders zu beachten?","answer":[{"label":"Geeignete Einführung","text":"Passende Kabelverschraubung, dafür zugelassene Durchführungstülle oder Dichteinsatz verwenden. Sie dichten Gehäuse und Kabelmantel ab; eine geeignete Verschraubung übernimmt zusätzlich Zugentlastung und gegebenenfalls Knickschutz. Unbenutzte Öffnungen mit geeigneten Blindteilen schließen."},{"label":"Auswahl und Montage","text":"Gewinde, Wandstärke, Klemm- und Dichtbereich müssen zum tatsächlichen Außendurchmesser und Kabel passen. Vorgesehene Dichtungen und Drehmomente einhalten, Mantel unbeschädigt klemmen und Biegeradius beachten. IP-Schutzart, Temperatur, UV-, Medien- und gegebenenfalls EMV-/Ex-Anforderungen für das gesamte System prüfen. Nicht ohne freigegebenen Mehrfachdichteinsatz mehrere Kabel in eine Einfachdichtung pressen."},{"label":"Isolierstoffgehäuse","text":"Bei Schutzklasse II darf die Durchführung die doppelte beziehungsweise verstärkte Isolierung nicht überbrücken. Geeignete isolierende Einführungen gemäß Gehäusefreigabe verwenden. Eine beliebige Metallverschraubung mit innenliegender Gegenmutter kann die Schutzisolierung beeinträchtigen; die Schutzklasse ist von der Elektrofachkraft zu beurteilen."}],"mnemonic":"Dicht am Mantel, passend zur Wand, Schutzklasse erhalten.","pitfall":"IP-Schutzart gegen Fremdkörper und Wasser ist etwas anderes als Schutzklasse gegen elektrischen Schlag. Ein Kunststoffgehäuse allein garantiert keine Schutzklasse II.","keywords":["Kabelverschraubung","IP-Schutzart","Zugentlastung","Schutzklasse II","Isolierstoffgehäuse"],"sources":[{"label":"LAPP: Kabelverschraubungen und Abdichtung","url":"https://www.lapp.com/de/de/produkte/kabelverschraubungen/einfacheinfuehrungen/c/113981"},{"label":"LANUK NRW: Elektrotechnisches Ausbildungs-Handbuch, Schutzisolierung","url":"https://www.lanuk.nrw.de/fileadmin/lanuvpubl/0_lua/hndbetec.pdf"}],"minutes":4,"pdfPage":24},{"id":"E1","title":"Ein Ventil erhält keinen wirksamen Befehl","category":"Automation","question":"An einer Maschine reagiert ein 24-V-Magnetventil mit SPS-Transistorausgang nicht. Entwirf eine sichere Diagnosekette, erkläre den Ersatz von Hilfsschützen und definiere die Übertragungsrate.","answer":[{"label":"Sicher beginnen","text":"Fehlerbild, letzte Änderungen, Stromlauf- und Pneumatikplan sowie Meldungen aufnehmen. Gefährliche Bewegungen verhindern; Eingriffe nur durch beauftragtes Fachpersonal mit gesicherten Energiequellen. Auch ein 24-V-Steuersignal kann gefährliche Maschinenbewegungen auslösen."},{"label":"Signalweg eingrenzen","text":"Freigaben und Verriegelungen, SPS-Betriebszustand, Programmbedingung und Ausgangsdiagnose prüfen. Danach Lastversorgung, gemeinsame Bezugspotentiale, Stecker und Leitung, passende PNP-/NPN-Beschaltung, Ausgangsbelastbarkeit sowie Spule und Schutzbeschaltung beurteilen. Qualifizierte elektrische Prüfungen folgen dem freigegebenen Prüfplan. Ist die elektrische Ansteuerung in Ordnung, Druckversorgung, Vorsteuerung, Durchflussrichtung und mechanisches Klemmen untersuchen."},{"label":"Hilfsschütze ersetzen","text":"Reine Logikfunktionen lassen sich durch Programmverknüpfungen, Merker, Zeiten und Zähler ersetzen. Für Lastanpassung oder Potentialtrennung können geeignete Koppelrelais beziehungsweise Halbleiterstufen erforderlich bleiben. Eine Standard-SPS ersetzt keine geforderte Sicherheitsfunktion."},{"label":"Übertragungsrate","text":"Datenmenge je Zeit, meist in bit/s, kbit/s oder Mbit/s. 1 Mbit/s entspricht einer Million Bit pro Sekunde. Protokoll- und Verwaltungsdaten verringern den nutzbaren Datendurchsatz. Baud bezeichnet Symbole je Sekunde und ist nicht immer gleich bit/s."}],"mnemonic":"Befehl, Ausgang, Leitung, Spule, Pneumatik.","pitfall":"Eine leuchtende Ausgangs-LED beweist weder ausreichende Spannung an der Spule noch einen funktionsfähigen Ventilmechanismus. Ausgänge nicht ungesichert erzwingen.","keywords":["Magnetventil","Transistorausgang","PNP","NPN","Hilfsschütz","bit/s"],"sources":[{"label":"Siemens: Dokumentation S7-1200","url":"https://support.industry.siemens.com/cs/ww/de/view/109744173"},{"label":"Festo: Störungsbeseitigung und Herstellerdokumentation","url":"https://www.festo.com/de/de/e/support/support-erhalten/hilfe-und-stoerungsbeseitigung-id_21652"},{"label":"AUVA: Fünf Sicherheitsregeln","url":"https://auva.at/praevention/medien-und-publikationen/publikationen-us/5-sicherheitsregeln-110-x-80-mm/"}],"minutes":4,"pdfPage":42},{"id":"E2","title":"Gleichrichter liefert zu wenig Spannung","category":"Elektrotechnik","question":"Bei einem Brückengleichrichter fällt der gemessene Gleichanteil deutlich ab. Erkläre einen möglichen Diodenfehler, eine fachgerechte Diodenprüfung und den Begriff Kommunikationsprotokoll.","answer":[{"label":"Plausible Ursache","text":"Eine unterbrochene Diode kann einen der beiden Strompfade der Brücke sperren. Statt beider Halbwellen wird nur noch eine genutzt. Ohne Glättung und bei vergleichbarer Last kann der Gleichspannungsmittelwert ungefähr halbiert sein; die Pulsfrequenz sinkt von 2f auf f. Mit Siebkondensator ist die genaue Spannung last- und kapazitätsabhängig. Das Symptom allein beweist diesen Fehler nicht."},{"label":"Diodenprüfung","text":"Nur an sicher spannungsfreiem, fachgerecht entladenem Gerät prüfen; bei netzverbundenen Geräten durch Elektrofachkräfte. Parallele Schaltungspfade nötigenfalls durch fachgerechtes Trennen eines Anschlusses ausschließen. Im Diodentest zeigt eine normale Si-Diode in Durchlassrichtung typisch etwa 0,5–0,8 V und in Sperrrichtung OL. Sehr klein in beiden Richtungen spricht für Kurzschluss, OL in beiden für Unterbrechung."},{"label":"Protokoll","text":"Vereinbarte Regeln für den Datenaustausch: zum Beispiel Nachrichtenaufbau, Adressierung, Bedeutung der Daten, zeitlicher Ablauf und Fehlererkennung. Teilnehmer benötigen zueinander passende Protokolle; ein passender Stecker genügt nicht."}],"mnemonic":"Fehlt eine Halbwelle, fehlt ein Strompfad.","pitfall":"Halbe Ausgangsspannung bedeutet nicht immer genau eine defekte Diode. Glättung, Last, Versorgung und Messart beeinflussen den Wert.","keywords":["Brückengleichrichter","Graetz","Diode","Einweggleichrichtung","Diodentest","Protokoll"],"sources":[{"label":"Fluke: Fehler an Gleichrichtern verstehen","url":"https://media.fluke.com/275d3144-9c10-4f5d-992d-b1060066d6cf_original%20file.pdf"},{"label":"Fluke: Diodenprüfung","url":"https://www.fluke.com/de-at/mehr-erfahren/blog/digitalmultimeter/anleitung-zum-pruefen-von-dioden"}],"minutes":4,"pdfPage":42},{"id":"E3","title":"Stern-Dreieck-Anlauf startet nicht","category":"Elektrotechnik","question":"Eine Stern-Dreieck-Steuerung reagiert auf den Startbefehl nicht. Beschreibe ein strukturiertes, sicheres Vorgehen und erkläre anschließend den Begriff Netzwerktopologie.","answer":[{"label":"Auftrag und Sicherheit","text":"Störung und Sollablauf anhand des Plans verstehen; Maschine gegen unbeabsichtigtes Anlaufen sichern. Elektrische Eingriffe nur als beauftragte Fachkraft und grundsätzlich im freigeschalteten, gesicherten und auf Spannungsfreiheit geprüften Zustand. Not-Halt oder Verriegelungen nicht überbrücken."},{"label":"Kette statt Teiletausch","text":"Zunächst Versorgung und Schutzgeräte anhand der vorgesehenen Anzeigen kontrollieren. Im Steuerpfad schrittweise Sicherung und Steuerspannungsversorgung, Stop-/Freigabekette, Motorschutzkontakt, Starttaster und Verdrahtung eingrenzen. Danach Spulendaten, Spulen, Selbsthaltung, elektrische und mechanische Verriegelung sowie Zeitrelais beurteilen. Messungen legt die Elektrofachkraft nach Gefährdungsbeurteilung fest. Nach Reparatur vollständigen sicheren Ablauf und Verriegelung prüfen und dokumentieren."},{"label":"Topologie","text":"Sie beschreibt die physische oder logische Verknüpfung der Netzwerkteilnehmer. Beispiele: Linie, Bus, Stern, Ring und Baum. Bei einem Stern sind Teilnehmer mit einem zentralen Knoten verbunden; ein Ring besitzt einen geschlossenen Verbindungsweg."}],"mnemonic":"Vom gemeinsamen Freigabepfad bis zur Spule eingrenzen.","pitfall":"Wenn gar kein Schütz anzieht, zuerst gemeinsame Bedingungen untersuchen. Ein überbrückter Schutzkontakt kann einen Fehler verdecken und Menschen gefährden.","keywords":["Stern-Dreieck","Schütz","Freigabekette","Verriegelung","Topologie"],"sources":[{"label":"AUVA: Fünf Sicherheitsregeln","url":"https://auva.at/praevention/medien-und-publikationen/publikationen-us/5-sicherheitsregeln-110-x-80-mm/"},{"label":"ABB: Prüfung und Wartung von Schützen und Motorstartern","url":"https://library.e.abb.com/public/a1a9d7b1b9c3495f9282037d0c4fcaaa/2CDC101005M0101.pdf"}],"minutes":4,"pdfPage":43},{"id":"E4","title":"Drehstrommotor anschließen und schützen","category":"Elektrotechnik","question":"Plane den Anschluss eines Drehstrommotors auf fachlicher Ebene. Welche Daten bestimmen die Zuleitung, welche Schutzgeräte kommen infrage und was muss vor der Freigabe zur Inbetriebnahme geprüft oder eingestellt sein?","answer":[{"label":"Zuleitung","text":"Ausgangspunkt ist der Motor-Bemessungsstrom bei richtiger Spannung und Schaltung. Zusätzlich Anlaufstrom und Anlaufdauer, Leitungslänge und Spannungsfall, Leiterwerkstoff, belastete Adern, Verlegeart, Häufung, Umgebungstemperatur und mechanische Einflüsse berücksichtigen. Schutzleiter, Kurzschlussfestigkeit und rechtzeitige Schutzabschaltung sind ebenfalls auszulegen. Ein pauschaler Querschnitt allein nach kW genügt nicht."},{"label":"Motorschutz","text":"Motorschutzschalter mit thermischem und magnetischem Auslöser; Überlastrelais oder elektronische Schutzgeräte mit passendem Schalt- und Kurzschlussschutz; direkte Temperaturüberwachung, etwa PTC-Fühler in der Wicklung. Eine Kurzschlusssicherung allein schützt nicht zuverlässig gegen jede Motorüberlastung."},{"label":"Vor der Freigabe","text":"Elektrofachkraft prüft Versorgung, Typenschild, Anschlussbild und Stern-/Dreieck-Eignung; Schutzleiter, Isolation und weitere erforderliche Schutzmaßnahmen; Klemmen, Zugentlastung, mechanische Befestigung, freie Kühlung und sichere Lastanbindung. Motorschutz, Anlaufzeiten und gegebenenfalls Umrichterdaten passend einstellen. Der Einstellstrom hängt auch vom Einbauort des Schutzgeräts ab. Drehrichtung und Sicherheitsfunktionen mit geschütztem Prüfablauf erproben und Ergebnisse dokumentieren."}],"mnemonic":"Typenschild, Leitung, Schutz und Mechanik gemeinsam prüfen.","pitfall":"Motorschutz nicht höher einstellen, damit der Motor durchläuft. Stern oder Dreieck wird aus Netzspannung und Typenschild abgeleitet.","keywords":["Drehstrommotor","Zuleitung","Motorschutz","PTC","Inbetriebnahme","Typenschild"],"sources":[{"label":"LAPP: Strombelastbarkeit und Dimensionierung","url":"https://www.lapp.com/de/at/produkte/eigenschaften-technologien/elektrische-eigenschaften/strombelastbarkeit/e/071001"},{"label":"WEG: Sicherheit, Anschluss, Schutz und Wartung von Motoren","url":"https://static.weg.net/medias/downloadcenter/h8e/h88/WEG-WMO-safe-area-50031071-manual-en-es.pdf"},{"label":"Siemens: SIRIUS 3RW30/3RW40, Motorschutz","url":"https://support.industry.siemens.com/dl/files/095/38752095/att_1310809/v1/Manual_softstarter_3RW30_3RW40_de-DE.pdf"}],"minutes":4,"pdfPage":43},{"id":"E5","title":"Sicher, zuverlässig und übersichtlich","category":"Sicherheit","question":"Eine Elektroinstallation soll Menschen schützen, zuverlässig arbeiten und gut beherrschbar bleiben. Erkläre diese drei Ziele und nenne zu jedem drei konkrete Gestaltungsmaßnahmen.","answer":[{"label":"Unfallsicherheit","text":"Menschen vor elektrischem Schlag, Verbrennung und anderen Gefahren schützen. Drei Maßnahmen: wirksamer Berührungsschutz durch Isolation beziehungsweise Abdeckungen; fachgerecht ausgeführte Schutzmaßnahme mit Schutzleiter und automatischer Abschaltung, wo vorgesehen; sichere Trenn- und Notfallfunktionen mit geeignetem Zugangsschutz. Ein RCD ergänzt nur die dafür vorgesehenen Schutzkonzepte."},{"label":"Betriebssicherheit","text":"Die Anlage erfüllt ihre Aufgabe unter erwartbaren Bedingungen ohne unzulässige Erwärmung oder Ausfälle. Drei Maßnahmen: Leitungen und Schaltgeräte für die Belastung auslegen; Schutzgeräte passend auswählen und koordinieren; Umgebung berücksichtigen, zum Beispiel Schutzart, Kühlung und EMV, und planmäßige Wartung vorsehen."},{"label":"Übersichtlichkeit","text":"Bedienung, Prüfung und Fehlersuche müssen eindeutig möglich sein. Drei Maßnahmen: Betriebsmittel, Leiter und Klemmen dauerhaft kennzeichnen; Schaltpläne und Dokumentation aktuell halten; geordnete Leitungswege, sinnvolle räumliche Gruppierung und erforderliche Trennung von Stromkreisen schaffen."},{"label":"Umsetzung","text":"Errichtung und elektrische Prüfung sind Aufgaben der dafür qualifizierten Fachkräfte nach den anwendbaren österreichischen Regeln. Die drei Ziele ergänzen einander und müssen gemeinsam erfüllt werden."}],"mnemonic":"Menschen schützen, Funktion sichern, Zusammenhänge sichtbar machen.","pitfall":"Ein ordentlicher Schaltschrank ist nicht automatisch elektrisch sicher. Kennzeichnung ersetzt keine Schutzprüfung.","keywords":["Unfallsicherheit","Betriebssicherheit","Übersichtlichkeit","Kennzeichnung","Schutzmaßnahme"],"sources":[{"label":"OVE: OVE E 8101, Ausgabe 2025-10-01","url":"https://www.ove.at/ove-standardization/normen-produkte/ove-e-8101/"}],"minutes":4,"pdfPage":44},{"id":"E6","title":"Systematische Fehlersuche verstehen","category":"Elektrotechnik","question":"Welche Voraussetzungen braucht methodische Fehlersuche? Ordne typische Fehler und Ursachen einer Leitungsunterbrechung ein und erkläre das Spannungsprinzip der Unterbrechungssuche ohne eine Anleitung für Arbeiten an Netzspannung zu geben.","answer":[{"label":"Voraussetzung","text":"Die Sollfunktion, den aktuellen Schaltplan und die Signal-/Energiekette verstehen. Dazu kommen passende Fachqualifikation, ein sicherer Arbeitsauftrag, geeignete Prüfmittel und die Kenntnis der Schutzmaßnahmen. Fehlerbild, Zeitpunkt und letzte Änderungen erfassen, dann Hypothesen gezielt prüfen."},{"label":"Fehlerarten","text":"Elektrische, mechanische und Steuerungs-/Parametrierfehler; sie können dauerhaft oder zeitweise auftreten. Häufige elektrische Ursachen sind Unterbrechung, Kurzschluss, Erd- oder Körperschluss, hoher Übergangswiderstand, falscher Anschluss und fehlende Versorgung."},{"label":"Unterbrechung","text":"Mögliche Ursachen: Leiterbruch durch Biegung oder Schwingung, lose beziehungsweise fehlerhaft verpresste Klemme, Korrosion, thermische Schädigung oder mechanische Beschädigung. Auch eine ausgelöste Sicherung oder ein offener Schaltkontakt kann den Strompfad unterbrechen."},{"label":"Spannungsprinzip","text":"Theoretisch fällt bei einem geschlossenen, nahezu ideal leitenden Abschnitt fast keine Spannung ab. Über einer Unterbrechung kann unter definierten Schaltungsbedingungen nahezu die Versorgungsspannung liegen. Rückspeisung, Parallelpfade und hochohmige Messgeräte können die Deutung verfälschen. Die Fachkraft entscheidet über ein sicheres Messverfahren; zum Lernen dient ein strombegrenztes Schutzkleinspannungsmodell. Reparaturen und Widerstands-/Durchgangsprüfungen erfolgen im nachgewiesen spannungsfreien Zustand."}],"mnemonic":"Sollzustand kennen, Fehler eingrenzen, Ursache belegen.","pitfall":"Null Volt an einer einzelnen Messstelle beweist keine Spannungsfreiheit. Ein zufälliger Bauteiltausch ist keine methodische Diagnose.","keywords":["Fehlersuche","Unterbrechung","Kurzschluss","Körperschluss","Übergangswiderstand","Spannungsabfall"],"sources":[{"label":"DGUV: Betrieb elektrischer Anlagen und Betriebsmittel","url":"https://publikationen.dguv.de/widgets/pdf/download/article/313"},{"label":"LANUK NRW: Elektrotechnisches Ausbildungs-Handbuch, Schutzisolierung","url":"https://www.lanuk.nrw.de/fileadmin/lanuvpubl/0_lua/hndbetec.pdf"}],"minutes":4,"pdfPage":44},{"id":"E7","title":"Störungssuche sicher beginnen","category":"Sicherheit","question":"Nenne zwei erste Prüfgedanken bei einer elektrischen Störung. Welche Fehler werden spannungsfrei untersucht, und welche Messgeräte unterstützen die Eingrenzung von Kurzschluss- und Isolationsfehlern?","answer":[{"label":"Zwei erste Prüfungen","text":"Erstens Sichtkontrolle auf Beschädigung, Verfärbung, lose Verbindungen oder auffällige Betriebsanzeigen. Zweitens Versorgung und Betriebsbereitschaft anhand der vorgesehenen Anzeigen beziehungsweise durch eine fachgerecht geplante Spannungsprüfung kontrollieren. Vor Öffnen oder Eingriff sind Gefährdungen und sicherer Anlagenzustand zu klären."},{"label":"Spannungsfrei untersuchen","text":"Kurz- und Erdschlussstellen, Isolationsschäden sowie Unterbrechungen mit Widerstands- oder Durchgangsmessung werden nicht bei angelegter Netzspannung gesucht. An Bauteilen können zusätzlich gespeicherte Energie oder Fremdeinspeisungen anliegen. Die Elektrofachkraft trennt und sichert den betroffenen Bereich, stellt Spannungsfreiheit fest und berücksichtigt empfindliche Elektronik."},{"label":"Prüfmittel","text":"Digitalmultimeter beziehungsweise Ohmmeter mit Durchgangsprüfung für niederohmige Verbindungen; Isolationswiderstandsmessgerät für geeignete Isolationsprüfungen; gegebenenfalls geeignetes Leitungsortungs-/Fehlersuchgerät. Prüfspannung und Messverfahren müssen zur Anlage passen. Ein zweipoliger Spannungsprüfer dient der fachgerechten Feststellung der Spannungsfreiheit."}],"mnemonic":"Erst ansehen und Versorgung klären, dann sicher eingrenzen.","pitfall":"Ohm- und Durchgangsbereiche gehören niemals an einen unter Netzspannung stehenden Stromkreis. Sicherungen wiederholt einzusetzen lokalisiert keinen Kurzschluss.","keywords":["Sichtprüfung","Versorgung","Durchgangsprüfung","Isolationsmessung","Spannungsprüfer","Kurzschluss"],"sources":[{"label":"DGUV: Betrieb elektrischer Anlagen und Betriebsmittel","url":"https://publikationen.dguv.de/widgets/pdf/download/article/313"},{"label":"AUVA: Fünf Sicherheitsregeln","url":"https://auva.at/praevention/medien-und-publikationen/publikationen-us/5-sicherheitsregeln-110-x-80-mm/"}],"minutes":4,"pdfPage":45},{"id":"E8","title":"Eine passende Steuerung wählen","category":"Automation","question":"Lege fünf begründete Kriterien für eine Maschinensteuerung fest. Vergleiche eine SPS mit einer konventionellen Schützsteuerung anhand von je zwei Vor- und Nachteilen.","answer":[{"label":"1: Ein- und Ausgänge","text":"Anzahl und Art der Sensoren/Aktoren, analoge Signale und elektrische Schnittstellen bestimmen benötigte Baugruppen und Reserven."},{"label":"2: Zeitverhalten","text":"Reaktionszeit, Zykluszeit und gegebenenfalls Bewegungsregelung entscheiden, ob die Steuerung schnell und deterministisch genug arbeitet."},{"label":"3: Funktionen und Kommunikation","text":"Ablaufkomplexität, Datenspeicherung, Diagnose, Bedienung und bestehende Busse bestimmen Speicher, Rechenleistung und Schnittstellen."},{"label":"4: Umgebung und Sicherheit","text":"Temperatur, Feuchte, Schwingung und EMV müssen zur Bauart passen. Erforderliche Sicherheitsfunktionen benötigen ein dafür geeignetes, validiertes System."},{"label":"5: Betrieb und Wirtschaftlichkeit","text":"Lebenszykluskosten, Ersatzteilversorgung, vorhandenes Personal, Softwarepflege und Erweiterbarkeit bestimmen die langfristige Eignung."},{"label":"SPS: zwei Vorteile","text":"Abläufe können oft per Software geändert und erweitert werden. Diagnose und komplexe Verknüpfungen lassen sich mit weniger Logikverdrahtung realisieren."},{"label":"SPS: zwei Nachteile","text":"Programmierung, Werkzeuge und Datensicherung erfordern Fachwissen und Aufwand. Ein Fehler an zentraler CPU, Versorgung oder Software kann größere Anlagenteile betreffen; bei sehr einfachen Aufgaben kann der Aufwand unverhältnismäßig sein."}],"mnemonic":"I/O, Zeit, Funktion, Umgebung, Betrieb.","pitfall":"Weniger Logikverdrahtung bedeutet nicht, dass eine SPS ohne Leistungs-Schaltgeräte auskommt. Standardausgänge übernehmen keine beliebige Sicherheitsabschaltung.","keywords":["SPS-Auswahl","I/O","Zykluszeit","Schützsteuerung","Lebenszykluskosten","Erweiterbarkeit"],"sources":[{"label":"Hochschule Augsburg: SPS-Grundlagen, Vor- und Nachteile","url":"https://www.hs-augsburg.de/~roos/PAT/SPS/Programmieren_mit_SIMATIC_Manager_STEP_7.pdf"}],"minutes":4,"pdfPage":45},{"id":"E9","title":"Österreichische Normen richtig zuordnen","category":"Sicherheit","question":"Ordne die historischen Verweise E 8001 und E 8701 sowie die Maschinen-Norm 60204-1 fachlich ein. Berücksichtige den Normenstand vom 5. November 2026, drei Auswahlkriterien und vier Bestandteile einer fachgerechten Abnahme.","answer":[{"label":"Niederspannungsanlagen","text":"ÖVE/ÖNORM E 8001 steht für frühere österreichische Errichtungsbestimmungen elektrischer Niederspannungsanlagen. Für aktuelle Planung ist insbesondere OVE E 8101 relevant; der OVE führt die Neufassung 2025-10-01. Bei Altanlagen sind Errichtungszeitpunkt, Änderungen und die einschlägige rechtliche Lage gesondert zu beurteilen."},{"label":"Elektrische Geräte","text":"ÖVE/ÖNORM E 8701 betrifft Prüfungen nach Instandsetzung beziehungsweise Änderung und wiederkehrende Geräteprüfungen. Sie ist teilweise durch OVE EN 50678 für Prüfungen nach Reparatur und OVE EN 50699 für Wiederholungsprüfungen ersetzt. Ein vollständiger pauschaler Wegfall wäre falsch: OVE-Fachinformation G02 nennt beispielsweise Geräte unter 25 V AC beziehungsweise 60 V DC sowie bestimmte Reparaturprüfungen an Audio-/Video-/IT-Geräten. Produktbezogene Sondernormen können vorrangig sein."},{"label":"Maschinen","text":"Richtig lautet die Nummer OVE EN 60204-1: elektrische Ausrüstung von Maschinen, allgemeine Anforderungen. Die Angabe EN 602014-1 ist ein Schreibfehler. Austrian Standards führt aktuell die Ausgabe 2026-08-01. Eine Maschine und die versorgende Gebäudeinstallation haben unterschiedliche, sich ergänzende Regelungsbereiche."},{"label":"Drei Auswahlkriterien","text":"1. Geltungsbereich und Anlagen-/Produktart. 2. Aktuelle Ausgabe, Änderungen und Übergangsregelungen. 3. Österreichischer Rechts-, Vertrags- und Anwendungsbezug; Normenstatus und gesetzliche Verbindlichkeit getrennt prüfen."},{"label":"Vier Abnahmepunkte","text":"1. Vollständige Dokumentation, Pläne, Betriebsanleitung und erforderliche Konformitätsunterlagen. 2. Besichtigung von Aufbau, Kennzeichnung, Auswahl und Schutzmaßnahmen. 3. Erforderliche elektrische Messungen durch qualifiziertes Prüfpersonal mit dokumentierten Ergebnissen. 4. Geschütztes Erproben von Funktion und Sicherheitsfunktionen einschließlich Wiederanlaufverhalten sowie dokumentierte Freigabe."}],"mnemonic":"Anlage: 8101. Gerät: passende Prüf-Norm. Maschine: 60204-1.","pitfall":"Nicht ungeprüft alte Normnummern auswendig anwenden. E 8701 ist nur teilweise ersetzt; technische Nachfolgenorm und gesetzlicher Verweis sind nicht dasselbe.","keywords":["OVE E 8101","ÖVE E 8001","E 8701","EN 50678","EN 50699","EN 60204-1"],"sources":[{"label":"OVE: OVE E 8101, Ausgabe 2025-10-01","url":"https://www.ove.at/ove-standardization/normen-produkte/ove-e-8101/"},{"label":"OVE: E 8701-1, Status teilweise ersetzt","url":"https://shop.ove.at/de/product/-ve-norm-e-8701-1-2003-01-01"},{"label":"OVE: Fachinformation G02 zur Geräteprüfung","url":"https://www.ove.at/fileadmin/userdaten/docs/fachinformationen/OVE-Fachinformation-G02_202410.pdf"},{"label":"Austrian Standards: OVE EN 60204-1:2026-08-01","url":"https://www.austrian-standards.at/de/shop/ove-en-60204-1-2026-08-01~p5078230"}],"minutes":4,"pdfPage":46},{"id":"E10","title":"Steuerung oder Sensor ersetzen","category":"Automation","question":"Eine SPS-Anlage ist gestört. Erläutere Diagnose und Wiederfreigabe und nenne jeweils drei wichtige Prüfgruppen vor einem Steuerungstausch und vor dem Ersatz eines Sensors.","answer":[{"label":"Steuerungstausch: drei Prüfgruppen","text":"1. Vollständige geprüfte Sicherung von Programm, Parametern, Rezepturen und erforderlichen Lizenzen. 2. Kompatibilität von Hardware, Firmware, Baugruppen, Kommunikationsschnittstellen und Anschlussbelegung. 3. Sicherer Stillstand mit gesicherten Energien, geplanter Wiederinbetriebnahme sowie erneuter Funktions- und Sicherheitsprüfung."},{"label":"Störung beheben","text":"Meldung und Zeitpunkt erfassen, Sollablauf und letzte Änderungen klären. Diagnosepuffer, Betriebszustand, Busstatus und Ein-/Ausgangsinformationen auswerten; Signalweg vom Sensor über Logik zum Aktor eingrenzen. Ursache durch Fachpersonal beheben, anschließend den gesamten betroffenen Ablauf und die Schutzfunktionen kontrolliert prüfen und dokumentieren. Ungeplantes Forcen oder Überbrücken von Sicherheitsfunktionen unterlassen."},{"label":"Sensorersatz: drei Prüfgruppen","text":"1. Messprinzip, Zielmaterial, Schaltabstand beziehungsweise Messbereich und Schaltfunktion. 2. Versorgung, Pinbelegung, PNP/NPN, Öffner/Schließer, Analog- oder Bus-Schnittstelle. 3. Bauform, Montageart, Schutzart, Umgebung und gegebenenfalls zugelassene Sicherheitsfunktion. Einbaulage und Teach-/Parameterwerte nach Herstellerangaben herstellen."},{"label":"Sicherheit","text":"Austausch nur durch beauftragtes Personal im gesicherten Zustand; elektrische Arbeiten der Elektrofachkraft überlassen. Auch ein funktionsgleicher Ersatz benötigt eine überprüfte Wiederfreigabe."}],"mnemonic":"Sichern, vergleichen, ersetzen, prüfen, freigeben.","pitfall":"Gleicher Stecker und gleiche Baugröße beweisen keine Austauschbarkeit. Ein Standardsensor ist kein Ersatz für einen Sicherheitssensor.","keywords":["SPS-Diagnose","Backup","Firmware","Sensortausch","PNP/NPN","Wiederfreigabe"],"sources":[{"label":"Siemens: Diagnosekonzept für Automatisierungsanlagen","url":"https://contentpath.siemens.com/standardization/de_diagnosekonzept"},{"label":"Festo Didactic: Induktiver Näherungsschalter, Daten und Montageart","url":"https://www.festo.com/de/de/p/naeherungsschalter-induktiv-m18-id_PROD_DID_548645"},{"label":"Suva: Sichere Instandhaltung elektrischer Einrichtungen","url":"https://www.suva.ch/download/factsheets/sichere-instandhaltung--elektrische-einrichtungen--33079.D/standard-variante--33079.D"}],"minutes":4,"pdfPage":46},{"id":"E11","title":"Lötfreie Verbindungen fachgerecht","category":"Elektrotechnik","question":"Nenne drei lötfreie Verbindungstechniken. Beschreibe die fachgerechte Vorbereitung und Prüfung einer Pressverbindung, die geeigneten Leiterarten und zwei konkrete Kennfarben mit Querschnittsbereich.","answer":[{"label":"Drei Techniken","text":"Schraubklemmen, Federkraft-/Push-in-Klemmen und Crimp-/Pressverbindungen. Weitere Beispiele sind Schneidklemm- und geeignete Steckverbindungen."},{"label":"Arbeitsfolge","text":"Nur im gesicherten, spannungsfreien Arbeitsbereich: Verbinder passend zu Leiterwerkstoff, Querschnitt, Leiterklasse und Anschluss auswählen. Auf Herstellermaß abisolieren, ohne Drähte zu verletzen; Leiter vorbereiten und vollständig einführen. Mit freigegebenem Werkzeug und Einsatz in vorgegebener Anzahl und Richtung verpressen. Sichtprüfung und vorgesehene mechanische Kontrolle durchführen; Anschluss und erforderliche Isolation sachgerecht herstellen. Elektrische Endprüfung durch die Fachkraft."},{"label":"Leitertypen","text":"DIN-Presskabelschuhe nach DIN 46235 sind je nach Ausführung und freigegebener Pressform für ein-, mehr-, fein- und feinstdrähtige Cu-Leiter vorgesehen, also Klassen 1, 2, 5 und 6. Normale Rohrkabelschuhe sind häufig für Klasse 2, isolierte Quetschkabelschuhe häufig für Klassen 5 und 6 freigegeben. Das konkrete Datenblatt entscheidet; Aluminium erfordert ein dafür ausgelegtes System."},{"label":"Kennfarben als Beispiel","text":"Bei der dokumentierten DIN-/HAUPA-Zuordnung für isolierte Quetschkabelschuhe: Rot 0,5–1 mm², Blau 1,5–2,5 mm². Andere Produktserien geben für Rot auch bis 1,5 mm² frei. Maßgeblich sind Aufdruck und Datenblatt, nicht eine allein gemerkte Farbe."}],"mnemonic":"Leiter, Verbinder und Werkzeug bilden ein abgestimmtes System.","pitfall":"Kennfarben von Kabelschuhen und Aderendhülsen sind nicht allgemein austauschbar. Abkneifen einzelner Litzen macht einen unpassenden Verbinder nicht passend.","keywords":["Crimpen","Presskabelschuh","Quetschkabelschuh","Leiterklasse","Kennfarbe","Federkraftklemme"],"sources":[{"label":"Klauke: Auswahl von DIN- und Rohrkabelschuhen","url":"https://www.klauke.com/at/de/din-presskabelschuh-oder-rohrkabelschuh"},{"label":"Klauke: Kabelschuhe richtig verpressen","url":"https://www.klauke.com/ch/de/kabelschuhe-richtig-verpressen"},{"label":"HAUPA: Kennfarben isolierter Quetschkabelschuhe","url":"https://haupa.com/fileadmin/Products/Info/de/info_crimp_isol_kabelschuh.pdf"}],"minutes":4,"pdfPage":47},{"id":"E12","title":"Sensorfehler und Erstinbetriebnahme","category":"Automation","question":"Ein Näherungssensor meldet kein Werkstück. Nenne elektrische und mechanisch-anwendungsbezogene Fehler mit Abhilfe. Erläutere eine sichere Erstinbetriebnahme am Beispiel einer Zuführstation und zwei Zwecke des Protokolls.","answer":[{"label":"Elektrische Beispiele","text":"Fehlende Versorgung durch beschädigte Leitung oder losen Stecker: durch Fachpersonal eingrenzen und Verbindung fachgerecht instand setzen. Falsche Ausgangsart beziehungsweise Pinbelegung, etwa NPN statt erforderlichem PNP: Datenblätter und SPS-Eingang vergleichen und freigegebene Komponenten/Beschaltung herstellen."},{"label":"Anwendungsbezogene Beispiele","text":"Ziel außerhalb des gesicherten Schaltabstands oder Sensor verstellt: fachgerecht ausrichten und Abstand einstellen. Ungeeignetes Zielmaterial oder unzulässiger bündiger/nichtbündiger Einbau: passenden Sensortyp beziehungsweise korrekte Montage wählen. Ein induktiver Sensor erkennt beispielsweise kein beliebiges Kunststoffteil."},{"label":"Beispiel Zuführstation","text":"Vor dem Start Dokumentation, Montage, Anschluss und Schutzkonzept prüfen; elektrische Prüfungen erfolgen durch die Fachkraft. Gefahrenbereich räumen und sichern. Sensorzustände, Drehrichtung und Bewegungsabläufe nach freigegebenem Prüfplan schrittweise bei begrenzter Geschwindigkeit/Energie erproben, soweit technisch vorgesehen. Not-Halt, Verriegelungen und Wiederanlaufschutz validieren; danach definierten Probebetrieb und Übergabe durchführen."},{"label":"Protokoll: zwei Zwecke","text":"Es belegt Zustand, Prüfumfang, Ergebnisse und Freigabeverantwortung. Außerdem hält es Parameter, Abweichungen und offene Punkte als Vergleichsbasis für spätere Wartung und Fehlersuche fest."}],"mnemonic":"Versorgung und Signal prüfen, Ziel und Abstand prüfen.","pitfall":"Die Sensor-LED und der SPS-Eingang sind zwei unterschiedliche Diagnosepunkte. Eine Erstinbetriebnahme ist mit einem erfolgreichen Probehub allein nicht abgeschlossen.","keywords":["Näherungssensor","Schaltabstand","PNP/NPN","Erstinbetriebnahme","Prüfprotokoll","Zuführstation"],"sources":[{"label":"Festo Didactic: Induktiver Näherungsschalter, Daten und Montageart","url":"https://www.festo.com/de/de/p/naeherungsschalter-induktiv-m18-id_PROD_DID_548645"},{"label":"AUVA: Fünf Sicherheitsregeln","url":"https://auva.at/praevention/medien-und-publikationen/publikationen-us/5-sicherheitsregeln-110-x-80-mm/"}],"minutes":4,"pdfPage":47},{"id":"E13","title":"Motor wird im Dauerbetrieb zu warm","category":"Elektrotechnik","question":"Ein Asynchronmotor mit Käfigläufer überhitzt. Erkläre für drei unterschiedliche Ursachen jeweils Wirkung und fachgerechte Abhilfe.","answer":[{"label":"1: Mechanische Überlast","text":"Zu große Last oder eine schwergängige Maschine erhöhen den benötigten Strom und damit die Kupferverluste. Wicklung und gegebenenfalls Lager werden zu heiß; die Isolierung altert schneller. Gesichert stillsetzen, Lastursache durch Fachpersonal klären, Mechanik instand setzen beziehungsweise Antrieb richtig auslegen. Motorschutz passend einstellen, nicht umgehen."},{"label":"2: Phasenausfall oder Unsymmetrie","text":"Eine unterbrochene Zuleitung, ein beschädigter Kontakt oder ungleiche Spannungen können stark unsymmetrische Ströme und Erwärmung verursachen; zugleich sinkt das nutzbare Drehmoment. Elektrofachkraft prüft Versorgung, Anschlüsse und Schaltgeräte nach sicherem Prüfplan, beseitigt die Ursache und kontrolliert den Phasenausfallschutz."},{"label":"3: Ungenügende Kühlung","text":"Verstopfte Lüftungswege, verschmutzte Rippen, ein defekter Lüfter oder zu hohe Umgebungstemperatur verhindern die Wärmeabgabe. Reinigung und Reparatur im gesicherten Zustand, freie Zu-/Abluft und passende Umgebung herstellen. Bei niedriger Umrichterdrehzahl kann eine geeignete Fremdkühlung erforderlich sein."},{"label":"Wiederfreigabe","text":"Nach Abkühlung und Ursachenbehebung Zustand von Motor und Schutzsystem fachgerecht prüfen, Betriebswerte kontrolliert vergleichen und Befund dokumentieren. Nicht mehrfach weiterlaufen lassen, bis die Schutzeinrichtung auslöst."}],"mnemonic":"Zu viel Last, ungleiche Phasen oder zu wenig Luft.","pitfall":"Ein heißes Gehäuse allein lokalisiert die Ursache nicht. Ein höherer Motorschutz-Einstellwert ist keine Reparatur.","keywords":["Kurzschlussläufer","Überhitzung","Überlast","Phasenausfall","Kühlung","Isolationsalterung"],"sources":[{"label":"ABB: Handbuch für Induktionsmotoren, Störungsdiagnose","url":"https://library.e.abb.com/public/6df512c64b0b4a659933aee242b2e7d5/Manual%20for%20Induction%20Motors%20and%20Generators_EN.pdf"},{"label":"WEG: Sicherheit, Anschluss, Schutz und Wartung von Motoren","url":"https://static.weg.net/medias/downloadcenter/h8e/h88/WEG-WMO-safe-area-50031071-manual-en-es.pdf"}],"minutes":4,"pdfPage":48},{"id":"E14","title":"Anlagenpflege und klarer SPS-Code","category":"Automation","question":"Stelle vier sinnvolle Instandhaltungsarbeiten zusammen. Begründe drei Vorteile eingehaltenen Wartungsintervallen und zwei Vorteile einer verständlichen SPS-Programmstruktur.","answer":[{"label":"Vier Arbeiten","text":"1. Vorgesehene Filter und Kühlwege reinigen oder wechseln. 2. Schmierstellen nach Herstellerplan versorgen. 3. Sensorbefestigungen, Leitungen, Stecker und pneumatische Leitungen auf Zustand beziehungsweise Leckage kontrollieren. 4. Schutz- und Sicherheitsfunktionen durch befugtes Personal nach Prüfplan kontrollieren. Jede Arbeit erfordert einen passend gesicherten Anlagenzustand."},{"label":"Drei Gründe für Intervalle","text":"Sicherheit: Verschleiß und Schutzmängel rechtzeitig entdecken. Verfügbarkeit: ungeplante Stillstände verringern und notwendige Arbeiten planen. Qualität und Lebensdauer: reproduzierbare Funktion erhalten und teure Folgeschäden begrenzen. Intervalle folgen Herstellerangaben, Einsatzbedingungen und Erfahrung; vorgeschriebene Prüfungen sind zusätzlich zu beachten."},{"label":"Zwei Programmvorteile","text":"Klar abgegrenzte Bausteine, aussagekräftige Namen und dokumentierte Schnittstellen erleichtern Diagnose und Einarbeitung. Gekapselte, geprüfte Funktionen lassen sich wiederverwenden und gezielter ändern, wodurch Änderungsaufwand und Fehlerwahrscheinlichkeit sinken."}],"mnemonic":"Pflegen hält verfügbar, Struktur hält verständlich.","pitfall":"Wartung ist mehr als Reinigen. Eine vorhandene Prüfliste beweist erst mit sachgerechter Durchführung und Dokumentation den erledigten Umfang.","keywords":["Instandhaltung","Wartungsintervall","Filter","Schmierung","SPS-Struktur","Wiederverwendung"],"sources":[{"label":"DGUV: Instandhaltung sicher und praxisgerecht durchführen","url":"https://publikationen.dguv.de/widgets/pdf/download/article/338"},{"label":"Siemens: Programmierleitfaden S7-1200/1500","url":"https://support.industry.siemens.com/dl/files/040/90885040/att_978091/v1/81318674_Programming_guideline_DOC_v161_de.pdf"},{"label":"WEG: Sicherheit, Anschluss, Schutz und Wartung von Motoren","url":"https://static.weg.net/medias/downloadcenter/h8e/h88/WEG-WMO-safe-area-50031071-manual-en-es.pdf"}],"minutes":4,"pdfPage":48},{"id":"E15","title":"Widerstände auslegen und einstellen","category":"Elektrotechnik","question":"Welche Daten brauchst du zur Auswahl eines Widerstands? Zeige einen Wert außerhalb einer gewählten E-Reihe durch Zusammenschaltung, berechne die Belastung und erkläre Aufbau sowie Funktion eines Potentiometers.","answer":[{"label":"Auswahlwerte","text":"Nennwiderstand und Toleranz, zulässige Dauer- und Impulsleistung, maximale Betriebsspannung, Temperaturkoeffizient, Umgebung und Bauform. Nennwerte werden häufig aus E-Reihen gewählt, zum Beispiel E12, E24 oder E96. Leistungsangaben gelten unter definierten Temperaturbedingungen."},{"label":"Zwischenwert bilden","text":"In Reihe addieren sich Widerstände: Rges = R1 + R2. Beispiel aus E12-Werten: 1 kΩ + 220 Ω = 1,22 kΩ. Parallel gilt 1/Rges = 1/R1 + 1/R2; bei zwei Widerständen Rges = R1 × R2 / (R1 + R2). Alternativ passende feinere Normreihe oder einen geeigneten Abgleich verwenden. Toleranzen mitberücksichtigen."},{"label":"Leistung","text":"Im jeweiligen Widerstand P = U × I = I² × R = U²/R berechnen. Beispiel: 10 V an 1 kΩ ergeben 0,1 W. Einen Typ mit ausreichender Reserve unter Beachtung von Datenblatt und Temperatur-Derating wählen. Spannungs- und Impulsgrenzen gelten zusätzlich, auch wenn die mittlere Leistung klein bleibt."},{"label":"Potentiometer","text":"Widerstandsbahn mit zwei Endanschlüssen und beweglichem Schleifer mit drittem Anschluss. Als Spannungsteiler liefert er eine einstellbare Teilspannung; als veränderlicher Widerstand werden Schleifer und ein Ende genutzt, sofern der Typ dafür geeignet ist. Lineare oder logarithmische Kennlinie nach Anwendung wählen; Schleiferstrom und Teilbahnleistung begrenzen."}],"mnemonic":"Ohm legt die Funktion fest, Watt und Volt die Belastungsgrenzen.","pitfall":"Ein Potentiometer verträgt nicht auf jedem kleinen Teilstück seine gesamte Nennleistung. Für Präzisionsweggeber gelten besondere Vorgaben zur Schleiferbelastung.","keywords":["E-Reihe","Nennwiderstand","Toleranz","Verlustleistung","Derating","Potentiometer"],"sources":[{"label":"Vishay: Widerstandsfarbcode und E-Reihen","url":"https://www.vishay.com/docs/20143/colorcod.pdf"},{"label":"Vishay: Widerstandskenngrößen und Leistungsreduzierung","url":"https://www.vishay.com/docs/49873/49873_sg2113.pdf"},{"label":"MEGATRON: Potentiometrische Positionssensoren","url":"https://www.megatron.de/kategorie/potentiometrische-positionssensoren"}],"minutes":4,"pdfPage":49},{"id":"E16","title":"Vom Feldgerät zur Leitwarte","category":"Automation","question":"Erkläre den Informationsweg einer vernetzten Fabrik vom Feldgerät über Zelle und Kommunikationsnetz bis zur Leitwarte und zum externen Netz. Welche Kopplungsaufgabe kann ein LINK erfüllen? Ergänze ein nachvollziehbares Kommunikationsbeispiel aus einem Betrieb.","answer":[{"label":"Einordnung des Übersichtsbildes","text":"Die zugeordnete Bildseite zeigt Feldgeräte und Sensoren, lokale Steuerungen auf Zellebene, ein gemeinsames Ethernet-Kommunikationsnetz, SCADA auf Fabriksebene sowie eine über Gateway und Firewall abgegrenzte externe Ebene. Unterschiedliche Feldbusse beziehungsweise Ethernet-Systeme kommen nebeneinander vor; ein 4–20-mA-Signal ist dagegen eine analoge Punkt-zu-Punkt-Verbindung."},{"label":"Kommunikation und Verfügbarkeit","text":"Controller sammeln Prozessdaten und geben Stellbefehle aus. Leit- und Bedienebenen visualisieren, archivieren und überwachen, beispielsweise mit OPC UA. Der dargestellte MRP-Ring kann nach einer einzelnen Leitungsunterbrechung einen alternativen Datenweg herstellen; er ersetzt keine Sicherheitsfunktion."},{"label":"LINK","text":"Allgemein koppelt ein Link Teilnetze beziehungsweise Kommunikationssysteme und vermittelt den Datenaustausch. Sind unterschiedliche Protokolle beteiligt, übernimmt ein entsprechend ausgelegtes Gateway die Umsetzung. Medien- oder Geschwindigkeitsschnittstellen hängen vom konkreten Gerät ab. Das Bild benennt kein einzelnes LINK-Modell; daraus lässt sich etwa ein bestimmter DP/PA-Link nicht sicher ableiten."},{"label":"Praktisches Beispiel","text":"Eine Förderzellen-SPS erhält Sensorwerte über eine dezentrale PROFINET-I/O-Station, steuert einen Antrieb und stellt Zählerstände für SCADA per OPC UA bereit. Übertrage dieses Beispiel auf die tatsächlich im eigenen Betrieb eingesetzten Systeme: Teilnehmer, Daten und Kommunikationswege konkret nennen."}],"mnemonic":"Feld erfasst, Zelle steuert, Leitwarte überwacht, Kopplung vermittelt.","pitfall":"Ein Kabel oder ein Switch übersetzt nicht automatisch Anwendungsprotokolle. Redundanz verbessert Verfügbarkeit und ist keine beliebige Freigabe für Internetzugriff.","keywords":["Feldebene","Zellebene","SCADA","LINK","MRP","OPC UA","Gateway"],"sources":[{"label":"Siemens: Medienredundanz bei Ringtopologien","url":"https://docs.tia.siemens.cloud/r/simatic_s7_1200_manual_collection_dede_20/kommunikation/profinet/medienredundanzprotokoll-mrp/medienredundanz-bei-ringtopologien"},{"label":"Phoenix Contact: Geräte-Server und Gateways","url":"https://www.phoenixcontact.com/de-de/produkte/industrielle-kommunikation/geraeteserver-und-gateways?p=5"},{"label":"OPC Foundation: OPC UA","url":"https://opcfoundation.org/about/opc-technologies/opc-ua/"}],"minutes":4,"pdfPage":49,"imagePage":66,"imagePages":[66]},{"id":"E17","title":"Leiterplatten bestücken und MOS schützen","category":"Elektrotechnik","question":"Formuliere drei Regeln für die Bestückung einer Platine und drei für den Austausch eines MOS-Bauteils. Woran erkennst du eine sachgerechte Lötverbindung, und welche Grenze hat eine reine Sichtprüfung?","answer":[{"label":"Bestückung: drei Regeln","text":"1. Richtige Bauteile und Werte mit Stückliste beziehungsweise Bestückungsplan vergleichen. 2. Lage und Polarität beachten, besonders bei ICs, Dioden und Elektrolytkondensatoren. 3. Saubere, unbeschädigte Anschlüsse, passende Abstände und einen für Bauteil und Leiterplatte geeigneten Lötprozess sicherstellen."},{"label":"MOS-Austausch: drei Regeln","text":"1. Gerät sicher spannungsfrei machen und gespeicherte Energie fachgerecht abbauen; Arbeiten an Netzgeräten der Fachkraft überlassen. 2. ESD-geschützten Arbeitsplatz, geeignete ableitfähige Unterlage, Personenableitung und ESD-gerechtes Werkzeug verwenden; Bauteile bis zur Verarbeitung geschützt verpackt lassen. 3. Typ, Pinbelegung und Einbaurichtung prüfen und mit begrenzter, datenblattgerechter Wärmeeinwirkung aus-/einlöten, ohne Pads und Leiterbahnen abzulösen."},{"label":"Lötstelle beurteilen","text":"Lot benetzt Anschluss und Lötfläche erkennbar, bildet eine passende gleichmäßige Kontur und eine mechanisch ruhige Verbindung. Keine Brücken, Risse, abgehobenen Pads oder unbenetzten Anschlussbereiche. Bleifreies Lot kann auch bei guter Verbindung matt wirken. Sichtprüfung unter Vergrößerung ergänzen durch die für die Baugruppe vorgesehenen elektrischen und funktionalen Prüfungen."}],"mnemonic":"Wert und Richtung prüfen, ESD vermeiden, Benetzung beurteilen.","pitfall":"Glänzend ist kein universeller Qualitätsnachweis. Unsichtbare ESD-Schäden können ein Bauteil erst später ausfallen lassen.","keywords":["Bestückung","MOS","ESD","Pinbelegung","Lötstelle","Benetzung"],"sources":[{"label":"Toshiba: ESD-Schutz von MOS-Bauteilen","url":"https://toshiba.semicon-storage.com/ap-en/semiconductor/knowledge/faq/mosfet/mos-is-sensitive-to-static-electricityhow-do-you-protect-mosfets.html"},{"label":"Kester: Eigenschaften bleifreier Lötstellen","url":"https://www.kester.com/knowledge-base/faq"}],"minutes":4,"pdfPage":50},{"id":"E18","title":"Umbauten und Instandhaltung planen","category":"Automation","question":"Vor einer Erweiterung einer Automatisierungsanlage: Welche vier Planungspakete sind nötig? Erkläre außerdem die vier Grundmaßnahmen der Instandhaltung anhand einfacher Beispiele.","answer":[{"label":"1: Ziel und Bestand","text":"Anforderungen, gewünschte Leistung und vorhandenen Anlagenzustand erfassen. Pläne, Programmstand, Reserven an I/O, Leistung, Platz und Kommunikation sowie Schnittstellen zu anderen Anlagenteilen prüfen."},{"label":"2: Sicherheit und Regelwerk","text":"Gefährdungen und Auswirkungen der Änderung beurteilen, Schutzkonzept und erforderliche Sicherheitsfunktionen festlegen. Zuständigkeiten, anwendbare Regeln, notwendige Prüfungen und mögliche Konsequenzen für Konformität und Dokumentation vorab klären."},{"label":"3: Technische Umsetzung","text":"Kompatible Komponenten, Versorgung und Leitungsdimensionierung, mechanische/pneumatische Anpassungen und Softwareänderungen planen. Datensicherung, Ersatzteile und Rückkehrmöglichkeit zu einem freigegebenen Stand vorsehen."},{"label":"4: Abwicklung und Freigabe","text":"Kosten, Personal, Lieferzeit und Stillstandsfenster abstimmen. Sichere Montage, Prüf- und Inbetriebnahmeplan, Abnahmekriterien, aktualisierte Unterlagen und Bedienerschulung festlegen. Durchführung und elektrische Prüfung durch entsprechend beauftragte Fachkräfte."},{"label":"Vier Instandhaltungsmaßnahmen","text":"Wartung verzögert Verschleiß, etwa Schmieren. Inspektion ermittelt und beurteilt den Istzustand, etwa Lagerzustand prüfen. Instandsetzung stellt eine ausgefallene Funktion wieder her, etwa ein defektes Lager ersetzen. Verbesserung erhöht Zuverlässigkeit beziehungsweise Instandhaltbarkeit ohne Änderung der geforderten Funktion, etwa eine bekannte Verschleißursache konstruktiv beseitigen."}],"mnemonic":"Ziel, Sicherheit, Technik und Ablauf; warten, prüfen, reparieren, verbessern.","pitfall":"Ein Umbau endet nicht mit der Montage. Programm, Schaltplan, Schutzprüfung und Freigabe müssen den geänderten Zustand abbilden.","keywords":["Umbau","Erweiterung","Wartung","Inspektion","Instandsetzung","Verbesserung"],"sources":[{"label":"DGUV: Instandhaltung sicher und praxisgerecht durchführen","url":"https://publikationen.dguv.de/widgets/pdf/download/article/338"},{"label":"Austrian Standards: OVE EN 60204-1:2026-08-01","url":"https://www.austrian-standards.at/de/shop/ove-en-60204-1-2026-08-01~p5078230"}],"minutes":4,"pdfPage":50},{"id":"E19","title":"Drehstrommotor: Fehler eingrenzen","category":"Elektrotechnik","question":"Ein Drehstromantrieb läuft nicht richtig. Wie unterscheiden Sie drei typische Fehlerbilder, welche Befunde helfen bei der Diagnose und welche fachgerechte Abhilfe passt jeweils?","answer":[{"label":"Diagnose sicher vorbereiten","text":"Störung, Betriebszustand und letzte Änderung erfassen; Typenschild, Schaltplan, Motorschutz und gegebenenfalls Umrichterdiagnose zuordnen. Elektrische Messungen und Reparaturen gehören in die Hände einer Elektrofachkraft. Vor Eingriffen freischalten, gegen Wiedereinschalten sichern und den sicheren Zustand einschließlich nachlaufender Lasten herstellen."},{"label":"Phasenausfall oder Versorgungsfehler","text":"Der Motor brummt, startet schlecht oder löst den Schutz aus. Mögliche Ursachen sind eine defekte Sicherung, ein beschädigter Leiter oder ein fehlerhafter Schützkontakt. Die Fachkraft prüft Versorgung und Stromsymmetrie, anschließend spannungsfrei die betroffenen Verbindungen. Die Ursache beseitigen und ein geeignetes defektes Bauteil ersetzen; den Schutz nicht überbrücken."},{"label":"Überlastung oder mangelhafte Kühlung","text":"Hoher Strom und steigende Temperatur sprechen etwa für zu große Last, eine blockierte Mechanik, verschmutzte Lüftung oder falsche Betriebsbedingungen. Last und freien Lauf sowie Lüfter und Kühlwege überprüfen lassen. Mechanische Ursache beheben, Kühlung instand setzen und Belastung beziehungsweise Antriebsauslegung korrigieren."},{"label":"Lager- oder Ausrichtfehler","text":"Raues Geräusch, Vibrationen und örtliche Erwärmung weisen auf beschädigte Lager, falsche Schmierung, Unwucht oder Kupplungsversatz hin. Geräusch- und Schwingungsbefunde mit Montagezustand und Wartungsdaten vergleichen. Fachgerecht ausrichten, die freigegebene Schmierung herstellen oder beschädigte Lager ersetzen; danach kontrollierter Funktionslauf und Dokumentation."}],"mnemonic":"Erst das Fehlerbild trennen: Versorgung, Wärme, Mechanik.","pitfall":"Eine größere Sicherung oder ein höher eingestellter Motorschutz beseitigt die Fehlerursache nicht.","keywords":["Phasenausfall","Motorschutz","Überlast","Lager","Diagnose"],"sources":[{"label":"Siemens: SIMOTICS – Störungen und Abhilfen","url":"https://cache.industry.siemens.com/dl/files/011/109475011/att_879160/v1/OperatingInstructions_en_1LH1_en-US.pdf"}],"minutes":4,"pdfPage":51},{"id":"E20","title":"Anlage passend auslegen und SPS-Logik ausdrücken","category":"Automation","question":"Welche Leistungs- und Qualitätsdaten bestimmen die Größe einer Produktionsanlage, warum ist unnötige Präzision teuer und wie lässt sich dieselbe UND-Verknüpfung in zwei SPS-Darstellungen erklären?","answer":[{"label":"Dimensionierung","text":"Aus Stückzahl und verfügbarer Produktionszeit den erforderlichen Takt bestimmen. Werkstückmasse, Kräfte, Drehmoment, Geschwindigkeit und Lastwechsel legen die Antriebe fest. Verfügbarkeit, Rüstzeiten, Ausschuss, Energieversorgung, Platz und sinnvoll begründete Reserven mitrechnen. Der langsamste Prozessschritt begrenzt die Gesamtleistung."},{"label":"Genauigkeit bedarfsgerecht wählen","text":"Maßgeblich sind Funktion und geforderte Toleranz. Engere Toleranzen als notwendig erhöhen meist Investition, Bearbeitungszeit und Messaufwand. Sie können außerdem empfindlichere Einstellungen sowie höheren Wartungsaufwand verlangen. Zu große Ungenauigkeit verursacht dagegen Ausschuss oder Montageprobleme."},{"label":"Sprachen heute und im Altbestand","text":"IEC 61131-3:2025 nennt Strukturierter Text (ST), Kontaktplan (LD/KOP) und Funktionsbausteinsprache (FBD/FUP). SFC beschreibt eine Ablaufstruktur; Siemens GRAPH ist eine entsprechende Herstellerumsetzung. SCL ist die Siemens-Bezeichnung für ST. AWL/IL findet man in älteren Projekten und bestimmten Werkzeugen; sie gehört nicht zur gleichberechtigten aktuellen Sprachliste dieser Normausgabe."},{"label":"Gleiche UND-Funktion in zwei Formen","text":"In ST lautet eine einfache Zuweisung beispielsweise: Freigabe := SensorA AND SensorB; In KOP stehen zwei zu SensorA und SensorB gehörende Schließerkontakte in Reihe vor der Spule Freigabe. Beide Eingänge müssen TRUE sein. Eine ODER-Verknüpfung verwendet OR beziehungsweise parallele Kontaktzweige. Diese Lernlogik ersetzt keine sicherheitsgerichtete Freigabe."}],"mnemonic":"Takt und Last bestimmen die Größe, die Toleranz bestimmt die Präzision.","pitfall":"AWL aus einem älteren Lehrbuch ungeprüft als aktuelle gleichrangige Normsprache anführen.","keywords":["Dimensionierung","Taktzeit","Toleranz","ST","KOP","FUP"],"sources":[{"label":"Siemens: Antriebe mit Lastprofil dimensionieren","url":"https://support.industry.siemens.com/cs/attachments/109773995/micro-drive_in_tst_getting_started_en-US_en-US.pdf"},{"label":"IEC: IEC 61131-3:2025 – aktueller Sprachumfang","url":"https://webstore.iec.ch/en/publication/68533"}],"minutes":4,"pdfPage":51},{"id":"E21","title":"Robotereinsatz und klare Programmstruktur","category":"Automation","question":"Bewerten Sie einen Robotereinsatz mit je drei Chancen und Grenzen. Wie wird ein Automatisierungsprogramm verständlich gegliedert, und wie hilft ein wiederverwendbarer Baustein dabei?","answer":[{"label":"Drei Vorteile","text":"Roboter können wiederholte Bewegungen mit hoher Wiederholgenauigkeit ausführen, gleichmäßige Abläufe und planbare Taktzeiten unterstützen und Menschen von schweren, monotonen oder gefährlichen Tätigkeiten entlasten. Durch Umprogrammierung und Werkzeugwechsel sind sie für unterschiedliche Aufgaben einsetzbar."},{"label":"Drei Nachteile oder Aufwände","text":"Anschaffung und Integration kosten Geld; Greifer, Vorrichtungen und Schutzkonzept gehören dazu. Programmierung, Einrichten und Instandhaltung benötigen qualifiziertes Personal. Bei wechselnden oder unzureichend beherrschten Prozessbedingungen entstehen zusätzlicher Sensorik- und Anpassungsaufwand sowie Stillstandsrisiken."},{"label":"Drei Strukturierungsmöglichkeiten","text":"Erstens nach Anlagenfunktionen in überschaubare Module gliedern, etwa Zuführen, Spannen und Bearbeiten. Zweitens wiederkehrende Funktionen in parametrierbare Bausteine mit klaren Schnittstellen auslagern. Drittens Ablaufzustände mit einer nachvollziehbaren Schrittkette oder Zustandsmaschine organisieren. Einheitliche Namen und aussagekräftige Kommentare unterstützen alle drei."},{"label":"Bausteinbeispiel","text":"Ein Baustein für einen Förderantrieb erhält Start, Stop und Rückmeldungen als Eingänge und liefert Ansteuerung, Betriebszustand und Störung zurück. Jede Antriebsinstanz erhält ihren eigenen Zustandsspeicher. So kann derselbe geprüfte Ablauf mehrfach genutzt werden, während eine Änderung an einer klar abgegrenzten Stelle erfolgt."}],"mnemonic":"Eine Funktion, eine klare Schnittstelle, ein eigener Zustand.","pitfall":"Wiederholgenauigkeit mit absoluter Positioniergenauigkeit oder Robotereinsatz mit automatisch sicherem Betrieb gleichsetzen.","keywords":["Roboter","Wiederholgenauigkeit","Modularisierung","Schnittstelle","Wiederverwendung"],"sources":[{"label":"ABB: Robotik und Automatisierungsanwendungen","url":"https://www.abb.com/global/en/areas/robotics"},{"label":"PLCopen: Software Construction Guidelines","url":"https://www.plcopen.org/guidelines/software-construction-guidelines/"}],"minutes":4,"pdfPage":52},{"id":"E22","title":"Sicher in der Roboterzelle arbeiten","category":"Sicherheit","question":"Welche vier Verhaltensgrundsätze schützen bei Robotertätigkeiten, und welche Informationen muss die Anlagendokumentation für Betrieb, Störung und Wartung bereitstellen?","answer":[{"label":"Berechtigung und Betriebsart","text":"Nur unterwiesene und für die Aufgabe beauftragte Personen arbeiten am Robotersystem. Betriebsanleitung, Betriebsarten und besondere Gefahren des Werkzeugs beachten. Einrichtbetrieb darf nur mit den dafür vorgesehenen Schutzmaßnahmen erfolgen, beispielsweise sicher reduzierter Geschwindigkeit und Zustimmungseinrichtung."},{"label":"Schutzbereich und Wiederanlauf","text":"Schutzzäune, verriegelte Türen und berührungslos wirkende Schutzeinrichtungen nicht umgehen. Im Automatikbetrieb muss der Gefahrenbereich frei sein. Ein quittierter Schutzstopp darf keinen unerwarteten Anlauf auslösen; die freigegebene Wiederanlaufprozedur einhalten."},{"label":"Energien und Lasten","text":"Vor Wartung oder Störungsbeseitigung alle gefährlichen Energien nach dem Anlagenverfahren sichern. Werkzeug, Werkstück und schwerkraftbelastete Achsen können auch bei abgeschalteten Antrieben gefährlich sein. Haltebremsen ersetzen keine erforderliche mechanische Lastsicherung."},{"label":"Bewegungsraum und Reaktion","text":"Arbeitsraum einschließlich Greifer, Werkstück, Peripherie und möglicher Teilebewegungen berücksichtigen. Sichere Standposition und Fluchtmöglichkeit wählen; Not-Halt-Stellen kennen. Störungen melden und die Anlage bis zur fachgerechten Freigabe gesichert lassen."},{"label":"Anlagendokumentation","text":"Dazu gehören bestimmungsgemäße Verwendung und Grenzen, Restrisiken, Schutzfunktionen, Bedienung und Betriebsarten, Transport und Aufstellung, Inbetriebnahme, Störungsbehebung und Wartungsplan. Schalt- und Pneumatik-/Hydraulikpläne, Schnittstellen, Teilelisten, Softwarestände, Prüfunterlagen sowie Zuständigkeiten müssen dem tatsächlichen Anlagenstand entsprechen."}],"mnemonic":"Betriebsart, Schutzbereich, Energie und Bewegungsraum gemeinsam betrachten.","pitfall":"Einen stillstehenden Roboter für ungefährlich halten oder eine Schutztür zur Fehlersuche überbrücken.","keywords":["Roboterzelle","Einrichtbetrieb","Schutzeinrichtung","Restenergie","Dokumentation"],"sources":[{"label":"AUVA: Checkliste Industrieroboter","url":"https://auva.at/media/o4fo4ldo/checkliste_industrieroboter-bf_2511_oh.pdf"},{"label":"Arbeitsinspektion: Auswahl und Benutzung von Arbeitsmitteln","url":"https://www.arbeitsinspektion.gv.at/arbeitsschutz/arbeitsmittel/gemeinsame_bestimmungen/definition_allgemeine_vorschriften.html"}],"minutes":4,"pdfPage":52},{"id":"E23","title":"Automatisierungsebenen richtig zuordnen","category":"Automation","question":"Ordnen Sie Sensorik, SPS, HMI/SCADA, Fertigungsmanagement und Unternehmensplanung ihren Aufgaben zu. Was zeigt ein Netzwerkbild mit SPS, HMI, SCADA, Gateway, Firewall und Cloud tatsächlich?","answer":[{"label":"Prozess und Feld","text":"Im ISA-95-Modell ist Ebene 0 der physische Prozess. Ebene 1 erfasst ihn mit Sensoren und beeinflusst ihn mit Aktoren, zum Beispiel durch Messen einer Position und Bewegen eines Zylinders."},{"label":"Steuerung und Bedienung","text":"Ebene 2 steuert und überwacht den Prozess. SPS/DCS verarbeiten Signale und koordinieren Maschinenfunktionen. HMI und SCADA stellen Zustände, Trends und Alarme dar und erlauben die dafür freigegebene Bedienung."},{"label":"Fertigungs- und Unternehmensebene","text":"Ebene 3 unterstützt das Fertigungsmanagement, beispielsweise mit MES für Auftragsausführung, Rückverfolgung und Produktionsdaten. Ebene 4 plant unternehmensweit mit ERP etwa Material, Termine und betriebswirtschaftliche Ressourcen. In Lehrbüchern können Ebenennamen und Zählweise abweichen; die Aufgaben erklären die Zuordnung."},{"label":"Bildbezug und Netzwerkkomponenten","text":"Die Originalübersicht zeigt Geräte im Feld, mehrere Steuerungen sowie HMI und SCADA an einer Netzwerkinfrastruktur. Ein Gateway verbindet Kommunikationsbereiche; die Firewall kontrolliert Verbindungen zum externen Netz. Cloud ist ein möglicher Dienstort und keine zusätzliche festgelegte ISA-95-Ebene. Ein gezeichneter Ring allein belegt noch keine funktionierende Redundanz."}],"mnemonic":"Unten wirkt die Anlage, darüber wird gesteuert, geführt und geplant.","pitfall":"Ein Switch mit einem Gateway verwechseln oder Cloud pauschal als oberste Automatisierungsebene bezeichnen.","keywords":["ISA-95","Feldebene","SPS","SCADA","MES","ERP"],"sources":[{"label":"Siemens: ISA-95-Ebenen","url":"https://www.siemens.com/fi-fi/technology/isa-95-framework-layers/"},{"label":"Phoenix Contact: Industrielle Kommunikation und Übertragungsmedien","url":"https://www.phoenixcontact.com/en-au/products/industrial-communication"}],"minutes":4,"pdfPage":53,"imagePage":67,"imagePages":[67]},{"id":"E24","title":"Industrielle Übertragungsmedien auswählen","category":"Automation","question":"Vergleichen Sie drei Medien für industrielle Datenübertragung, nennen Sie mindestens drei Auswahlkriterien und erläutern Sie den typischen Aufbau einer Kupfer- beziehungsweise Glasfaserverbindung.","answer":[{"label":"Drei Medien","text":"Kupferleitungen übertragen elektrische Signale und sind verbreitet sowie einfach anzuschließen. Lichtwellenleiter übertragen Licht, bieten galvanische Trennung und sind gegen elektromagnetische Einstreuung unempfindlich. Funk überträgt elektromagnetische Wellen ohne Datenleitung; Verfügbarkeit und Reichweite hängen unter anderem von Umgebung und Funkplanung ab."},{"label":"Industrieanforderungen","text":"Wichtig sind passende Datenrate und zulässige Leitungslänge, ausreichende Störfestigkeit und geringe Fehlerrate sowie Eignung für Temperatur, Feuchte, Öl, UV und mechanische Beanspruchung. Bei bewegten Leitungen zählen Biegeradius und Schleppketteneignung. Steckverbinder, Schutzart und Übertragungszeit müssen zum Einsatz passen."},{"label":"Kupferstrecke","text":"Eine typische geschirmte Datenleitung besteht aus isolierten Leitern, verdrillten Aderpaaren, gegebenenfalls Paar- und Gesamtschirm und einem geeigneten Außenmantel. Dazu gehören passende Stecker oder Anschlussmodule, Zugentlastung und die systemgerechte Schirmanbindung."},{"label":"Lichtwellenleiter und Funkstrecke","text":"Ein Lichtwellenleiter besitzt Kern und optischen Mantel, Schutzschichten sowie je nach Leitung Zugentlastung und Außenmantel; Stecker und optische Sender/Empfänger vervollständigen die Strecke. Eine Funkstrecke benötigt Funkgeräte, Antennen und den Ausbreitungsraum. Der Aufbau einer Kupferleitung lässt sich daher nicht auf jedes Medium übertragen."}],"mnemonic":"Medium, Umgebung und Übertragungsanforderung müssen zusammenpassen.","pitfall":"Nur die Datenrate vergleichen und Bewegungsbeanspruchung, Reichweite oder elektromagnetische Umgebung vergessen.","keywords":["Kupfer","Lichtwellenleiter","Funk","EMV","Schirm","Biegeradius"],"sources":[{"label":"Phoenix Contact: Industrielle Kommunikation und Übertragungsmedien","url":"https://www.phoenixcontact.com/en-au/products/industrial-communication"},{"label":"PI: PROFIBUS-Installationsrichtlinien","url":"https://www.profibus.com/download/profibus-installation-guidelines"}],"minutes":4,"pdfPage":53},{"id":"E25","title":"Stahl trennen und Schnittkanten nacharbeiten","category":"Mechanik","question":"Welches Handgerät eignet sich zum mobilen Trennen von Stahl? Beschreiben Sie für unterwiesene Fachkräfte den sicheren Grundablauf eines Scheibenwechsels und einer Serie gleich langer Sägeschnitte sowie den Zweck des Entgratens.","answer":[{"label":"Geeignetes Gerät","text":"Ein Winkelschleifer mit für Stahl und Gerät zugelassener Trennscheibe kann Reparaturschnitte ausführen. Werkstücksicherung, passende Trennschutzhaube, Zusatzhandgriff sowie Augen-/Gesichtsschutz, Gehörschutz und weitere arbeitsplatzabhängige Schutzmaßnahmen sind erforderlich. Funkenflug und brennbare Stoffe berücksichtigen."},{"label":"Scheibenwechsel als Fachablauf","text":"Gerät nach Anleitung von der Energieversorgung trennen und Stillstand abwarten. Passende unbeschädigte Scheibe auswählen; Abmessungen, Aufnahme und zulässige Drehzahl müssen stimmen. Das freigegebene Befestigungssystem mit vorgesehenem Werkzeug lösen, Anlageflächen prüfen und Scheibe, Flansche und Spannmittel nach Herstelleranordnung montieren. Schutzhaube und freien Lauf kontrollieren; den vorgeschriebenen Probelauf in gesichertem Bereich durchführen. Schnellwechselsysteme haben einen eigenen Ablauf."},{"label":"Gleich lange Werkstücke sägen","text":"Zeichnung und Schnittmaß festlegen; Material, Sägeblatt und Schnittdaten aufeinander abstimmen. Bei stillgesetzter Säge den vorgesehenen Längenanschlag einrichten und lange Stangen abstützen. Jedes Werkstück sicher im Spannmittel halten, den Schnitt mit freigegebenem Vorschub ausführen und erst nach Stillstand lösen oder entnehmen. Erstes Teil messen, Einstellung nötigenfalls korrigieren und die Serie mit regelmäßigen Maßkontrollen fortsetzen. Der Anschlag darf das abgetrennte Teil nicht einklemmen."},{"label":"Entgraten","text":"Grate und scharfe Kanten verursachen Schnittverletzungen und können Montage, Auflage sowie Maßprüfung verfälschen. Nacharbeit verbessert die sichere Handhabung und die Funktion; geforderte Fasen und Maße müssen erhalten bleiben."}],"mnemonic":"Passendes Werkzeug, festes Werkstück, stillstehender Werkzeugwechsel.","pitfall":"Eine Trennscheibe seitlich zum Schruppen belasten oder das Werkstück an der Kreissäge freihändig halten.","keywords":["Winkelschleifer","Trennscheibe","Spannmittel","Längenanschlag","Entgraten"],"sources":[{"label":"Bosch: Betriebsanleitung GWS – Scheibenmontage und Sicherheit","url":"https://www.bosch-professional.com/binary/manualsmedia/o20130v21_09004a11800a7daa.pdf"},{"label":"Bosch: Metalltrennsäge GCD 12 JL, Herstellerunterlagen","url":"https://www.bosch-professional.com/de/de/products/gcd-12-jl-0601B28000"}],"minutes":4,"pdfPage":54},{"id":"E26","title":"Hydraulikpumpe: Fördermenge und Fehler verstehen","category":"Mechanik","question":"Welche drei Fehlergruppen vermindern die Leistung einer Hydraulikanlage? Wie erkennt man Saug- und Druckseite von Zahnradpumpen am Funktionsprinzip, welche Instandsetzung ist möglich und lässt sich die Fördermenge bei unveränderter Drehzahl verstellen?","answer":[{"label":"Drei Fehlergruppen","text":"Erstens kann die Ansaugung behindert sein, etwa durch einen verschmutzten Saugfilter, zu niedrigen Ölstand oder eine undichte Saugleitung; Luft und Kavitation vermindern die Förderung. Zweitens verursachen verschlissene Pumpenspalte oder undichte Ventile interne Leckage. Drittens kann ein falsch eingestelltes oder defektes Druckbegrenzungsventil Öl zu früh zum Tank ableiten. Zu hohe Öltemperatur und falsche Viskosität können die Symptome verstärken."},{"label":"Saug- und Druckseite im Bild","text":"Links ist eine Außenzahnradpumpe, rechts eine Innenzahnradpumpe mit Sichel zu erkennen. Dort, wo Zahnzwischenräume größer werden beziehungsweise Zähne aus dem Eingriff laufen, liegt die Saugseite. Das Öl wird in den Zahnlücken am Gehäuse entlang transportiert; beim erneuten Zahneingriff wird es zur Druckseite verdrängt. Eine feste Zuordnung oben/unten oder links/rechts erfordert erkennbare Drehrichtungspfeile; diese sind in der vorliegenden Abbildung nicht eindeutig lesbar."},{"label":"Fachgerechte Reparatur","text":"Zunächst die Ursache nachweisen. Je nach freigegebener Bauart können Dichtungen, Lager oder passende Reparatursätze ersetzt werden. Verschlissene Zahnräder, Seitenplatten und Gehäuse erfordern häufig eine spezialisierte Überholung oder den Pumpenaustausch. Passungen nicht improvisiert nacharbeiten; Sauberkeit, Herstellerdaten und eine abschließende Prüfung sind wesentlich."},{"label":"Konstante Drehzahl","text":"Für eine übliche Zahnrad-Konstantpumpe gilt näherungsweise Q = Vg · n · ηv. Bei festem Verdrängungsvolumen Vg und konstanter Drehzahl n lässt sich ihr theoretischer Förderstrom nicht wie bei einer Verstellpumpe einstellen. Eine Drossel oder ein Bypass verändert den Verbraucher- beziehungsweise Rücklaufstrom und erzeugt Verluste, aber nicht das geometrische Fördervolumen der Pumpe."}],"mnemonic":"Zähne öffnen: saugen. Zähne schließen: drücken.","pitfall":"Eine Drossel als Verstellung der Konstantpumpe erklären oder eine nicht erkennbare Drehrichtung erfinden.","keywords":["Zahnradpumpe","Saugseite","Druckseite","Leckage","Kavitation","Volumenstrom"],"sources":[{"label":"Bosch Rexroth: Innenzahnradpumpen mit konstantem Verdrängungsvolumen","url":"https://www.boschrexroth.com/ics/Projects/GenericSelector/?ProductArea=PGP&c=ch&language=de"},{"label":"Bosch Rexroth: Hydraulikfehler, Ursachen und Vorbeugung","url":"https://www.boschrexroth.com/en/pl/service-and-support/service/repairs/failures-causes-and-advices/"},{"label":"Bosch Rexroth: Zahnradpumpen und Ersatzteilzuordnung","url":"https://www.boschrexroth.com/ics/AZMaschinen/FAQ.cfm?ModelCode=AZ&language=en"}],"minutes":4,"pdfPage":54,"imagePage":68,"imagePages":[68]},{"id":"E27","title":"Buskommunikation und Übertragungsrichtungen","category":"Automation","question":"Was verbindet ein industrieller Bus, welche Informationen transportiert er und wie unterscheiden sich Simplex, Halbduplex und Vollduplex anhand anschaulicher Beispiele?","answer":[{"label":"Bedeutung und Aufgabe","text":"Ein Bus ist ein gemeinsamer Kommunikationsweg mit festgelegten elektrischen beziehungsweise optischen Eigenschaften und einem Protokoll. Steuerungen, dezentrale Ein-/Ausgänge, Sensoren und Antriebe tauschen darüber Prozessdaten, Parameter und Diagnosemeldungen aus. Es gibt keine für alle Bussysteme verbindliche Auflösung von BUS als Wortabkürzung."},{"label":"Simplex","text":"Daten fließen nur in eine Richtung, beispielsweise von einem reinen Sender zu einem Empfänger. Es gibt auf diesem Kommunikationsweg keine Rückübertragung."},{"label":"Halbduplex","text":"Beide Richtungen sind möglich, aber zeitlich abwechselnd. Teilnehmer müssen den Zugriff koordinieren. Eine typische RS-485-Verbindung arbeitet so; ein Teilnehmer sendet, während die anderen empfangen."},{"label":"Vollduplex","text":"Beide Seiten können gleichzeitig senden und empfangen. Moderne geswitchte Ethernet-Verbindungen nutzen dies üblicherweise. Getrennte Übertragungsrichtungen beziehungsweise geeignete Signalverfahren ermöglichen den gleichzeitigen Austausch."},{"label":"Begriffe auseinanderhalten","text":"Simplex/Halbduplex/Vollduplex beschreiben die Richtungen. Master-Slave, Token-Verfahren und Publisher/Subscriber beschreiben dagegen Rollen oder Kommunikationsabläufe. Bus-, Stern- und Ringstruktur bezeichnen die Topologie. Diese Einteilungen beantworten unterschiedliche Fragen."}],"mnemonic":"Simplex: hin. Halbduplex: abwechselnd. Vollduplex: gleichzeitig.","pitfall":"Die Übertragungsrichtung mit Buszugriffsverfahren oder Netzwerktopologie vermischen.","keywords":["Bus","Prozessdaten","Simplex","Halbduplex","Vollduplex","Protokoll"],"sources":[{"label":"Cisco: Halbduplex, Vollduplex und Aushandlung","url":"https://www.cisco.com/c/en/us/support/docs/lan-switching/ethernet/10561-3.html"},{"label":"PI: PROFIBUS-Installationsrichtlinien","url":"https://www.profibus.com/download/profibus-installation-guidelines"}],"minutes":4,"pdfPage":55},{"id":"E28","title":"Lichtgitter, Lichtvorhang und sichere Auswahl","category":"Sicherheit","question":"Wie lassen sich Mehrstrahlgeräte mit unterschiedlicher Auflösung unterscheiden? Nach welchen Daten wählen Sie ein Gerät für große Entfernungen aus, und welche Schutz- beziehungsweise Messaufgaben sind möglich?","answer":[{"label":"Begriffe und Auflösung","text":"Die Bezeichnungen werden nicht überall einheitlich verwendet. Ein Lichtvorhang besitzt meist viele eng benachbarte Strahlen und kann je nach Auflösung Finger oder Hände erfassen. Ein Mehrstrahl-Sicherheitslichtgitter mit wenigen weiter auseinanderliegenden Strahlen wird häufig zur Zugangssicherung eingesetzt. Entscheidend sind das Datenblatt und die vom Hersteller erklärte Verwendung."},{"label":"Große Entfernungen","text":"Nicht allein anhand des Namens entscheiden. Verglichen werden spezifizierte Mindest-/Maximalreichweite, Auflösung, Schutzfeldhöhe und Umgebungsbedingungen. Ein Gerät mit wenigen Strahlen kann für große Zugangsbreiten geeignet sein, doch auch Lichtvorhänge sind je nach Typ für größere Reichweiten ausgelegt. Für eine konkrete Auswahl müssen Entfernung und erforderliche Erkennungsgröße bekannt sein."},{"label":"Sicherheitsaufgaben","text":"Geeignete zertifizierte Systeme sichern Gefahrstellen oder Zugänge, indem sie eine Unterbrechung sicherheitsgerichtet auswerten. Sicherheitsabstand, Nachlaufzeit, Hintertretbarkeit und Wiederanlaufverhalten gehören zum Schutzkonzept; eine Schutzeinrichtung verhindert nicht automatisch das Wegschleudern von Teilen."},{"label":"Mess- und Erfassungsaufgaben","text":"Messende Lichtgitter können Konturen, Höhe, Position, Anwesenheit oder Anzahl von Objekten erfassen. Ein Standard-Messgerät ist dadurch noch kein für Personenschutz geeignetes Sicherheitsgerät. Muting oder Ausblendung sind nur nach der vorgesehenen sicherheitstechnischen Auslegung zulässig."}],"mnemonic":"Für die Auswahl zählen Auflösung, Reichweite und Sicherheitsfunktion.","pitfall":"„Lichtgitter reicht immer weiter als Lichtvorhang“ als allgemeines Gesetz lernen.","keywords":["Lichtgitter","Lichtvorhang","Auflösung","Reichweite","Schutzfeld","Sicherheitsabstand"],"sources":[{"label":"SICK: Was ist ein Sicherheits-Lichtvorhang?","url":"https://www.sick.com/be/de/was-genau-ist-ein-sicherheits-lichtvorhang/w/blog-definition-safety-light-curtain"},{"label":"SICK: deTec4 – Auflösung, Reichweite und Schutzfeld","url":"https://www.sick.com/media/docs/0/40/840/operating_instructions_detec4_safety_light_curtain_de_im0079840.pdf"}],"minutes":4,"pdfPage":55},{"id":"E29","title":"Hydraulik warten und Speicher sichern","category":"Sicherheit","question":"Welche drei Wartungsfelder sind bei einer Hydraulikanlage wichtig? Welche gespeicherten Energien sind vor Arbeiten zu beherrschen, wie unterscheiden sich zwei Speicherbauarten und welches Gas ist zugelassen?","answer":[{"label":"Drei Wartungsfelder","text":"Ölzustand und Ölstand überwachen; Verschmutzung, Wasser und auffällige Temperatur beachten. Filterzustand nach Wartungsplan prüfen und geeignete Filterelemente ersetzen lassen. Leitungen, Anschlüsse, Schläuche und Dichtungen auf Schäden und Leckagen kontrollieren sowie fällige Arbeiten dokumentieren. Leckagen nicht mit der Hand suchen."},{"label":"Vor Arbeiten mit Speicher","text":"Nur fachkundiges Personal arbeitet nach Hersteller- und Anlagenanweisung. Anlage stillsetzen, Energien trennen und gegen Wiederanlauf sichern. Lasten mechanisch sichern; den Speicher von relevanten Anlagenteilen absperren und die Flüssigkeitsseite über die vorgesehene Einrichtung kontrolliert entlasten. Druckfreiheit an den betroffenen Stellen nachweisen. Bei Eingriffen am Speicher selbst muss auch die Gasseite entsprechend der Herstelleranweisung sicher drucklos sein. Das Abschalten der Pumpe allein genügt nicht."},{"label":"Zwei Bauarten","text":"Beim Blasenspeicher trennt eine elastische Blase Gas und Hydraulikflüssigkeit. Beim Kolbenspeicher übernimmt ein beweglicher abgedichteter Kolben diese Trennung. Beide nutzen die Kompressibilität des Gases, um Energie aufzunehmen und bei sinkendem Systemdruck Flüssigkeit abzugeben."},{"label":"Füllgas","text":"Für die üblichen gasbelasteten Hydraulikspeicher ist trockener Stickstoff in der vom Hersteller geforderten Qualität zu verwenden. Sauerstoff und Druckluft sind wegen Brand-/Explosionsgefahr ungeeignet. Das Befüllen ist eine Facharbeit mit freigegebener Füll- und Prüfausrüstung."}],"mnemonic":"Pumpe aus heißt nicht Speicher leer; Füllgas ist Stickstoff.","pitfall":"Eine Leitung lösen, obwohl noch Druck oder eine ungesicherte schwebende Last vorhanden ist.","keywords":["Hydraulikspeicher","Stickstoff","Blasenspeicher","Kolbenspeicher","Druckfreiheit","Wartung"],"sources":[{"label":"HYDAC: Kolbenspeicher – Wartung und Sicherheit, nur Stickstoff","url":"https://betterfit-us.hydac.com/wp-content/uploads/Piston%20Maintenance%20Manual.pdf"},{"label":"HYDAC: Funktionsweise von Hydraulikspeichern","url":"https://betterfit-us.hydac.com/faq/how-does-an-accumulator-work/"},{"label":"Bosch Rexroth: Hydraulikfehler, Ursachen und Vorbeugung","url":"https://www.boschrexroth.com/en/pl/service-and-support/service/repairs/failures-causes-and-advices/"}],"minutes":4,"pdfPage":56},{"id":"E30","title":"Drucktransmitter und Ausgangssignale","category":"Automation","question":"Was macht ein Drucktransmitter, wo wird er eingesetzt und wie interpretieren Sie seine typischen analogen und digitalen Ausgänge?","answer":[{"label":"Funktion","text":"Ein Drucktransmitter beziehungsweise Druckmessumformer erfasst Druck über ein Sensorelement und wandelt ihn mit einer Auswerteelektronik in ein normiertes oder digitales Signal um. Relativ-, Absolut- oder Differenzdruck müssen zur Messaufgabe passen."},{"label":"Einsatz und Auswahl","text":"Beispiele sind Drucküberwachung in Hydraulik und Pneumatik, Pumpenregelung, Filterüberwachung über Differenzdruck oder Füllstandsmessung über hydrostatischen Druck. Messbereich, Überlastfestigkeit, Medium, Temperatur, Prozessanschluss und Genauigkeit bestimmen die Auswahl."},{"label":"Analoge Signale","text":"Verbreitet sind 4–20 mA und 0–10 V; die genaue Ausführung steht im Datenblatt. Bei 4–20 mA liegt der Messbereichsanfang typischerweise bei 4 mA und der Endwert bei 20 mA. Für einen Bereich 0–100 bar entsprechen 12 mA idealisiert 50 bar. Die SPS muss denselben Bereich und Signaltyp skalieren."},{"label":"Digital und Abgrenzung","text":"Digitale Varianten liefern Messwert und häufig Diagnosedaten, etwa über IO-Link oder ein Bussystem. Nicht jeder Drucktransmitter besitzt jede Schnittstelle. Ein Druckschalter meldet dagegen vorrangig das Über-/Unterschreiten eines Schaltpunkts; Kombigeräte können Messwert und Schaltausgänge bereitstellen."}],"mnemonic":"Druck hinein, verwertbares Signal heraus.","pitfall":"Ein 4–20-mA-Signal als 0–20 mA skalieren oder Druckschalter und Messumformer gleichsetzen.","keywords":["Drucktransmitter","4–20 mA","0–10 V","Skalierung","Relativdruck","IO-Link"],"sources":[{"label":"WIKA: Druckmessumformer A-10","url":"https://shop.wika.com/en-us/a_10.WIKA?ProductGroup=100277&fromGeoIpOverlay=true"},{"label":"WIKA: Elektrische Schaltung bei Drucksensoren","url":"https://blog.wika.com/en/products/pressure-products/active-passive-sensor/?doing_wp_cron=1721298252.4989230632781982421875"}],"minutes":4,"pdfPage":56},{"id":"E31","title":"Netzwerkstecker fachgerecht anschließen","category":"Elektrotechnik","question":"Wie planen und prüfen Sie eine Kupfer-Netzwerkverbindung mit RJ45? Welche Werkzeuge passen zu Crimp- und Feldsteckern, welche Leitung darf verwendet werden und wie ist eine unklare Angabe wie „einpolig“ fachlich zu klären?","answer":[{"label":"Leitung und Stecker abstimmen","text":"Die geforderte Kategorie, Schirmung, Aderzahl, Leiterquerschnitte sowie Durchmesser müssen zu Stecker und Anwendung passen. Massivleiter für feste Installation und Litzenleiter für flexible Patchleitungen brauchen dafür zugelassene Kontakte. Bei PoE zusätzlich Strombelastbarkeit und Erwärmung berücksichtigen."},{"label":"Montagegrundablauf","text":"Verbindung außer Betrieb nehmen und nach der konkreten Herstelleranleitung ablängen sowie den Mantel entfernen, ohne Leiter oder Schirm zu verletzen. Verdrillung möglichst bis zur Kontaktstelle erhalten, Schirm und Zugentlastung richtig vorbereiten. Adern nach festgelegtem Schema T568A oder T568B beziehungsweise dem gerätespezifischen Industrie-Pinout einlegen. Kontakte vollständig herstellen und Gehäuse samt Zugentlastung schließen."},{"label":"Passende Werkzeuge","text":"Ein geeigneter Mantelabsetzer und Seitenschneider gehören zur Vorbereitung. Konventionelle modulare Crimpstecker verlangen die passende Crimpzange; feldkonfektionierbare Schneidklemmstecker benötigen das vorgesehene Montagewerkzeug oder sind werkzeuglos. Eine beliebige Zange ersetzt keine kompatible Anschlusstechnik."},{"label":"Prüfen","text":"Sichtprüfung und Wiremap prüfen Unterbrechung, Kurzschluss, Vertauschung und Schirmdurchgang. Ein einfacher Durchgangstester beweist keine Kategorie. Für einen normgerechten Leistungsnachweis sind geeignete Zertifizierungsmessungen einschließlich Längen- und Hochfrequenzparametern nötig; Split Pairs müssen erkannt werden."},{"label":"„Einpolig“ klären","text":"Für übliches Ethernet ist „einpoliges Kabel“ kein eindeutiger Fachbegriff. Ist ein eindrähtiger Massivleiter gemeint, einen dafür zugelassenen Stecker verwenden. Ist Single Pair Ethernet gemeint, sind es zwei Leiter als ein verdrilltes Paar mit passender SPE-Schnittstelle. Eine einzelne Ader lässt sich nicht durch eine frei erfundene RJ45-Belegung zum Ethernetkabel machen."}],"mnemonic":"Leiter, Kontakt und Prüfverfahren müssen zur Verbindung passen.","pitfall":"Litzen- und Massivleiterstecker vertauschen oder aus acht richtigen Durchgangswerten auf garantierte Gigabit-Qualität schließen.","keywords":["RJ45","Crimpen","Massivleiter","T568B","Wiremap","Single Pair Ethernet"],"sources":[{"label":"Telegärtner: Datenverkabelung, RJ45 und Anschlusstechnik","url":"https://www.telegaertner.com/fileadmin/user_upload/Downloads/Kataloge/DV-Enterprise_Katalog_DE.pdf"},{"label":"METZ CONNECT: Reference Guide – Kupfer, LSA-Anschlusstechnik","url":"https://www.metz-connect.com/media/file/8a8a80ea92e237ff01931b3e86fb7e8f.de.0/reference_guide_de.pdf"},{"label":"Phoenix Contact: Single Pair Ethernet mit zwei Adern","url":"https://assets.phoenixcontact.com/file/faa818a7-4934-4d78-979b-5551e8160e3b/media/original?SPE_news_release_Final.pdf="}],"minutes":4,"pdfPage":57},{"id":"E32","title":"Netzwerkleitungen und LSA verstehen","category":"Elektrotechnik","question":"Vergleichen Sie Kupfer-Twisted-Pair und Lichtwellenleiter mit je zwei Eigenschaften. Wie stellt eine LSA-Verbindung Kontakt her und welche Grenzen sind dabei zu beachten?","answer":[{"label":"Twisted-Pair-Kupfer","text":"Verdrillte Aderpaare übertragen elektrische Differenzsignale. Die Verbindung ist kostengünstig und unterstützt bei passender Technik auch die Energieversorgung über PoE. Reichweite und Störfestigkeit hängen von Kategorie, Ausführung und Installation ab; elektromagnetische Einflüsse sowie Potenzialunterschiede sind zu berücksichtigen."},{"label":"Lichtwellenleiter","text":"Ein LWL überträgt Licht und ist gegen elektromagnetische Einstreuung unempfindlich. Er trennt die Endgeräte galvanisch und eignet sich, mit passenden Fasern und Transceivern, für große Entfernungen. Er benötigt saubere Steckflächen und die Einhaltung zulässiger Biegeradien; elektrisches PoE kann er nicht direkt übertragen."},{"label":"LSA-Verbindung","text":"LSA bedeutet löt-, schraub- und abisolierfrei. Eine isolierte Einzelader wird mit dem vorgesehenen Auflegewerkzeug in einen Schneidklemmkontakt gedrückt. Die Kontaktkanten durchdringen die Aderisolation und kontaktieren den Leiter; das Werkzeug kann den Überstand zugleich kürzen. Typische Anwendungen sind Anschlussdosen und Patchfelder."},{"label":"Montagegrenzen","text":"Nur zugelassene Leiterarten und -durchmesser verwenden. Den Außenmantel und gegebenenfalls Schirm bereitet man trotzdem nach Anleitung vor; „abisolierfrei“ bezieht sich auf die einzelne Kontaktstelle. Erneutes Auflegen erfolgt bei Bedarf an einem unbeschädigten Leiterabschnitt."}],"mnemonic":"Kupfer leitet Strom, Faser leitet Licht, LSA schneidet durch die Aderisolation.","pitfall":"„Abisolierfrei“ so verstehen, dass die Leitung ohne jede Vorbereitung angeschlossen wird.","keywords":["Twisted Pair","Lichtwellenleiter","Galvanische Trennung","PoE","LSA","Schneidklemme"],"sources":[{"label":"Phoenix Contact: Industrielle Kommunikation und Übertragungsmedien","url":"https://www.phoenixcontact.com/en-au/products/industrial-communication"},{"label":"METZ CONNECT: Reference Guide – Kupfer, LSA-Anschlusstechnik","url":"https://www.metz-connect.com/media/file/8a8a80ea92e237ff01931b3e86fb7e8f.de.0/reference_guide_de.pdf"}],"minutes":4,"pdfPage":57},{"id":"E33","title":"Maschinen bewegen und Kranberechtigung einordnen","category":"Sicherheit","question":"Welche maschinellen und manuellen Transportmittel kommen für Werkzeugmaschinen infrage, welche Voraussetzungen gelten in Österreich für das Kranführen, welche Anschlagmittel kennen Sie und was ist vor dem Anlagentransport zu planen?","answer":[{"label":"Transportmöglichkeiten","text":"Maschinell sind beispielsweise Hallenkran und geeigneter Gabelstapler einsetzbar. Für einen manuellen, aber technisch unterstützten Transport können Handhubwagen oder zugelassene Maschinentransportfahrwerke dienen, wenn Last, Schwerpunkt und Untergrund dazu passen. Eine schwere Werkzeugmaschine wird nicht durch bloße Muskelkraft sicher transportierbar."},{"label":"Kranführen in Österreich","text":"Erforderlich sind geeignete, entsprechend unterwiesene Personen und eine ausdrückliche Fahrbewilligung des Arbeitgebers; für bestimmte Krane zusätzlich der passende Fachkenntnisnachweis. Die vereinfachte Angabe „über 5 t“ ersetzt nicht die Rechtsprüfung: § 3 FK-V nennt unter anderem flurgesteuerte Krane bis 50 kN als Ausnahme; bei Fahrzeug-/Ladekranen sind auch 100 kNm Lastmoment und die genaue Bauart relevant. 50 kN entsprechen ungefähr 5 t. Für große Krane gelten die entsprechenden Nachweise; Minderjährigenschutz ist zusätzlich zu beachten."},{"label":"Zwei Anschlagmittel","text":"Anschlagketten und geeignete Rundschlingen beziehungsweise Hebebänder verbinden Lastaufnahmemittel und Last. Tragfähigkeit, Anschlagart, Winkel, Kantenschutz und Herstellerfreigaben müssen zur Last passen. Beschädigte oder nicht eindeutig gekennzeichnete Mittel ausscheiden."},{"label":"Transport vorbereiten","text":"Masse, Schwerpunkt und freigegebene Anschlagpunkte aus der Dokumentation ermitteln; Transportweg, Boden-/Deckentragfähigkeit und Durchfahrten prüfen. Versorgung fachgerecht trennen, Restenergien sichern, bewegliche Teile und Werkzeug festsetzen und empfindliche Baugruppen schützen. Ein geeigneter Transportplan legt Mittel, Lastsicherung, Zuständigkeiten, Absperrung und Kommunikation fest."}],"mnemonic":"Masse und Schwerpunkt kennen, Mittel prüfen, Personen berechtigen.","pitfall":"Eine deutsche Kranregel als österreichische Antwort verwenden oder die 5-t-Angabe ohne Kranart und Lastmoment auslegen.","keywords":["Transport","Kran","Fachkenntnisnachweis","Fahrbewilligung","Schwerpunkt","Anschlagmittel"],"sources":[{"label":"RIS Österreich: FK-V § 3 – Ausnahmen und genaue Grenzen","url":"https://www.ris.bka.gv.at/NormDokument.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20005222&Paragraf=3"},{"label":"Arbeitsinspektion Österreich: Krane, Fachkenntnisse und Fahrbewilligung","url":"https://www.arbeitsinspektion.gv.at/arbeitsschutz/arbeitsmittel/heben_lasten_personen/krane_lastenaufnahmeeinrichtungen_anschlagmittel.html"},{"label":"DGUV/IFA: Anschlagmittel und Prüfung vor Benutzung","url":"https://www.dguv.de/ifa/praxishilfen/gefahrenschwerpunkt-frachtcontainer/lexikon/anschlagmittel/index.jsp"}],"minutes":4,"pdfPage":58},{"id":"E34","title":"Transportmittel und ablegereife Drahtseile","category":"Sicherheit","question":"Welche Einrichtungen unterstützen den mechanischen Transport, wann muss ein Stahlseil aus dem Betrieb genommen werden und welche gemeinsamen Regeln schützen bei maschinellem und manuell unterstütztem Transport?","answer":[{"label":"Mechanische Transportmittel","text":"Dazu zählen Krane und Hebezeuge, Stapler, Hubwagen, Rollenbahnen sowie zugelassene Transportfahrwerke. Ihre Eignung wird aus Tragfähigkeit, Lastgeometrie, Schwerpunkt, Hubhöhe, Transportweg und Untergrund bestimmt."},{"label":"Schäden an Drahtseilen","text":"Ausscheidegründe sind beispielsweise Knicke oder Kinken, Quetschungen, Korbbildung, herausgetretene Einlage, starke Korrosion, Hitzeschäden, beschädigte Endverbindungen und eine unzulässige Zahl von Drahtbrüchen. Auch deutlicher Verschleiß beziehungsweise Durchmesserverlust ist kritisch. Die genaue Ablegegrenze hängt von Seilart, Einsatz und Hersteller-/Prüfvorschrift ab; es gibt keine universelle Drahtbruchzahl."},{"label":"Prüfung und Entscheidung","text":"Vor Gebrauch Sichtprüfung, Kennzeichnung und geeignete Tragfähigkeit kontrollieren. Bei Zweifel Seil sperren und durch eine fachkundige Person beurteilen lassen. Ein beschädigtes Anschlagseil wird nicht durch Knoten, provisorische Klemmen oder eigenmächtiges Kürzen repariert."},{"label":"Transportregeln","text":"Last sicher aufnehmen, gegen Verrutschen und Kippen sichern und den Weg freihalten. Personen fernhalten und nie unter schwebender Last stehen. Niemand darf zwischen Last und festem Hindernis eingeklemmt werden; Signale und Zuständigkeiten festlegen. Beim manuellen Bewegen technische Hilfsmittel und ausreichend Personal einsetzen, Belastung beurteilen und abgestimmt handeln."}],"mnemonic":"Ein beschädigtes Seil wird gesperrt, eine unsichere Last bleibt stehen.","pitfall":"Eine einzelne pauschale Drahtbruchzahl für jedes Stahlseil lernen oder Tragfähigkeit nur aus dem Seildurchmesser schätzen.","keywords":["Drahtseil","Ablegereife","Kinke","Korrosion","Lastsicherung","Transportweg"],"sources":[{"label":"BG BAU: Ablegereife von Anschlag-Drahtseilen","url":"https://www.bgbau-medien.de/handlungshilfen_gb/daten/dguv/109_005/5.htm"},{"label":"DGUV/IFA: Anschlagmittel und Prüfung vor Benutzung","url":"https://www.dguv.de/ifa/praxishilfen/gefahrenschwerpunkt-frachtcontainer/lexikon/anschlagmittel/index.jsp"},{"label":"AUVA: Evaluierung manueller Lastenhandhabung","url":"https://auva.at/praevention/sicher-arbeiten/evaluierung/lastenhandhabung"}],"minutes":4,"pdfPage":58},{"id":"E35","title":"Lasten von Hand, auf Rollen und als Blech transportieren","category":"Sicherheit","question":"Welche Hilfsmittel und persönliche Schutzausrüstung helfen beim manuellen Transport? Wie schützen Sie Anschlagmittel an Kanten, was ist bei Richtungswechseln mit Rollen zu beachten und welche besonderen Gefahren gehen von Blechen aus?","answer":[{"label":"Hilfsmittel und PSA","text":"Vorrang haben geeignete Hub- und Transporthilfen, etwa Hubwagen, Handkarren, Hebehilfen oder zugelassene Tragegriffe. Die manuelle Belastung ist nach Masse, Häufigkeit, Körperhaltung und Weg zu beurteilen. Sicherheitsschuhe und geeignete Schutzhandschuhe gehören je nach Aufgabe dazu; weitere PSA ergibt sich aus der Gefährdungsbeurteilung."},{"label":"Scharfe Lastkanten","text":"Seile und textile Anschlagmittel gegen Einschneiden, Quetschen und zu enge Biegeradien mit geeigneten Kantenschonern schützen. Tragfähigkeit und zulässigen Kantenradius nach Herstellerangaben einhalten. Ein zufällig untergelegtes dünnes Tuch ist kein nachgewiesener Kantenschutz."},{"label":"Richtungswechsel auf Rollen","text":"Das Prinzip besteht darin, die Ausrichtung der tragenden Rollen beziehungsweise eines lenkbaren Transportfahrwerks kontrolliert zu ändern. Das erfolgt nur mit abgestimmtem Transportplan und gesichertem Lastzustand; Hände und Füße bleiben aus dem Quetschbereich. Lose Rundstangen und spontanes Umlegen unter einer ungesicherten Maschine sind keine sichere Transportmethode. Bei schweren Anlagen eine geeignete Fachfirma einsetzen."},{"label":"Bleche","text":"Scharfe Kanten verursachen Schnittverletzungen, große Flächen können ausschwenken und hochkant stehende Bleche umkippen. Geeignete Blechgreifer oder freigegebene Hebemittel benutzen und Abrutschen sowie Kippen verhindern. Wege und Ablage vorbereiten, Hände von Kanten-/Quetschstellen fernhalten und Bleche in dafür geeigneten Einrichtungen standsicher lagern."}],"mnemonic":"Hilfsmittel tragen die Last, Kantenschutz schützt das Anschlagmittel.","pitfall":"Mit den Händen unter der Last Rollen nachlegen oder ein Blech nur wegen geringer Dicke für leicht beherrschbar halten.","keywords":["Lastenhandhabung","Kantenschutz","Transportrollen","Blechgreifer","Schnittschutz","Quetschgefahr"],"sources":[{"label":"AUVA: Evaluierung manueller Lastenhandhabung","url":"https://auva.at/praevention/sicher-arbeiten/evaluierung/lastenhandhabung"},{"label":"Suva: Transport und Lagerung von Blechen","url":"https://www.suva.ch/de-ch/download/checklisten/transport-und-lagerung-von-blechen/transport-und-lagerung-von-blechen--67111.D"},{"label":"DGUV/IFA: Anschlagmittel und Prüfung vor Benutzung","url":"https://www.dguv.de/ifa/praxishilfen/gefahrenschwerpunkt-frachtcontainer/lexikon/anschlagmittel/index.jsp"}],"minutes":4,"pdfPage":59},{"id":"E36","title":"Twisted Pair, Hub und Switch erkennen","category":"Automation","question":"Beschreiben Sie eine geschirmte Kupfer-Datenleitung mit vier verdrillten Aderpaaren und RJ45-Anschluss. Warum werden die Adern verdrillt, und wie unterscheidet sich ein Hub von einem Ethernet-Switch?","answer":[{"label":"Leitung im Bild","text":"Das Foto zeigt eine Kupfer-Twisted-Pair-Datenleitung mit acht isolierten Adern in vier farbcodierten Paaren, sichtbaren Schirmbestandteilen und Außenmantel sowie einen geschirmten RJ45-Stecker. Eine genaue Kategorie oder vollständige Schirmbezeichnung lässt sich aus dem Foto allein nicht zuverlässig bestimmen; dafür sind Aufdruck und Datenblatt maßgeblich."},{"label":"Wirkung der Verdrillung","text":"Ein symmetrisches Aderpaar führt gegenläufige Signale. Durch die Verdrillung wirken äußere Störungen möglichst ähnlich auf beide Leiter und können beim Differenzempfang unterdrückt werden. Zugleich werden elektromagnetische Abstrahlung und Übersprechen reduziert. Zu weit aufgedrehte Paare verschlechtern die Übertragungseigenschaften."},{"label":"Hub beziehungsweise Multiport-Repeater","text":"Ein Hub arbeitet auf der physikalischen Ebene. Er gibt empfangene Signale an die übrigen Ports weiter, ohne Ziel-MAC-Adressen auszuwerten. Klassisches Hub-Ethernet teilt Bandbreite und Kollisionsbereich und arbeitet halbduplex."},{"label":"Switch","text":"Ein Switch lernt Quell-MAC-Adressen und ihre Ports. Bekannte Unicast-Ziele werden gezielt an den betreffenden Port weitergeleitet. Broadcasts und unbekannte Ziele werden innerhalb des betreffenden Netzes beziehungsweise VLANs weiterhin verteilt. Die einzelnen Verbindungen können vollduplex arbeiten; sie teilen nicht mehr einen gemeinsamen Kollisionsbereich."}],"mnemonic":"Twisted Pair verbessert das Signal, der Switch wählt den Zielport.","pitfall":"Behaupten, ein Switch sende niemals an mehrere Ports oder die Kabelfarbe beweise die Kategorie.","keywords":["Twisted Pair","RJ45","Differenzsignal","Hub","Switch","MAC-Adresse"],"sources":[{"label":"Telegärtner: Datenverkabelung, RJ45 und Anschlusstechnik","url":"https://www.telegaertner.com/fileadmin/user_upload/Downloads/Kataloge/DV-Enterprise_Katalog_DE.pdf"},{"label":"Cisco: Hub und Switch – Weiterleitung von Ethernet-Verkehr","url":"https://www.cisco.com/c/en/us/td/docs/routers/asr9000/software/asr9k-r6-3/interface/configuration/guide/b-interfaces-hardware-component-cg-asr9000-63x/b-interfaces-hardware-component-cg-asr9000-63x_chapter_01001.pdf"}],"minutes":4,"pdfPage":59,"imagePage":69,"imagePages":[69]},{"id":"E37","title":"Löten, SMD und Reflow","category":"Elektrotechnik","question":"Was geschieht beim Löten im Unterschied zum Aufschmelzen des Grundwerkstoffs? Erklären Sie SMD, zwei elektrische Lötverfahren, zwei Entlöthilfen und den Ablaufgedanken des Reflowlötens.","answer":[{"label":"Löten","text":"Ein geschmolzenes Lot benetzt die metallischen Fügeflächen und bildet nach dem Erstarren eine stoffschlüssige Verbindung. Die Grundwerkstoffe bleiben dabei fest. Geeignete Oberflächen, Flussmittel und ein beherrschter Wärmeeintrag sind entscheidend; in der Elektronik wird überwiegend weichgelötet."},{"label":"SMD-Technik","text":"SMD steht für Surface Mounted Device. Die Bauteilanschlüsse werden auf Lötflächen an der Leiterplattenoberfläche kontaktiert, statt Anschlussdrähte durch Bohrungen zu führen. SMT bezeichnet die zugehörige Oberflächenmontagetechnik."},{"label":"Zwei Lötverfahren","text":"Beim Handlöten führt eine geeignete temperaturgeregelte Lötspitze Wärme an Anschluss und Lötfläche. Beim Reflowlöten wird zuvor aufgebrachte Lotpaste aufgeschmolzen. Weitere industrielle Verfahren sind Wellen- und Selektivlöten, vor allem für bedrahtete Anschlüsse."},{"label":"Entlöten","text":"Entlötlitze nimmt flüssiges Lot durch Kapillarwirkung auf. Eine Entlötpumpe beziehungsweise Vakuum-Entlötstation saugt aufgeschmolzenes Lot ab. Für bestimmte SMD-Bauformen kommen geregelte Heißluft- oder Reworksysteme hinzu. Zug an noch nicht vollständig freigeschmolzenen Anschlüssen kann Pads abreißen."},{"label":"Reflowprinzip","text":"Lotpaste auf die Pads aufbringen, Bauteile platzieren und die Baugruppe mit einem zu Paste und Bauteilen passenden Temperaturprofil erwärmen. Nach Vorwärmen und eigentlicher Aufschmelzphase entstehen beim kontrollierten Abkühlen die Verbindungen. ESD-Schutz, Absaugung und Temperaturgrenzen sind zu beachten."}],"mnemonic":"Lot schmilzt, Grundwerkstoff bleibt fest; Reflow schmilzt vorbereitete Lotpaste.","pitfall":"SMD mit einer Lötmethode gleichsetzen oder ein Bauteil vor dem vollständigen Entlöten abziehen.","keywords":["Löten","SMD","SMT","Reflow","Entlötlitze","Lotpaste"],"sources":[{"label":"Ersa: Lötfibel – THT, SMD, Reflow und Entlöten","url":"https://www.ersa-shop.de/images/p_info/edb_700030226_Loetfibel_web_deu.pdf"}],"minutes":4,"pdfPage":60},{"id":"E38","title":"Statische und temporäre Daten, FC und FB","category":"Automation","question":"Wie unterscheiden sich bei Siemens-SPS temporäre und statische Variablen sowie FC und FB? Erklären Sie, welcher Baustein für eine reine Berechnung und welcher für einen zustandsbehafteten Antrieb passt.","answer":[{"label":"Temporäre Variable","text":"TEMP-Daten dienen als Zwischenergebnisse während eines Bausteinaufrufs. Ihr Wert steht nicht als eigener gespeicherter Zustand für den nächsten Aufruf zur Verfügung. Vor dem Lesen muss ein definierter Wert vorliegen. Bei nicht optimierten Bausteinen können Anfangswerte undefiniert sein; bestimmte optimierte S7-1200/1500-Bausteine initialisieren TEMP-Daten mit dem Datentyp-Standardwert. Darauf darf man nicht systemübergreifend vertrauen."},{"label":"Statische Variable","text":"STAT-Daten eines FB liegen im zugehörigen Instanzspeicher. Sie behalten ihren Wert zwischen Aufrufen, beispielsweise einen Ablaufzustand oder eine gespeicherte Flanke. Das bedeutet nicht automatisch Remanenz bei Spannungsausfall; Remanenz ist eine gesonderte Eigenschaft beziehungsweise Einstellung."},{"label":"Funktion FC","text":"Ein Siemens-FC besitzt keinen eigenen Instanz-DB für statische Bausteindaten. Er eignet sich beispielsweise für eine Skalierungs- oder Rechenfunktion mit übergebenen Parametern. Ein FC kann dennoch globale Daten lesen oder schreiben; „kein eigener Speicher“ bedeutet nicht „kein Zugriff auf gespeicherte Daten“."},{"label":"Funktionsbaustein FB","text":"Ein FB besitzt Instanzdaten und eignet sich für Zustände über mehrere Aufrufe, etwa einen Antrieb mit Betriebszustand und Zeitgliedern. Jede unabhängige Verwendung benötigt eine eigene Instanz; diese kann als Einzelinstanz oder Multiinstanz angelegt sein."}],"mnemonic":"TEMP für diesen Aufruf, STAT für den nächsten – remanent ist eine eigene Frage.","pitfall":"STAT mit spannungsausfallsicher verwechseln oder behaupten, ein FC könne grundsätzlich keinen gespeicherten Wert verändern.","keywords":["TEMP","STAT","FC","FB","Instanz-DB","Remanenz"],"sources":[{"label":"Siemens: Programmierleitfaden S7-1200/S7-1500, FC, FB und Variablen","url":"https://cache.industry.siemens.com/dl/files/040/90885040/att_970576/v1/81318674_Programming_guideline_DOC_v16_en.pdf"}],"minutes":4,"pdfPage":60},{"id":"E39","title":"Inbetriebnahme nachweisbar protokollieren","category":"Automation","question":"Welche vier Eigenschaften machen ein Inbetriebnahmeprotokoll brauchbar, welche Angaben gehören hinein und welche Prozessdaten benötigen Sie für eine passende Anlagenauslegung?","answer":[{"label":"Vier Qualitätsmerkmale","text":"Ein Protokoll soll vollständig, nachvollziehbar, objektiv prüfbar und eindeutig zuordenbar sein. Ein fremder Fachkundiger muss erkennen können, welche Anlage in welchem Zustand nach welchen Kriterien geprüft wurde und ob die Anforderungen erfüllt waren."},{"label":"Inhalt","text":"Anlagenidentifikation, Datum, beteiligte Personen, Hardware-/Softwarestände und Prüfbedingungen festhalten. Sollwerte, Messmethode, tatsächliche Ergebnisse und Bewertung getrennt dokumentieren. Auch Schutzfunktionen, Schnittstellen, erkannte Mängel, Verantwortliche, Fristen und Freigaben gehören hinein; eine bloße Unterschrift ersetzt keine Ergebnisse."},{"label":"Nutzen","text":"Die Dokumentation unterstützt Übergabe, Abnahme, spätere Fehlersuche und den Nachweis von Änderungen. Offene Punkte bleiben sichtbar und können gezielt abgearbeitet werden. Für gesetzlich vorgeschriebene Prüfungen gelten zusätzlich die Anforderungen an den jeweiligen Prüfbefund."},{"label":"Dimensionierung","text":"Benötigt werden geforderter Durchsatz/Takt, Produktvarianten und Toleranzen sowie Werkstücklasten, Kräfte, Drehmomente und Bewegungsprofile. Verfügbarkeit, Rüstzeiten, Ausschuss, Medienversorgung, Platz und Umgebung beeinflussen Kapazität und Reserven. Motorleistung allein beschreibt nicht die Leistungsfähigkeit einer Gesamtanlage."}],"mnemonic":"Ein gutes Protokoll verbindet Anforderung, Messwert und Entscheidung.","pitfall":"Nur „funktioniert“ dokumentieren oder eine Anlage ohne Rüst- und Stillstandszeiten auf den theoretischen Takt auslegen.","keywords":["Inbetriebnahmeprotokoll","Prüfkriterium","Messwert","Freigabe","Durchsatz","Lastprofil"],"sources":[{"label":"Arbeitsinspektion: Prüfungen vor der ersten Inbetriebnahme","url":"https://www.arbeitsinspektion.gv.at/arbeitsschutz/arbeitsmittel/pruefung_arbeitsmittel.html"},{"label":"Siemens: Antriebe mit Lastprofil dimensionieren","url":"https://support.industry.siemens.com/cs/attachments/109773995/micro-drive_in_tst_getting_started_en-US_en-US.pdf"}],"minutes":4,"pdfPage":61},{"id":"E40","title":"Schrittketten und Bussysteme","category":"Automation","question":"Erklären Sie Schritt und Transition an einem einfachen Ablauf, nennen Sie zwei Vorteile von GRAPH/SFC und beschreiben Sie, welche Aufgaben das Kommunikationssystem in der Anlage übernimmt.","answer":[{"label":"Schritt","text":"Ein Schritt beschreibt einen Zustand des Ablaufs. Solange er aktiv ist, werden die ihm zugeordneten Aktionen nach ihren Bedingungen und Qualifizierungen bearbeitet. Beispiel: Im Schritt „Spannen“ wird das Werkstück eingespannt und die Rückmeldung überwacht."},{"label":"Transition","text":"Eine Transition ist die logische Weiterschaltbedingung zwischen Schritten. Ist der Vorgängerschritt aktiv und die Bedingung erfüllt, kann in den Folgeschritt gewechselt werden. Beispiel: Erst wenn die zulässige Spannrückmeldung vorliegt, folgt „Bearbeiten“. Eine Transition ist keine Aktion."},{"label":"Zwei Vorteile","text":"Der Prozessablauf ist grafisch leichter mit dem tatsächlichen Maschinenablauf zu vergleichen. Zusätzlich lassen sich aktive Schritte, fehlende Bedingungen und Zeitüberschreitungen gezielt diagnostizieren. Parallele oder alternative Abläufe können klar modelliert werden."},{"label":"Busaufgaben","text":"Bussysteme verbinden SPS, dezentrale Ein-/Ausgänge, Antriebe und Bediengeräte. Sie übertragen zyklische Prozesswerte, azyklische Parameter und Diagnosen, reduzieren Einzelverdrahtung und ermöglichen abgestimmte Abläufe. Zeitverhalten und Ausfallreaktion müssen zur Anwendung passen. Sicherheitskommunikation benötigt dafür ausgelegte Protokolle und Komponenten; ein Standardbus ist allein keine Sicherheitsfunktion."}],"mnemonic":"Der Schritt handelt, die Transition erlaubt den Wechsel.","pitfall":"Eine Transition aktiv erzwingen, obwohl die physische Anlage die Weiterschaltbedingung noch nicht erfüllt.","keywords":["Schrittkette","GRAPH","SFC","Transition","Prozessdaten","Diagnose"],"sources":[{"label":"Siemens: S7-GRAPH-Handbuch – Schritte und Transitionen","url":"https://support.industry.siemens.com/cs/attachments/1137630/Graph7_e.pdf"},{"label":"PI: PROFIBUS-Installationsrichtlinien","url":"https://www.profibus.com/download/profibus-installation-guidelines"}],"minutes":4,"pdfPage":61},{"id":"E41","title":"Online-Diagnose gezielt nutzen","category":"Automation","question":"Was bringt eine Onlineverbindung zur SPS? Erläutern Sie drei Diagnoseaufgaben und begründen Sie, warum diese Werkzeuge bei modernen Anlagen besonders wichtig sind.","answer":[{"label":"Vorteil der Onlineverbindung","text":"Die Engineering- oder Diagnosesoftware kann den tatsächlichen Zustand der Steuerung auslesen. Betriebszustand, Baugruppenmeldungen, aktuelle Variablen und Programmstatus helfen, eine Vermutung mit realen Daten zu vergleichen. Zugriffsrechte, sichere Verbindung und Freigaben der Anlage bleiben dabei maßgeblich."},{"label":"Aufgabe 1: Ereignisse auswerten","text":"Diagnosepuffer und Meldungen zeigen Fehler mit Zeitbezug, etwa Baugruppenausfall, Kommunikationsabbruch oder einen CPU-STOP. Reihenfolge und Randbedingungen helfen, Ursache und Folge zu unterscheiden."},{"label":"Aufgabe 2: Signalweg verfolgen","text":"Statusanzeigen und Beobachtungstabellen zeigen, ob ein Eingang ankommt, eine Verriegelung erfüllt ist und ein Ausgang im Programm angesteuert wird. Die elektrische oder mechanische Wirkung muss separat geprüft werden; ein TRUE im Programm beweist keine reale Bewegung."},{"label":"Aufgabe 3: Verläufe und Netzwerk prüfen","text":"Tracefunktionen zeichnen Signalverläufe auf, um kurze oder sporadische Ereignisse sichtbar zu machen. Geräte-/Netzdiagnose kann ausgefallene Teilnehmer, Portzustände und Topologieabweichungen eingrenzen. Online-/Offline-Vergleich hilft, unpassende Projektstände zu erkennen."},{"label":"Warum wichtiger geworden?","text":"Vernetzte Systeme, viele Softwarefunktionen und zeitkritische Wechselwirkungen sind mit Sichtkontrolle allein schwer zu verstehen. Gute Diagnose senkt Suchzeiten und unterstützt vorbeugende Instandhaltung. Steuern oder Forcen kann reale Bewegungen auslösen und ist nur in einem fachlich freigegebenen Prüfverfahren zulässig."}],"mnemonic":"Erst beobachten, dann Ursache belegen, danach kontrolliert ändern.","pitfall":"Eine beobachtete Programmansteuerung mit einer tatsächlich vorhandenen Spannung oder Bewegung gleichsetzen.","keywords":["Online","Diagnosepuffer","Beobachten","Trace","Netzdiagnose","Projektvergleich"],"sources":[{"label":"Siemens: Systemdiagnose S7-1500","url":"https://support.industry.siemens.com/cs/attachments/59192926/s71500_diagnosis_function_manual_en-US_en-US.pdf"},{"label":"Siemens: Diagnosemöglichkeiten in STEP 7","url":"https://docs.tia.siemens.cloud/r/simatic_s7_1500_et_200mp_manual_collection_enus_21/device-specific-information/communication-modules/simatic-cm-1542-5/diagnostics-and-upkeep/diagnostics/diagnostics-options?contentId=ef79iyH~W3vvvQiD_rZY9g"}],"minutes":4,"pdfPage":62},{"id":"E42","title":"Visualisierungsfehler und digitale Unterstützung","category":"Automation","question":"Wie grenzen Sie ein dunkles HMI und falsche Anzeigewerte ein? Welche Aufgaben erfüllt industrielle Bildverarbeitung, und welchen Nutzen kann ein abgesicherter mobiler Anlagenzugang bieten?","answer":[{"label":"Dunkles Display","text":"Zuerst prüfen, ob nur Energiesparmodus, Helligkeit oder Bildschirmschoner aktiv sind. Danach Gerätestatus und Versorgung einschließlich vorgesehener Sicherung durch zuständige Fachkräfte überprüfen. Bei laufendem Gerät kommen Hintergrundbeleuchtung oder Display als Ursache infrage; bei fehlendem Start auch Netzteil oder Hardware. Nach Befund Einstellungen korrigieren, Versorgung instand setzen oder das freigegebene Ersatzgerät mit gesichertem Projektstand einsetzen."},{"label":"Anzeigewert passt nicht","text":"Den Weg Sensor → Eingangsmodul → SPS-Wert → HMI-Variable vergleichen. Häufige Ursachen sind Kommunikationsunterbrechung und veraltete Werte, falsche Adresse, Datentyp oder Skalierung, vertauschte Einheit sowie ein unpassender Projektstand. Verbindungsstatus, Zeitstempel und Rohwert prüfen; anschließend die nachgewiesene Ursache korrigieren und mit einem bekannten Referenzzustand kontrollieren."},{"label":"Kamerasysteme","text":"Digitale Bildverarbeitung kann Bauteile lokalisieren, Vollständigkeit oder Oberflächenfehler prüfen, Abmessungen messen sowie Codes oder Schrift lesen. Sie liefert schnell wiederholbare Prüfergebnisse und kann die Rückverfolgbarkeit verbessern. Beleuchtung, Optik, Kalibrierung und geeignete Auswertung bestimmen die Zuverlässigkeit."},{"label":"Mobilgeräte","text":"Freigegebene Meldungen, Zustände und Wartungsinformationen erreichen zuständiges Personal schneller; ein Fernzugriff kann die Diagnose unterstützen. Rollenrechte, verschlüsselte beziehungsweise abgesicherte Zugänge und aktuelle Daten sind notwendig. Eine Mobilanzeige ersetzt keine lokale Sicherheitsfunktion oder die sichere Sicht auf die Anlage."}],"mnemonic":"Bei falschen Werten den ganzen Signalweg prüfen.","pitfall":"Nur das HMI neu starten, obwohl der Sensorfehler oder die falsche Skalierung in der SPS liegt.","keywords":["HMI","Skalierung","Kommunikationsfehler","Bildverarbeitung","Fernzugriff","Referenzwert"],"sources":[{"label":"Siemens: HMI IPC477C – Fehlerdiagnose, dunkles Display","url":"https://cache.industry.siemens.com/dl/files/499/37443499/att_108164/v1/hmi_ipc477C_operating_instructions_en-US_en-US.pdf"},{"label":"SICK: Aufgaben industrieller Bildverarbeitung","url":"https://cdn.sick.com/media/docs/2/22/322/Whitepaper_SICK_AG_Whitepaper_Select_the_best_technology_for_your_vision_application_en_IM0063322.PDF"},{"label":"Phoenix Contact: Industrielle Kommunikation und Übertragungsmedien","url":"https://www.phoenixcontact.com/en-au/products/industrial-communication"}],"minutes":4,"pdfPage":62},{"id":"E43","title":"Roboterkoordinaten und Achsantriebe","category":"Automation","question":"Welche Koordinatensysteme unterstützen das Roboterprogrammieren? Nennen Sie mindestens vier Anforderungen an einen Achsantrieb und vergleichen Sie elektrische, hydraulische und pneumatische Antriebskonzepte.","answer":[{"label":"Koordinatensysteme","text":"Weltkoordinaten beschreiben die Zelle, Basiskoordinaten den Bezug zum Roboterfuß. Werkstück-/Benutzerkoordinaten beziehen Positionen auf Werkstück oder Vorrichtung, Werkzeugkoordinaten auf das Werkzeug und dessen TCP. Achskoordinaten geben die einzelnen Gelenkwinkel beziehungsweise linearen Achspositionen an. Bezeichnungen und Voreinstellungen unterscheiden sich je nach Hersteller."},{"label":"Vier zentrale Anforderungen","text":"Ein Achsantrieb benötigt ausreichendes Drehmoment beziehungsweise Kraft für Last und Beschleunigung, hohe Regel- und Positioniergüte, passende Geschwindigkeit und Dynamik sowie zuverlässigen Dauerbetrieb. Zusätzlich sind geringe bewegte Masse, passende Steifigkeit/Spiel, Energieeffizienz und sichere Zustände bei Fehlern wichtig."},{"label":"Elektrischer Antrieb","text":"Industrieroboter verwenden heute überwiegend geregelte elektrische Servoantriebe mit Positionsrückführung. Die Bewegung wird direkt oder über Getriebe auf die Achse übertragen. Die Steuerung regelt Strom/Drehmoment, Geschwindigkeit und Lage abgestimmt."},{"label":"Weitere Konzepte","text":"Hydraulische Antriebe erreichen hohe Kraft- beziehungsweise Leistungsdichte, benötigen aber ein Hydrauliksystem und sorgfältige Leckage-/Wartungsbeherrschung. Pneumatische Antriebe sind für einfache, schnelle Bewegungen und Greifer verbreitet; wegen der Kompressibilität der Luft ist präzise geregelte Bewegung anspruchsvoller. Diese Energiekonzepte sind von Roboterkinematiken wie SCARA oder Knickarm zu unterscheiden."}],"mnemonic":"Koordinaten geben den Bezug, der Antrieb liefert die Bewegung.","pitfall":"SCARA als Energieart nennen oder hohe Geschwindigkeit ohne Last- und Genauigkeitsanforderung bewerten.","keywords":["Weltkoordinaten","Werkstückkoordinaten","TCP","Servo","Drehmoment","Dynamik"],"sources":[{"label":"ABB RobotStudio: Koordinatensysteme und TCP","url":"https://developercenter.robotstudio.com/api/robotstudio/articles/Concepts/Math/Coordinate-Systems.html"},{"label":"ABB: Robotik und Automatisierungsanwendungen","url":"https://www.abb.com/global/en/areas/robotics"}],"minutes":4,"pdfPage":63},{"id":"E44","title":"Schweißen als Fügeverfahren","category":"Mechanik","question":"Wie entsteht eine Schweißverbindung und welcher Verbindungsart gehört sie an? Nennen Sie je zwei Vorteile und Nachteile sowie zwei Schmelzschweißverfahren.","answer":[{"label":"Prinzip und Verbindungsart","text":"Beim Schweißen werden Werkstoffe durch Wärme und/oder Druck dauerhaft verbunden, mit oder ohne Zusatzwerkstoff. Beim Schmelzschweißen schmilzt der Grundwerkstoff im Fügebereich auf und erstarrt zur Naht. Das Ergebnis ist eine stoffschlüssige, im üblichen Sinn unlösbare Verbindung; Trennen erfordert einen zerstörenden Eingriff."},{"label":"Zwei Vorteile","text":"Gut ausgelegte Schweißverbindungen können hohe Kräfte übertragen und dichte Bauteile ermöglichen. Häufig werden zusätzliche Verbindungselemente und Überlappungen eingespart, sodass leichte und wirtschaftliche Konstruktionen möglich sind."},{"label":"Zwei Nachteile","text":"Der Wärmeeintrag kann Verzug, Eigenspannungen und Gefügeänderungen verursachen. Qualität und Werkstoffeignung verlangen sorgfältige Vorbereitung, qualifiziertes Personal und passende Prüfung; Fehler im Inneren sind nicht immer äußerlich sichtbar. Eine spätere zerstörungsfreie Demontage ist in der Regel nicht möglich."},{"label":"Zwei Schmelzschweißverfahren","text":"Beim MAG-Schweißen schmilzt eine kontinuierlich zugeführte Drahtelektrode ab; ein aktives Schutzgas schützt und beeinflusst den Prozess. Beim WIG-Schweißen brennt der Lichtbogen an einer nicht abschmelzenden Wolframelektrode unter inertem Gas, gegebenenfalls mit getrenntem Zusatzwerkstoff. Beide schmelzen den Grundwerkstoff im Nahtbereich auf."},{"label":"Arbeitsumgebung","text":"Schweißarbeiten erfordern den passenden Schutz gegen Strahlung, heiße Teile, Rauch und Brandgefahr sowie die für das Verfahren qualifizierte Durchführung. Die Erklärung ist keine Anleitung zur selbstständigen Schweißreparatur tragender Teile."}],"mnemonic":"Beim Löten schmilzt das Lot; beim Schmelzschweißen auch der Grundwerkstoff.","pitfall":"Jedes Schweißen als Schmelzen erklären: Es gibt auch Pressschweißverfahren.","keywords":["Schweißen","Stoffschluss","MAG","WIG","Verzug","Wärmeeinflusszone"],"sources":[{"label":"Fronius: WIG-Schweißen, Verfahren und Eigenschaften","url":"https://www.fronius.com/de/schweissen/know-how/schweissverfahren/wig-schweissen"},{"label":"Fronius: MIG/MAG-Schweißen – Grundprinzip und Schutzgase","url":"https://www.fronius.com/de/schweissen/know-how/schweissverfahren/mig-mag-schweissen"}],"minutes":4,"pdfPage":63},{"id":"E45","title":"Roboterhaltebremse und Werkzeugnullpunkt","category":"Automation","question":"Welche Aufgabe hat die Haltebremse einer Roboterachse und wie wirkt sie typischerweise? Wozu dienen die verschiedenen Koordinatenbezüge und wie heißt der Ursprung des Werkzeugkoordinatensystems?","answer":[{"label":"Aufgabe der Haltebremse","text":"Sie hält eine bereits stillgesetzte Achse gegen unbeabsichtigtes Verdrehen, insbesondere durch Schwerkraft. Sie ist im Regelfall keine Betriebsbremse zum regelmäßigen Abbremsen laufender Achsbewegungen. Diese Verzögerung übernimmt normalerweise der geregelte Antrieb; mögliche Notbremsfälle und Grenzen sind herstellerabhängig."},{"label":"Typische Eigenschaften","text":"Oft ist die Bremse federbetätigt und wird elektrisch gelüftet: Ohne Freigabe beziehungsweise Energie fällt sie ein. Zulässiges Haltemoment, Verschleiß und Funktionsprüfung sind zu beachten. Eine Haltebremse ist nicht automatisch eine vollständige sichere Lastsicherung; bei Arbeiten unter einer gefährdeten Achse sind die vorgesehenen zusätzlichen Maßnahmen nötig."},{"label":"Zweck der Koordinatensysteme","text":"Sie geben an, worauf Positionen, Richtungen und Orientierungen bezogen sind. Ein Werkstückbezug erleichtert die Anpassung an eine versetzte Vorrichtung, ein Werkzeugbezug das Bewegen entlang einer Werkzeugrichtung. Korrekt eingemessene Bezüge machen Programme verständlicher und wiederverwendbar."},{"label":"TCP","text":"Der Ursprung des Werkzeugkoordinatensystems heißt Tool Center Point, kurz TCP. Er ist der definierte wirksame Werkzeugpunkt, etwa eine Schweißdrahtspitze oder ein Greifbezugspunkt. Er muss nicht mit dem Roboterflansch zusammenfallen; seine Lage und Orientierung werden gegenüber dem Flansch beschrieben."}],"mnemonic":"Der Antrieb bremst die Bewegung, die Haltebremse hält den Stillstand.","pitfall":"Zum normalen Stoppen die Haltebremse verwenden oder den TCP immer am Flansch annehmen.","keywords":["Haltebremse","Federkraft","Lastsicherung","Werkzeugkoordinaten","TCP","Flansch"],"sources":[{"label":"Siemens: Haltebremse eines Servoantriebs","url":"https://support.industry.siemens.com/cs/attachments/109762402/V90_PTI_1FL6_op_instr_0818_en-US.pdf"},{"label":"ABB RobotStudio: Koordinatensysteme und TCP","url":"https://developercenter.robotstudio.com/api/robotstudio/articles/Concepts/Math/Coordinate-Systems.html"}],"minutes":4,"pdfPage":64},{"id":"E46","title":"Die sechs Bedingungen einer guten Inbetriebnahme","category":"Automation","question":"Was umfasst Inbetriebnahme über das erste Einschalten hinaus? Erläutern Sie die Beiträge von Planung, Montage, Bedienpersonal, Systemkopplung, Aufstellung und standortspezifischen Bedingungen.","answer":[{"label":"Inbetriebnahme","text":"Inbetriebnahme ist das geplante Herstellen, Prüfen und Nachweisen des vorgesehenen funktionsfähigen und sicheren Betriebszustands. Dazu gehören Kontrollen vor dem Start, Parametrierung, Funktions- und Schnittstellenprüfungen, geeignete Probeläufe sowie dokumentierte Übergabe und Freigabe durch die zuständigen Personen."},{"label":"Planungsqualität","text":"Anforderungen, Leistungsdaten, Schutzkonzept, Prüfplan und Schnittstellen müssen vorliegen. Fehlende Festlegungen lassen sich nicht zuverlässig erst beim Einschalten lösen."},{"label":"Montagequalität","text":"Mechanik, Anschlüsse, Medienführung, Erdung und Schutzeinrichtungen müssen den Unterlagen entsprechen. Montagefehler wie Verspannung oder falsche Verdrahtung beeinflussen Funktion und Sicherheit."},{"label":"Qualifikation des Bedienpersonals","text":"Bedienende benötigen verständliche Unterlagen und eine anlagenbezogene Unterweisung. Sie müssen Betriebsarten, zulässige Eingriffe, Störungsreaktionen und Verantwortlichkeiten kennen."},{"label":"Funktionelle Kopplung","text":"Mit vor- und nachgelagerten Anlagen sind Signale, Daten, Takt, Materialfluss und Reaktionen auf Stillstand abzustimmen. Die gemeinsame Sicherheitsfunktion und der Wiederanlauf müssen über die Schnittstellen hinweg geprüft werden."},{"label":"Aufstellungsbedingungen","text":"Untergrund, Tragfähigkeit, Befestigung, Ausrichtung, Zugänglichkeit und Wartungsräume müssen passen. Auch der sichere Materialtransport und Fluchtwege sind Teil der Aufstellung."},{"label":"Standortspezifische Bedingungen","text":"Energie- und Medienqualität, Temperatur, Feuchte, Staub, elektromagnetische Einflüsse und gegebenenfalls besondere Umgebungsgefahren berücksichtigen. Die am Standort geltenden betrieblichen Vorgaben beeinflussen Prüfung und Betrieb."}],"mnemonic":"Planen, montieren, befähigen, koppeln, aufstellen und den Standort prüfen.","pitfall":"Inbetriebnahme mit einem erfolgreichen Einschaltversuch gleichsetzen oder nur die Einzelmaschine ohne ihre Schnittstellen prüfen.","keywords":["Inbetriebnahme","Planung","Montage","Unterweisung","Systemkopplung","Aufstellung"],"sources":[{"label":"Arbeitsinspektion: Prüfungen vor der ersten Inbetriebnahme","url":"https://www.arbeitsinspektion.gv.at/arbeitsschutz/arbeitsmittel/pruefung_arbeitsmittel.html"},{"label":"Arbeitsinspektion: Auswahl und Benutzung von Arbeitsmitteln","url":"https://www.arbeitsinspektion.gv.at/arbeitsschutz/arbeitsmittel/gemeinsame_bestimmungen/definition_allgemeine_vorschriften.html"}],"minutes":4,"pdfPage":64,"imagePage":70,"imagePages":[70]},{"id":"E47","title":"Qualitätsmanagement, TQM und KVP","category":"Automation","question":"Welche Aufgaben erfüllt Qualitätsmanagement, wofür stehen TQM und KVP und wie trägt Qualitätslenkung dazu bei, festgelegte Anforderungen im Prozess einzuhalten?","answer":[{"label":"Qualitätsmanagement","text":"Es richtet Ziele, Zuständigkeiten und Prozesse so aus, dass Produkte und Leistungen festgelegte Kunden- und weitere Anforderungen verlässlich erfüllen. Dazu gehören Qualitätsplanung, Qualitätslenkung, Qualitätssicherung und Verbesserung. Qualität entsteht damit bereits in Entwicklung und Prozessgestaltung."},{"label":"TQM","text":"Total Quality Management ist ein umfassender Führungsansatz. Alle Bereiche und Mitarbeitenden beziehen Qualität in ihre Arbeit ein; Kundenorientierung, Führung, Prozessdenken und fortlaufende Verbesserung gehören zusammen. Es handelt sich nicht nur um die Endkontrolle eines Produkts."},{"label":"KVP","text":"Kontinuierlicher Verbesserungsprozess bedeutet, Abläufe und Ergebnisse regelmäßig in kleinen, nachvollziehbaren Schritten zu verbessern. Ein Beispiel ist die Ursache wiederkehrender Montagefehler zu untersuchen, eine Änderung zu erproben, ihre Wirkung zu messen und eine wirksame Lösung zu standardisieren. PDCA – Plan, Do, Check, Act – unterstützt diesen Ablauf."},{"label":"Ziel der Qualitätslenkung","text":"Qualitätslenkung hält den laufenden Prozess innerhalb festgelegter Anforderungen. Dazu werden geeignete Merkmale überwacht, Abweichungen erkannt und gezielt korrigiert, etwa über Prüfungen, Prozessparameter und Reaktionspläne. Ziel sind stabile Prozesse und konforme Ergebnisse mit wenig Fehlern und Nacharbeit."}],"mnemonic":"Qualität planen, im Prozess lenken, absichern und laufend verbessern.","pitfall":"KVP als gelegentliche große Umstrukturierung oder Qualitätsmanagement ausschließlich als Aufgabe der Prüfabteilung verstehen.","keywords":["Qualitätsmanagement","TQM","KVP","PDCA","Qualitätslenkung","Prozessstabilität"],"sources":[{"label":"ISO: Qualitätsmanagement und fortlaufende Verbesserung","url":"https://www.iso.org/quality-management"},{"label":"ISO: Qualitätssicherung und Qualitätslenkung","url":"https://www.iso.org/quality-management/quality-assurance"}],"minutes":4,"pdfPage":65},{"id":"E48","title":"PROFIBUS-Segmente, Repeater und Busabschluss","category":"Automation","question":"Deuten Sie eine PROFIBUS-Linie mit Steuerung, HMI, Feldgeräten und einem Repeater. Welche Aufgabe übernimmt der Repeater, und warum benötigt jedes elektrische Segment korrekte Busabschlüsse?","answer":[{"label":"Aufbau der Übersicht","text":"Die Darstellung zeigt einen PROFIBUS-Master, ein HMI und mehrere als Slaves bezeichnete Feldgeräte. Der Master koordiniert den Datenaustausch mit den zugeordneten Teilnehmern. Der eingezeichnete RS-485-Repeater verbindet zwei elektrische Bussegmente; die Netzwerkkommunikation läuft über diese Segmentgrenze hinweg."},{"label":"Aufgabe des Repeaters","text":"Er empfängt die elektrischen Signale, bereitet sie auf und sendet sie in das jeweils andere Segment weiter. So lassen sich Leitungslänge und Teilnehmerverteilung innerhalb der erlaubten Netzwerkregeln erweitern. Je nach Gerät trennt er die Segmente galvanisch. Er übersetzt dabei nicht automatisch in ein anderes Busprotokoll."},{"label":"Busabschluss","text":"An beiden physischen Enden jedes RS-485-Segments ist der vorgeschriebene Abschluss zu aktivieren. Er passt die Leitung elektrisch an und verhindert störende Signalreflexionen; bei PROFIBUS stabilisiert das aktive Widerstandsnetzwerk zusätzlich den Ruhepegel. Die dafür erforderliche Versorgung muss vorhanden sein."},{"label":"Wichtige Grenzen","text":"Nicht an jedem Teilnehmer terminieren und nicht nur die beiden äußersten Enden des gesamten Netzes betrachten: Der Repeater erzeugt Segmentgrenzen. Im vereinfachten Bild sind nicht alle erforderlichen Abschlüsse ausführlich dargestellt. Teilnehmerzahl, Baudrate, Segmentlänge, Repeaterzählung und Montage richten sich nach den Gerätedaten und den PROFIBUS-Regeln."}],"mnemonic":"Jedes Segment hat zwei Enden – beide brauchen Abschluss.","pitfall":"Den Repeater als Protokoll-Gateway bezeichnen oder die Terminierung an einer Segmentgrenze vergessen.","keywords":["PROFIBUS","Master","Slave","RS-485","Repeater","Busabschluss"],"sources":[{"label":"Siemens: RS-485-Repeater – Segmente und Busabschluss","url":"https://support.industry.siemens.com/cs/attachments/48598071/rs_485_repeater_manual_en-US_en-US.pdf"},{"label":"PI: PROFIBUS-RS-485-Busabschluss","url":"https://www.profibus.com/fileadmin/media/wbt/WBT_Assembly_V10_Dec06/en/Seiten/2_1_Busabschluss.html"}],"minutes":4,"pdfPage":65,"imagePage":71,"imagePages":[71]}];
